// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 회피
// ==========================================

// ── 곡예사 (acrobat) · 무력 ──────────────────
kJob('acrobat', 'A', [
  { at:'A', t:'복도 — 발목 높이의 어둠',
    x:`복도 바닥 가까이가 어둡다. 불빛이 무릎 위까지만 닿는다. 그 아래는 먹물처럼 고여 있다.<br><br>
    앞서 간 발소리가 어느 지점에서 끊겼다. 걸음이 멎은 소리가 아니다. 발이 바닥에서 들린 소리다. 신발 한 짝이 어둠 위로 떠올랐다가 도로 잠겼다.<br>
    천장으로 배관이 지나간다. 손목 굵기다. 곡예사는 손이 닿는 것을 다 길로 본다.<br><br>
    발밑 어둠에서 손가락 끝 하나가 올라왔다. 발목 높이에서 멈췄다. 기다린다.`,
    o:[
      { l:'① 배관을 잡고 몸을 들어 건넌다.', k:'evade', dc:22, wake:1,
        ok:`뛰어서 배관을 잡았다. 다리를 접어 배에 붙였다. 발목이 어둠에서 한 뼘 위다.<br><br>손을 하나씩 옮겼다. 배관이 이음매마다 조금씩 처진다. 처지기 전에 앞손이 먼저 무게를 받았다. 아래에서 손가락들이 올라온다. 발목 높이까지. 거기서 더는 못 올라온다.<br>복도 끝에서 내렸다. 소리 없이 내렸다.<br><br>내려서서 손바닥을 봤다. 쥐기 전에 손바닥이 먼저 알았다. 어느 이음매가 처질지. 손이 잡을 데를 고르는 게 아니라 잡을 데가 손을 부르는 것 같았다.`,
        ng:`셋째 이음매에서 배관이 꺾였다. 한쪽 손이 빠졌다.<br><br>다리가 내려갔다. 발목이 어둠에 잠겼다. 차다. 손가락 다섯이 발목을 감았다가 당겼다. 남은 손으로 버텼다. 동료가 허리를 안아 올렸다.<br>발목에 손가락 자국이 다섯 줄 남았다. 한 줄이 유난히 길다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, spirit:-18 } },
      { l:'② 무력을 실어 복도 끝까지 한 번에 뛴다.', k:'evade', dc:22, cost:{ might:28 },
        ok:`뒤로 열 걸음 물러났다. 다리에 힘을 모았다. 달렸다. 어둠 앞에서 찼다.<br><br>몸이 낮게 날았다. 무릎 높이 위로. 발밑으로 어둠이 지나간다. 손가락들이 일제히 올라와 빈 데를 쥐었다. 늦었다.<br>복도 끝 문턱에 발뒤꿈치로 내렸다. 문턱만 어둠 위로 솟아 있다.<br><br>돌아보니 어둠 위에 손가락이 풀처럼 서 있다. 이쪽이 지나간 쪽으로 다 누웠다.`,
        ng:`찼는데 바닥이 미끄러웠다. 어둠이 밑창을 붙잡았다.<br><br>반만 날았다. 복도 한가운데에 내렸다. 무릎까지 어둠이다. 손들이 정강이를 기어오른다. 다시 뛰었다. 힘이 남은 데까지.<br>문턱에 배로 걸렸다. 다리를 끌어올렸다. 바짓단이 없다. 양말도 없다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-14 } },
      { l:'③ 발끝으로 어둠을 짚어 손 사이를 고른다.', k:'sense', dc:23,
        ok:`어둠 속에 발끝만 살짝 넣었다. 닿는 데가 있고 안 닿는 데가 있다.<br><br>손가락은 무게가 실리는 데로 온다. 발끝은 무게가 아니다. 그 사이 빈 데를 골라 디뎠다. 한 걸음에 한 번씩 멈췄다.<br>오래 걸렸다. 다 건넜다.<br><br>복도 끝에서 신발을 벗어 털었다. 안에서 손톱 하나가 떨어졌다. 이쪽 손톱이 아니다.`,
        ng:`발끝을 넣은 자리에 손바닥이 있었다. 위를 보고 펼쳐진 손바닥.<br><br>디딘 순간 손이 접혔다. 발을 감쌌다. 다정하게. 뽑아내는 데 온몸을 썼다.<br>발등이 시퍼렇다. 손 모양으로.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-24, spirit:-20 } }
    ] },

  { at:'A', t:'계단통 — 세는 목소리',
    x:`계단이 아래로 감겨 내려간다. 가운데가 뚫렸다. 난간 너머로 아래층 난간이 겹겹이 보인다.<br><br>
    한 칸 내려가면 위에서 누가 센다. 하나. 두 칸이면 둘. 맑은 목소리다. 아이 목소리다.<br>
    열까지 세면 무슨 일이 있는지는 모른다. 지금 일곱이다.<br><br>
    곡예사는 계단을 칸으로 세지 않는다. 난간에서 난간까지 떨어지는 길이로 센다. 한 층이면 한 번이다.`,
    o:[
      { l:'① 난간을 넘어 아래층 계단참으로 떨어진다.', k:'evade', dc:23,
        doom:{ title:'계단통', what:'계단통 위로 끌려 올라갑니다', dc:18, sec:50,
          text:`난간을 넘었다. 아래층 난간을 향해 떨어졌다. 박자는 맞았다.<br><br>손이 난간에 닿기 직전에 몸이 멎었다. 떨어지던 몸이 그 자리에서 멎었다. 뒷덜미에 손이 있다. 위에서 뻗어 내려온 팔이다. 길다. 층을 몇 개 지나 내려왔다.<br>몸이 끌려 올라간다. 한 층. 위에서 센다. 여덟.<br><br>또 한 층. 아홉. 동료들이 아래 난간에서 손을 뻗는다. 발끝이 닿을락 말락 한다.`,
          dieText:`떨어지는 길이로 세면 한 번이었다.<br><br>위에서 세는 쪽은 칸으로 셌다. 열.<br>계단통 맨 위 어둠에서 누가 손뼉을 한 번 쳤다. 그 뒤로는 아무도 세지 않았다.` },
        ok:`난간을 넘었다. 떨어지면서 몸을 틀었다. 바로 아래 난간을 지나 그 아래 난간을 잡았다. 두 층이다.<br><br>위에서 세는 소리가 멎었다. 셈이 안 맞는다. 한 칸도 안 디뎠는데 두 층이 내려갔다.<br>위에서 팔 하나가 내려왔다. 이쪽이 방금 있던 자리를 쥐었다. 빈손이다.<br><br>계단참에 내려섰다. 위에서 다시 센다. 하나. 처음부터.`,
        win:{ exp:24, dream:3 } },
      { l:'② 셈에 맞춰 한 칸씩 내려가되 열째는 딛지 않는다.', k:'steady', dc:22,
        ok:`셈 박자에 맞춰 한 칸씩 디뎠다. 여덟. 아홉.<br><br>아홉째 칸에서 멈췄다. 열째 칸에는 발을 안 올렸다. 계단참까지 건너뛰어 내렸다.<br>위에서 목소리가 머뭇거린다. 아홉…… 아홉…….<br><br>다음 층에서는 처음부터 다시 셌다. 이쪽도 처음부터 아홉까지만 디뎠다. 층마다 그렇게 내려왔다. 다리가 후들거린다. 위에서는 아직 아홉을 센다.`,
        ng:`여덟째 칸이 반 칸이었다. 디딜 데가 짧다.<br><br>발이 미끄러져 아홉째, 열째까지 한꺼번에 내려갔다. 위에서 목소리가 반긴다. 열!<br>위에서 뭔가 떨어졌다. 작은 신발 한 짝이다. 어깨를 스치고 계단통 아래로 떨어졌다. 어깨가 찢어졌다. 한참 뒤에야 바닥 소리가 났다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
    ] },

  { at:'A', t:'들보 — 거꾸로 매달린 것',
    x:`방 천장을 들보 세 줄이 가로지른다. 가운데 들보에 뭔가 거꾸로 매달려 있다.<br><br>
    사람만 하다. 발로 들보를 쥐었다. 팔은 아래로 늘어졌다. 손끝이 바닥에서 한 뼘 위다. 얼굴이 이쪽을 향한다. 눈을 떴는지는 모르겠다. 눈 자리가 너무 매끈하다.<br>
    매달린 것은 아래로 지나가는 것을 잡는다. 곡예사도 그렇게 매달려 봐서 안다. 잡으려고 매달린 적은 없지만.<br><br>
    방을 건너야 한다. 들보 밑이 유일한 길이다.`,
    o:[
      { l:'① 옆 들보로 올라가 같은 높이로 지난다.', k:'evade', dc:22, wake:1,
        ok:`벽 모서리를 차고 옆 들보에 올랐다. 들보 위에 쪼그려 앉았다.<br><br>가운데 들보의 것과 눈높이가 같다. 그것이 고개를 돌렸다. 거꾸로 매달린 얼굴이 바로 앉은 이쪽을 본다. 아래만 보던 것이 옆을 보는 데는 시간이 걸린다.<br>그 시간 동안 들보를 건넜다. 반대편 벽으로 내렸다.<br><br>내려서며 알았다. 높은 데는 도망치는 데가 아니다. 서는 데다. 같은 높이에 서면 위에서 노리던 것도 그냥 맞은편이 된다.`,
        ng:`옆 들보에 올랐는데 들보가 젖어 있었다.<br><br>가운데 쪽으로 미끄러졌다. 매달린 것의 팔이 허리를 감았다. 거꾸로 들어 올렸다. 그것의 얼굴이 코앞이다. 숨을 쉬는데 냄새가 없다.<br>동료가 다리를 잡아당겼다. 둘이 같이 떨어졌다. 등이 바닥을 쳤다. 위에서 그것이 다시 팔을 늘어뜨렸다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-20 } },
      { l:'② 몸을 바닥에 붙이고 굴러서 지난다.', k:'evade', dc:23,
        ok:`바닥에 몸을 붙이고 굴렀다. 손끝과 바닥 사이 한 뼘보다 낮게.<br><br>그것의 손가락이 등을 스쳤다. 옷만 스쳤다. 굴러서 지났다. 반대편 벽에 닿아 일어섰다.<br>돌아보니 그것의 팔이 조금 길어져 있다. 손끝이 바닥에 닿았다.<br><br>다음 사람은 굴러도 안 된다.`,
        ng:`둘째 바퀴에서 등이 들렸다. 손가락이 옷깃에 걸렸다.<br><br>몸이 바닥에서 떠오른다. 옷깃을 찢고 떨어졌다. 목이 긁혔다. 굴러서 마저 지났다.<br>찢긴 옷깃 조각이 위에서 천천히 흔들린다. 그것이 그걸 들여다본다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
    ] },

  { at:'A', t:'문 — 저쪽에서 미는 손',
    x:`문이 하나 있다. 안 열린다. 잠긴 게 아니다. 저쪽에서 누가 민다.<br><br>
    밀면 같은 힘으로 민다. 더 밀면 더 민다. 손잡이를 놓으면 저쪽도 놓는다.<br>
    문 위에 채광창이 있다. 유리가 빠졌다. 어깨 하나 너비다. 곡예사라면 몸을 접어 들어간다.<br><br>
    채광창 너머는 깜깜하다. 문을 미는 손이 몇 개인지는 거기서라면 보일 것이다.`,
    o:[
      { l:'① 채광창으로 몸을 접어 넘는다.', k:'evade', dc:23,
        doom:{ title:'채광창', what:'채광창 안으로 끌려 들어갑니다', dc:18, sec:50,
          text:`문틀을 딛고 올라 채광창에 머리부터 넣었다. 어깨를 접었다. 들어간다.<br><br>가슴까지 들어갔을 때 아래가 보였다. 문 뒤에 사람들이 줄을 섰다. 문에 손바닥을 댄 채로. 맨 앞 하나가 고개를 든다. 그다음 하나도. 다 같이.<br>손이 올라온다. 어깨를, 팔을 쥔다. 안쪽으로 당긴다. 밖에 남은 다리가 문틀에서 미끄러진다.<br><br>허리까지 끌려 들어갔다. 동료들이 발목을 잡았다. 안쪽 손이 더 많다.`,
          dieText:`몸을 접는 법은 안다. 펴려면 자리가 있어야 한다.<br><br>채광창 안쪽에는 자리가 없었다. 손이 있었다.<br>문은 그 뒤로 더 세게 밀린다. 저쪽에서 미는 손이 둘 늘었을 뿐이다.` },
        ok:`채광창에 발부터 넣었다. 머리를 맨 나중에 넣었다. 저쪽을 보기 전에 몸을 먼저 보냈다.<br><br>안쪽 바닥에 내렸다. 문 뒤에 아무도 없다. 문짝에 손바닥 자국만 수십 개다. 아직 따뜻한 것도 있다.<br>안에서 손잡이를 돌렸다. 문이 그냥 열렸다. 동료들이 들어왔다.<br><br>문을 닫는데 손잡이가 묵직하다. 누가 다시 밀기 시작했다. 이번에는 아까 이쪽이 서 있던 쪽에서.`,
        win:{ exp:24, dream:3 } },
      { l:'② 무력을 실어 미는 박자 사이에 문을 밀어젖힌다.', k:'steady', dc:22, cost:{ might:28 },
        ok:`문틀에 발을 걸고 어깨를 문에 댔다. 저쪽이 미는 박자를 셌다. 밀고, 쉬고.<br><br>쉬는 박자에 힘을 다 실었다. 문이 한 뼘 밀렸다. 저쪽 바닥이 미끄러지는 소리가 났다. 맨발 여럿이다.<br>한 뼘이면 된다. 몸을 비틀어 틈으로 빠져나갔다. 동료들이 하나씩 그 틈으로 들어왔다.<br><br>건너와서 보니 아무도 없다. 문 이쪽 바닥에 젖은 맨발 자국만 줄지어 있다. 다 문을 향해 서 있던 자국이다.`,
        ng:`쉬는 박자를 잘못 셌다. 저쪽은 쉬지 않았다.<br><br>힘과 힘이 맞부딪쳤다. 어깨에서 소리가 났다. 문이 이쪽으로 확 밀렸다. 문짝에 얼굴을 맞았다.<br>벌어진 틈으로 손가락 하나가 나와 이쪽 머리카락 한 가닥을 집어 갔다. 문이 다시 닫혔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'A', t:'구멍 위 — 아래서 부르는 이름',
    x:`바닥이 무너진 자리에 들보 하나가 걸쳐 있다. 발바닥 하나 너비다. 건너편까지 열다섯 걸음.<br><br>
    아래는 깜깜하다. 거기서 목소리가 올라온다. 이쪽 이름을 부른다. 동료 목소리다. 그 동료는 뒤에 서 있다. 입을 다물고.<br>
    곡예사는 줄 위에서 아래를 보지 않는다. 눈이 가는 데로 몸이 따라가기 때문이다.<br><br>
    아래 목소리가 한 번 더 부른다. 이번에는 울먹인다.`,
    o:[
      { l:'① 아래를 보지 않고 건넌다.', k:'evade', dc:23, wake:1,
        ok:`건너편 벽에 박힌 못 하나에 눈을 박았다. 그것만 봤다.<br><br>세 걸음, 다섯 걸음. 아래에서 이름이 계속 올라온다. 고개가 내려가고 싶어 한다. 목에 힘을 줬다. 대신 발바닥이 들보를 봤다. 나뭇결, 옹이, 젖은 데. 발바닥이 눈보다 먼저 읽었다.<br>열다섯 걸음. 건너편이다.<br><br>못에서 눈을 떼고 나서야 알았다. 건너는 동안 들보를 한 번도 안 봤다. 볼 필요가 없었다. 발이 보고 있었다.`,
        ng:`아홉째 걸음에서 목소리가 바로 발밑에서 났다. 숨결까지 닿았다.<br><br>고개가 내려갔다. 아래가 보였다. 깜깜한 데 얼굴 하나가 떠 있다. 동료 얼굴이다. 웃는다.<br>몸이 기울었다. 들보를 끌어안았다. 팔이 다 쓸렸다. 기어서 건넜다. 귀에 아직 그 이름이 남았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
      { l:'② 동료와 허리를 줄로 묶고 건넌다.', k:'bond', dc:22,
        ok:`줄로 동료와 허리를 묶었다. 앞뒤로 섰다. 이쪽이 앞이다.<br><br>아래 목소리가 부를 때마다 뒤의 동료가 이쪽 이름을 같이 불렀다. 위에서 부르는 진짜 목소리. 그걸 따라 걸었다.<br>건넜다. 줄을 풀었다. 동료가 쉰 목으로 웃는다.<br><br>아래 목소리는 그다음부터 동료 이름을 부르기 시작했다. 이쪽 목소리로.`,
        ng:`가운데에서 줄이 팽팽해졌다. 뒤에서 당긴다.<br><br>돌아보니 동료가 아래를 보고 있다. 몸이 기운다. 이쪽이 버텼다. 둘 다 들보에 엎드렸다. 줄이 허리를 파고들었다.<br>한참 엎드려 있다가 기어서 건넜다. 동료는 그 뒤로 말이 없다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
      { l:'③ 무력을 실어 들보 밑에 매달려 손으로 건넌다.', k:'steady', dc:22, cost:{ might:30 },
        ok:`들보 밑으로 내려가 두 손으로 매달렸다. 다리는 아래로 늘어뜨렸다.<br><br>아래를 안 보려면 위를 보면 된다. 들보 밑면만 보고 손을 옮겼다. 목소리가 발바닥에 닿는다. 손은 멈추지 않았다.<br>건너편 모서리에 손이 닿았다. 몸을 끌어올렸다.<br><br>손바닥에 나무 가시가 열두 개 박혔다. 하나는 가시가 아니다. 머리카락이다. 아래에서 올라와 손가락에 감겨 있었다.`,
        ng:`반쯤 갔을 때 발목에 무게가 걸렸다.<br><br>아래에서 뭔가 이쪽 다리에 매달렸다. 손이 미끄러진다. 한 손으로 버티고 다른 발로 찼다. 무게가 떨어졌다. 떨어지는 소리는 안 났다.<br>건너편으로 기어올랐다. 팔이 떨려 한참 일어서지 못했다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A', t:'복도 — 옮겨 오는 어둠',
    x:`긴 복도다. 천장 등이 열두 개. 다 켜져 있다. 하나만 꺼졌다.<br><br>
    꺼진 등이 옮겨 온다. 맨 끝에서 이쪽으로. 한 칸씩. 꺼진 칸이 지나간 자리는 다시 켜진다. 꺼진 칸 안에 누가 서 있다. 불이 켜지면 없다.<br>
    꺼진 칸이 지나간 바닥에 발자국이 남는다. 젖은 맨발이다. 다 이쪽을 향했다.<br><br>
    곡예사는 박자를 안다. 꺼진 칸은 셋을 세고 한 칸 온다. 지금 이쪽 앞 세 칸이다.`,
    o:[
      { l:'① 꺼진 칸이 발밑을 지나는 동안 뛰어 있는다.', k:'evade', dc:22,
        ok:`셋을 셌다. 꺼진 칸이 바로 앞 칸으로 왔다. 하나, 둘. 셋에 뛰었다.<br><br>뛴 채로 발밑이 깜깜해졌다. 꺼진 칸이 이쪽 밑을 지나간다. 그 안에 선 것의 정수리가 보였다. 젖은 머리카락이 붙었다. 고개를 들려고 한다.<br>내렸다. 불 켜진 칸이다. 뒤에서 꺼진 칸이 계속 간다. 이쪽이 있던 자리로.<br><br>복도 끝 문을 열기 전에 돌아봤다. 꺼진 칸이 맨 처음 자리에서 멈췄다. 거기 선 것이 이번에는 이쪽을 보고 있다.`,
        ng:`셋에 뛰었는데 꺼진 칸이 둘에 왔다. 박자가 바뀌었다.<br><br>뛴 채로 깜깜해졌다. 내릴 데가 어둠이다. 내렸다. 어깨에 손이 얹혔다. 차고 젖은 손이다. 불이 다시 켜졌다. 손은 없다.<br>어깨에 젖은 손자국이 남았다. 그 자리가 한참 시렸다. 닦아도 마르지 않는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-22 } },
      { l:'② 꺼진 칸에 뛰어들어 단숨에 뚫고 지난다.', k:'evade', dc:23,
        doom:{ title:'꺼진 칸', what:'꺼진 칸과 함께 복도 끝으로 실려 갑니다', dc:18, sec:45,
          text:`꺼진 칸으로 뛰어들었다. 한 걸음이면 빠진다. 불빛이 등 뒤에서 끊겼다.<br><br>깜깜하다. 앞에 누가 서 있다. 젖은 숨이 닿는다. 비켜 가려는데 양팔이 잡혔다. 그것이 이쪽을 안았다. 가볍게. 오래 기다린 사람처럼.<br>꺼진 칸이 움직인다. 이쪽도 같이 실려 간다. 발이 바닥을 긁는다. 한 칸, 또 한 칸. 이쪽이 지나는 칸마다 불이 켜지지 않는다.<br><br>동료들이 불빛 끝에서 손을 뻗는다. 어둠 안까지는 들어오지 못한다.`,
          dieText:`꺼진 칸은 셋을 세고 한 칸 간다.<br><br>복도 끝에 닿았을 때 셀 것이 없어졌다.<br>천장 등이 열두 개 다 켜져 있다. 하나만 꺼졌다. 그 안에 둘이 서 있다.` },
        ok:`꺼진 칸에 뛰어들자마자 앞으로 굴렀다. 서 있는 것의 다리 사이로.<br><br>등 뒤에서 팔이 빈 데를 안았다. 이쪽은 이미 다음 칸이다. 불 켜진 칸.<br>멈추지 않고 문까지 달렸다.<br><br>문 앞에서 숨을 고르는데 뒤에서 꺼진 칸이 방향을 바꿨다. 이쪽으로 온다. 박자가 빨라졌다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A', t:'방 — 늘어진 줄들',
    x:`천장에서 줄이 수십 가닥 늘어졌다. 바닥에 닿지 않는다. 무릎 높이에서 끝난다.<br><br>
    바람이 없다. 줄이 흔들린다. 다 같이, 천천히. 그네처럼.<br>
    곡예사는 흔들리는 줄을 보면 줄 사이의 길을 안다. 줄과 줄이 멀어지는 박자가 있다.<br><br>
    줄 하나만 반대로 흔들린다. 그 줄 끝에 뭔가 묶였다. 작다. 신발 한 짝 같다.`,
    o:[
      { l:'① 줄 사이가 벌어지는 박자에 지난다.', k:'evade', dc:22,
        ok:`줄들이 왼쪽으로 갔다가 돌아오는 박자를 셌다. 돌아오는 순간 사이가 벌어진다. 사람 하나 너비다.<br><br>그 사이로 걸었다. 줄이 어깨 옆을 지난다. 닿지 않는다. 다음 박자, 다음 틈. 방 가운데까지 왔다.<br>반대로 흔들리는 줄이 앞을 막았다. 박자가 다르다. 줄 끝 신발에서 물이 떨어진다.<br><br>그 줄이 멀어지는 박자에 마저 지났다. 문을 나서며 보니 반대로 흔들리는 줄이 하나 늘었다.`,
        ng:`가운데에서 반대 줄과 부딪쳤다.<br><br>줄이 목을 한 바퀴 감았다. 부드럽게. 다른 줄들이 흔들림을 멈췄다. 전부 이쪽으로 기운다.<br>목에서 줄을 풀어냈다. 손가락 껍질이 벗겨졌다. 목에 붉은 줄이 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-18 } },
      { l:'② 반대로 흔들리는 줄만 본다.', k:'gaze', dc:22,
        ok:`반대 줄만 봤다. 줄 끝 매듭이 서툴다. 아무렇게나 감았다. 작은 손이 묶은 매듭이다.<br><br>신발이 아니다. 작은 손이다. 줄을 쥐고 있다. 놓지 않으려고. 그 손이 흔드는 박자가 다른 줄들을 끌고 간다.<br>그 손의 박자만 피해 걸었다. 다른 줄들은 따라갈 뿐이다.<br><br>방을 나왔다. 등 뒤에서 손이 줄을 놓는 소리가 났다. 작게. 뭔가 바닥에 떨어졌다.`,
        ng:`오래 봤다. 줄 끝의 것이 이쪽을 봤다.<br><br>눈이 없는데 봤다. 줄들이 일제히 이쪽으로 흔들렸다. 얼굴에, 팔에 줄이 감긴다. 털어내며 방을 가로질렀다.<br>팔에 줄 자국이 열 줄. 줄무늬처럼 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-16 } }
    ] },

  { at:'A', t:'계단 — 빠진 한 칸',
    x:`계단을 내려간다. 한 칸이 빠졌다. 위 칸과 아래 칸 사이가 깜깜하다.<br><br>
    틈에서 바람이 올라온다. 따뜻하다. 숨결 온도다.<br>
    빠진 칸 밑에서 얼굴 하나가 올려다본다. 계단 밑에 누워서. 눈이 마주쳤다. 깜박이지 않는다.<br><br>
    곡예사에게 한 칸은 아무것도 아니다. 보통은.`,
    o:[
      { l:'① 빠진 칸을 건너뛴다.', k:'evade', dc:22,
        ok:`위 칸에서 아래 칸으로 한 칸을 건넜다. 발끝으로 아래 칸 모서리를 쥐었다.<br><br>건너는 동안 틈 밑의 얼굴이 따라 움직였다. 고개가 돌아간다. 사람 목이 돌아가는 것보다 더.<br>다음 칸, 다음 칸. 계단을 다 내려왔다.<br><br>내려서서 돌아봤다. 빠진 칸이 하나 늘었다. 이쪽이 방금 디딘 칸이다.`,
        ng:`건너는데 틈에서 손이 올라와 발뒤꿈치를 쳤다.<br><br>발이 아래 칸에서 미끄러졌다. 정강이가 모서리에 찍혔다. 다리 하나가 틈으로 빠졌다. 밑에서 숨이 발바닥에 닿았다.<br>뽑아 올렸다. 신발이 없다. 틈 밑에서 신발 끈 푸는 소리가 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-14 } },
      { l:'② 무력을 실어 난간을 짚고 아래층 계단으로 넘는다.', k:'evade', dc:22, cost:{ might:26 },
        ok:`난간을 두 손으로 짚었다. 무력을 팔에 몰았다. 몸을 들어 난간 너머로 넘겼다. 꺾여 내려가는 아래층 계단 위로.<br><br>한 층을 통째로 건너뛰었다. 빠진 칸 위는 지나지도 않았다. 발바닥으로 아래층 계단참을 받았다. 무릎이 소리를 삼켰다.<br>올려다보니 틈에서 얼굴이 고개를 내밀었다. 계단만 보다가 난간 쪽을 보는 데 한참 걸린다.<br><br>난간에 손자국이 찍혀 있다. 이쪽 손이 짚은 자리 바로 옆이다. 이쪽보다 손가락이 길다.`,
        ng:`짚는 순간 난간이 흔들렸다. 녹슨 볼트가 빠졌다.<br><br>넘지 못하고 계단 쪽으로 떨어졌다. 빠진 칸 바로 옆이다. 팔꿈치가 틈에 들어갔다. 밑에서 손가락이 팔꿈치를 쓰다듬었다.<br>빼냈다. 팔꿈치가 깨졌다. 피가 틈으로 떨어졌다. 밑에서 맛보는 소리가 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, spirit:-16 } },
      { l:'③ 빠진 칸 밑을 들여다본다.', k:'gaze', dc:23,
        doom:{ title:'빠진 칸', what:'계단 틈으로 끌려 내려갑니다', dc:18, sec:50,
          text:`무릎을 꿇고 틈을 들여다봤다. 얼굴이 가깝다. 생각보다 가깝다.<br><br>얼굴이 웃는다. 입이 벌어진다. 그 안이 계단처럼 층층이다. 아래로 이어진다.<br>손이 올라와 목덜미를 쥐었다. 당긴다. 어깨가 틈에 걸렸다. 틈은 한 칸 너비다. 사람 하나는 안 들어간다. 그런데 끌려 들어가고 있다.<br><br>가슴이 틈에 걸렸다. 동료가 허리를 잡았다. 밑에서 손이 또 하나 올라온다.`,
          dieText:`한 칸은 아무것도 아니었다.<br><br>사람 하나 들어가기에는 좁았다. 들어가고 나니 넓었다.<br>계단은 그 뒤로 한 칸도 안 빠졌다. 맨 아래 칸이 조금 높아졌을 뿐이다.` },
        ok:`들여다보되 손은 위 칸 모서리를 쥐었다. 언제든 몸을 뺄 수 있게.<br><br>얼굴이 웃었다. 그 입 안이 계단처럼 층층이다. 아래 칸들이 거기로 이어진다. 이 계단은 처음부터 그 입으로 내려가고 있었다.<br>몸을 빼고 일행을 멈췄다. 내려가지 않고 돌아 올라갔다. 다른 계단을 찾았다.<br><br>돌아서는 등 뒤로 아쉬운 숨이 길게 올라왔다.`,
        win:{ exp:24, dream:3, mind:8 } }
    ] },

  { at:'A', t:'장 위 — 내려오라는 손짓',
    x:`높은 장 위에 올라와 있다. 아래로 뭔가 지나가기를 기다리는 중이었다. 지나갔다.<br><br>
    아래에서 동료들이 손짓한다. 내려와. 다 갔어.<br>
    손짓하는 손을 셌다. 하나가 많다. 들어올 때보다 하나가 많다.<br><br>
    곡예사는 높은 데서 오래 버틴다. 아래가 이상하면 더 오래.`,
    o:[
      { l:'① 내려가지 않고 위에서 하나씩 본다.', k:'gaze', dc:22,
        ok:`손짓을 못 본 척하고 하나씩 봤다. 얼굴, 옷, 신발.<br><br>다 아는 얼굴이다. 그런데 하나는 손이 조금 늦다. 손짓이 다른 이들보다 반 박자 늦게 올라간다. 남이 하는 걸 보고 따라 하는 손이다.<br>그 하나를 가리켰다. 동료들이 돌아봤다. 아무도 없다. 하나가 많던 수가 맞아졌다.<br><br>내려갔다. 바닥에 젖은 발자국이 하나 더 있다. 문 쪽으로 가지 않았다. 장 밑으로 들어갔다.`,
        ng:`하나씩 봤는데 다 아는 얼굴이다. 다 똑같이 손짓한다.<br><br>누가 더해진 건지 모르겠다. 오래 봤다. 눈이 따갑다. 손짓이 조금씩 빨라진다.<br>결국 내려갔다. 내려가 보니 수가 맞다. 하나가 어디 갔는지 아무도 모른다. 등 뒤가 계속 서늘하다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-20 } },
      { l:'② 바닥을 딛지 않고 위에서 위로 건너 반대편에 내린다.', k:'evade', dc:23, wake:1,
        ok:`장 위에서 선반으로, 선반에서 문틀로, 문틀에서 맞은편 장으로. 바닥은 한 번도 안 디뎠다.<br><br>아래에서 손짓하던 이들이 이쪽을 따라 고개를 돌린다. 다들 늦게 돌리는데 하나만 바로 돌린다. 바로 돌리는 하나가 가짜다. 위에서 보니 그게 보였다.<br>방 반대편 끝에 내렸다. 진짜 동료들이 이쪽으로 왔다. 하나는 처음 자리에 혼자 남아 손짓만 계속한다.<br><br>바닥을 안 딛고 방 하나를 건넜다. 몸이 그걸 아무렇지 않게 여긴다. 방이 다르게 보이기 시작했다. 벽도 문틀도 선반도 다 디딜 데다. 바닥은 여럿 중 하나일 뿐이다.`,
        ng:`문틀로 건너뛰는데 문틀이 썩어 있었다.<br><br>문틀째 떨어졌다. 손짓하던 이들 한가운데로. 동료들이 이쪽을 일으켜 세운다. 하나는 발목을 쥐고 안 놓는다.<br>걷어찼다. 손이 떨어졌다. 그 손이 문 밑으로 기어 나갔다. 발목에 손가락 자국이 남았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-18 } }
    ] },

  { at:'A', t:'문턱 너머 — 바닥 없는 떨어짐',
    x:`문을 열고 한 걸음 디뎠다. 바닥이 없다.<br><br>
    떨어진다. 깜깜하다. 위도 아래도 없다. 바람 소리만 난다. 동료들 목소리가 위에서 멀어진다.<br>
    곡예사는 떨어지는 동안 센다. 몸이 저절로 센다. 이만큼이면 무릎으로, 이만큼이면 등으로.<br><br>
    셈이 끝나지 않는다. 아직 떨어진다.`,
    o:[
      { l:'① 세기를 그만두고 몸을 받을 자세로 둔다.', k:'evade', dc:23, wake:1,
        ok:`세는 걸 그만뒀다. 무릎을 조금 굽히고 팔을 벌렸다. 언제 닿아도 받을 자세다.<br><br>바닥이 왔다. 생각보다 빨리. 발바닥, 무릎, 엉덩이, 등. 굴렀다. 한 바퀴 반. 일어섰다. 아무 데도 안 다쳤다.<br>올려다보니 문이 열려 있다. 손 뻗으면 닿는 높이다. 떨어진 건 한 길이었다. 어둠이 그걸 길게 늘였다.<br><br>모르는 높이에서 떨어져도 몸이 받는다. 셈을 몰라도 받는다. 떨어지는 법이 셈보다 깊은 데로 내려가 자리를 잡았다.`,
        ng:`계속 셌다. 셈이 늘어날수록 무서워졌다. 몸이 굳었다.<br><br>굳은 몸으로 닿았다. 발목이 꺾였다. 바닥이 차고 젖었다. 올려다보니 문이 손 닿을 높이다.<br>한 길이었다. 한 길 떨어지면서 쉰을 셌다. 발목이 퉁퉁 붓는다.`,
        win:{ exp:25, dream:3 }, lose:{ hp:-32, mind:-16 } },
      { l:'② 팔을 뻗어 벽을 긁어 잡는다.', k:'sense', dc:22,
        ok:`팔을 옆으로 뻗었다. 벽이 손끝을 스친다. 가깝다. 손톱을 세워 긁었다.<br><br>손가락이 틈에 걸렸다. 몸이 멎었다. 매달렸다. 발밑을 더듬으니 발끝에 바닥이 닿는다. 한 뼘 아래다.<br>내려섰다. 위에서 동료가 문으로 고개를 내민다. 손이 닿는다.<br><br>벽을 긁은 자리에 손톱 자국이 이쪽 것 말고도 많다. 오래된 것, 새것.`,
        ng:`벽을 잡았는데 벽이 물렀다.<br><br>벽이 아니다. 뭔가의 옆구리다. 손이 파묻혔다. 뽑았다. 떨어졌다. 바닥은 한 뼘 아래였다. 엉덩이로 떨어졌다.<br>손바닥이 미끈하다. 씻어도 안 지워진다. 한참 손을 비볐다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-22 } }
    ] },

  { at:'A1', t:'방청석 위 — 카메라 크레인',
    x:`방청석 위로 크레인 팔이 길게 뻗었다. 끝에 카메라가 달렸다. 팔이 천천히 돈다. 방청석 위를 쓸고 지나간다.<br><br>
    카메라 앞 빨간 불이 켜져 있다. 찍는 중이다. 찍히는 건 방청객이다. 방청석은 비었다. 이쪽 일행만 있다.<br>
    크레인 팔 끝은 위층 조정실 창 앞까지 간다. 걸어서 가려면 방청석 계단을 다 올라야 한다. 계단마다 하얀 장갑이 하나씩 앉아 있다.<br><br>
    곡예사는 움직이는 것에 올라타는 법을 안다. 그네든 크레인이든.`,
    o:[
      { l:'① 크레인 팔에 매달려 방청석 위를 건넌다.', k:'evade', dc:23,
        doom:{ title:'크레인', what:'크레인 팔에 실려 무대로 갑니다', dc:18, sec:50,
          text:`팔이 머리 위를 지날 때 뛰어 잡았다. 매달렸다. 방청석이 발밑으로 흐른다.<br><br>조정실 창 앞에서 놓으려는데 카메라가 돌아섰다. 렌즈가 이쪽을 본다. 빨간 불이 코앞이다. 스피커에서 노래 언니가 반긴다. 어머, 우리 친구가 하늘을 나네!<br>크레인이 방향을 바꿨다. 무대 쪽으로. 손을 놓으려는데 안 떨어진다. 손등 위에 하얀 장갑이 얹혔다. 손가락 넷이 꽉 쥐었다.<br><br>무대 쪽으로 실려 간다. 조명이 가까워진다. 박수가 쏟아진다.`,
          dieText:`움직이는 것에 올라타는 법은 안다. 내리려면 그쪽이 놓아줘야 할 때가 있다.<br><br>방송은 그날도 다섯 시에 나갔다.<br>화면 위쪽에서 누가 크레인에 매달려 손을 흔든다. 장갑 낀 손이다.` },
        ok:`팔이 지날 때 잡고 매달렸다. 카메라 뒤쪽이다. 렌즈에 안 걸리는 자리.<br><br>카메라는 앞만 찍는다. 등 뒤에 매달린 것은 화면에 없다. 화면에 없는 것은 방청객이 아니다.<br>조정실 창 앞에서 손을 놓았다. 창틀에 내렸다. 소리 하나 안 났다.<br><br>창 너머 모니터에 방청석이 나온다. 비었다. 맨 앞줄에만 누가 앉아 이쪽을 향해 손을 흔든다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 무력을 실어 크레인 축을 붙잡아 멈춰 세운다.', k:'steady', dc:22, cost:{ might:30 },
        ok:`크레인 받침대로 가서 돌아가는 축을 두 팔로 붙잡았다. 힘을 다 실었다.<br><br>축이 멈췄다. 크레인 팔이 방청석 계단 위에서 섰다. 카메라가 계단을 내려다본다. 계단에 앉은 장갑들이 찍힌다. 장갑들이 렌즈를 올려다본다. 찍히는 쪽이 된 걸 안다. 꼼짝을 안 한다.<br>그 사이 일행이 계단을 올랐다.<br><br>마지막에 축을 놓았다. 크레인이 다시 돈다. 이쪽은 뛰어서 계단을 올랐다. 팔이 한참 떨렸다.`,
        ng:`축을 잡았는데 축이 더 셌다.<br><br>팔이 꺾이며 몸이 축에 감겼다. 크레인이 한 바퀴 돌 때 같이 돌았다. 받침대 쇠에 갈비가 긁혔다.<br>놓고 떨어졌다. 카메라가 그 장면을 찍었다. 스피커에서 웃음소리가 났다. 녹음이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] },

  { at:'A1', t:'놀이 세트 — 미끄럼틀 탑',
    x:`놀이 세트 가운데 미끄럼틀 탑이 섰다. 색칠한 합판이다. 빨강, 노랑, 파랑. 꼭대기에 깃발.<br><br>
    미끄럼틀은 통이다. 안이 깜깜하다. 출구가 세트 밑으로 들어간다. 무대 바닥 아래로. 통 안에서 웃음소리가 내려간다. 끝나지 않는다.<br>
    탑 꼭대기에서 건너편 세트 지붕으로 다리가 놓였다. 그쪽이 다음 문이다. 계단은 탑 안에 있다. 안에도 웃음이 산다.<br><br>
    바깥 기둥은 칠이 벗겨졌다. 손가락 걸 데가 있다.`,
    o:[
      { l:'① 탑 바깥 기둥을 타고 오른다.', k:'evade', dc:22, wake:1,
        ok:`기둥을 손가락으로 쥐고 발로 밀었다. 합판 이음매가 사다리처럼 이어진다. 보통 눈에는 안 보이는 사다리다.<br><br>오르는 동안 탑 안 계단에서 작은 발소리가 같이 올라온다. 이쪽 높이에 맞춰. 합판 한 장 사이다. 판 틈으로 눈 하나가 보였다.<br>꼭대기에 먼저 닿았다. 깃대를 잡고 다리로 건넜다. 등 뒤에서 탑 안 발소리가 꼭대기에 닿아 멈췄다.<br><br>오르는 내내 손이 기둥을 움켜쥐지 않았다. 얹기만 했다. 힘을 빼고 오르는 길을 손이 혼자 찾았다. 쥐는 힘이 남으니 끝에서도 숨이 남는다.`,
        ng:`다섯째 이음매가 손에서 떨어져 나왔다. 합판이 썩었다.<br><br>탑 옆구리에 몸이 붙었다. 판 틈으로 손이 나와 손목을 쥐었다. 하얀 장갑이다. 손가락 넷.<br>뿌리치고 미끄러져 내려왔다. 처음 자리다. 손목에 하얀 실밥이 붙어 있다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20 } },
      { l:'② 미끄럼틀 통 등을 밟고 거꾸로 오른다.', k:'evade', dc:23,
        ok:`통 바깥, 둥근 등 위에 올라섰다. 미끄럼틀을 거꾸로 걸어 올랐다. 발바닥을 넓게 디뎠다.<br><br>발밑 통 안으로 웃음이 내려간다. 이쪽 발바닥 밑을 지날 때마다 웃음이 잠깐 멎는다. 위에 누가 있는 걸 안다.<br>꼭대기에 닿았다. 다리를 건넜다.<br><br>건너편에서 돌아보니 미끄럼틀 출구에서 뭔가 기어 나왔다가 도로 들어간다. 이쪽이 안 내려오니 데리러 나왔던 것이다.`,
        ng:`통 위 칠이 미끄러웠다. 반쯤 오르다 미끄러졌다.<br><br>통 등을 타고 끝까지 내려왔다. 출구 바로 앞에 섰다. 출구에서 웃음이 쏟아졌다. 얼굴 앞에서.<br>뒷걸음질 쳤다. 발목을 장갑이 스쳤다. 그 웃음이 한참 귀에서 안 빠졌다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-18, spirit:-22 } },
      { l:'③ 이음매를 짚어 주며 동료를 먼저 올린다.', k:'bond', dc:22,
        ok:`이음매 사다리를 손가락으로 짚어 보여 줬다. 여기, 여기, 여기. 동료들이 하나씩 올랐다. 이쪽은 아래에서 발을 받쳤다.<br><br>맨 나중에 이쪽이 올랐다. 다들 꼭대기에서 손을 내밀었다. 잡고 올랐다.<br>깃대 밑에 사탕 상자가 있었다. 촬영 소품이다. 열어 보니 꿀이 굳어 있다. 진짜다.<br><br>탑 안 계단의 발소리는 이쪽이 모두 다리를 건넌 다음에야 꼭대기에 닿았다.`,
        ng:`둘째 동료가 오를 때 이음매가 떨어졌다. 동료가 이쪽 위로 떨어졌다.<br><br>둘이 같이 바닥에 깔렸다. 미끄럼틀 출구 바로 앞이다. 출구 안에서 웃음이 나온다. 손이 나온다.<br>동료를 끌고 굴러서 피했다. 이쪽 등이 먼저 바닥에 갈렸다.`,
        win:{ exp:16, dream:1, item:'꿀 한 줌' }, lose:{ hp:-28, mind:-14 } }
    ] },

  { at:'A1', t:'스튜디오 — 서커스 날 회차',
    x:`스튜디오 한쪽 모니터에 옛날 회차가 나온다. 「방글 동산 — 서커스 날」.<br><br>
    화면 속에서 작은 아이가 줄을 탄다. 아래에서 방글이가 손뼉을 친다. 아이가 다 건너자 박수가 쏟아진다. 아이가 고개를 숙였다가 든다. 든 얼굴에 그려 넣은 입이 웃는다.<br>
    화면 밖, 이쪽 앞에도 줄이 걸려 있다. 방청석 위를 건너 위층 난간까지. 화면 속 줄과 같은 줄이다. 매듭까지 같다.<br><br>
    스피커에서 박수가 미리 난다. 기다린다.`,
    o:[
      { l:'① 줄을 탄다. 끝에서 고개는 숙이지 않는다.', k:'evade', dc:23, wake:1,
        ok:`줄에 올랐다. 박수가 커진다. 들리는 대로 뒀다. 박수에 맞춰 걸으면 박수가 발을 쥔다. 이쪽 박자로 걸었다.<br><br>가운데에서 줄이 흔들렸다. 밑에서 누가 줄을 튕겼다. 흔들림을 무릎으로 받았다. 다시 고요해졌다.<br>건너편 난간에 닿았다. 박수가 쏟아진다. 인사하라고. 숙이지 않았다. 등을 돌려 문으로 갔다. 박수가 어색하게 멎었다.<br><br>무대 위 곡예는 인사로 끝난다. 인사가 없는 곡예를 오늘 처음 했다. 보는 눈을 발밑에서 떼어 내니 줄이 땅보다 넓었다. 줄 위에 이쪽 혼자만 남는 법을 알았다.`,
        ng:`가운데에서 박수가 박자를 바꿨다. 발이 그 박자를 따라갔다.<br><br>틀린 박자다. 발이 줄에서 빠졌다. 줄을 겨드랑이에 끼고 매달렸다. 스피커에서 아이들이 아아 하고 탄식한다. 녹음이다.<br>기어서 건넜다. 겨드랑이가 쓸려 피가 났다. 건너편에서 고개가 저절로 숙여졌다. 숙이고 나서야 알았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
      { l:'② 줄 밑 방청석 사이로 엎드려 지난다.', k:'hide', dc:22,
        ok:`방청석 의자 사이로 엎드려 기었다. 줄이 머리 위에 있다. 줄 위에 아무도 없으니 박수가 기다린다.<br><br>기다리는 박수는 오래 간다. 그 사이 위층 계단까지 기었다. 아무도 이쪽을 안 찾았다. 다들 줄을 본다.<br>계단에 닿아 돌아봤다. 줄 위에 누가 올라섰다. 작은 아이다. 화면 속 그 아이다. 이쪽 대신.<br><br>박수가 쏟아졌다.`,
        ng:`의자 밑에 장갑이 있었다. 여럿이다.<br><br>장갑들이 옷을 잡고 위로 밀어 올렸다. 줄 쪽으로. 의자를 붙잡고 버텼다. 팔꿈치가 의자 다리에 찍혔다.<br>장갑들이 놓았다. 박수가 실망한다. 의자 밑에서 작게 손뼉 치는 소리가 났다. 이쪽에게 치는 박수가 아니다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } }
    ] },

  { at:'A1', t:'방청석 — 일어나지 않기',
    x:`방청석을 가로질러야 한다. 통로 계단마다 하얀 장갑들이 앉아 있다. 손바닥을 무릎에 얹고. 박수 칠 차례를 기다린다.<br><br>
    의자는 비었다. 등받이가 줄줄이 이어진다. 열두 줄. 건너편 출구까지.<br>
    대기실 포스터의 둘째 규칙. 자리에서 일어나지 않기.<br><br>
    곡예사는 등받이 위를 걸을 수 있다. 그건 일어선 걸까, 자리에 있는 걸까.`,
    o:[
      { l:'① 등받이 위를 걸어 건넌다.', k:'evade', dc:22,
        ok:`첫 의자 등받이에 올라섰다. 발끝으로 섰다. 다음 줄 등받이로 건너뛰었다. 하나씩.<br><br>장갑들이 이쪽을 올려다본다. 일어섰는지 앉았는지 정하지 못한다. 발이 의자에 있다. 자리에 있는 것이다.<br>열두 줄을 건넜다. 출구 문틀을 잡고 내렸다.<br><br>돌아보니 장갑들이 하나씩 등받이 위로 올라서 본다. 따라 해 본다. 다들 잘 못 선다.`,
        ng:`일곱째 줄 등받이가 접히는 의자였다.<br><br>등받이가 뒤로 꺾였다. 이쪽은 의자 앞 바닥에 섰다. 장갑들이 일제히 고개를 들었다. 일어섰다.<br>다음 등받이로 뛰어 다시 올랐다. 정강이가 의자 모서리에 찍혔다. 등 뒤에서 박수가 한 번 났다. 딱 한 번.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-18 } },
      { l:'② 의자 밑으로 엎드려 기어간다.', k:'hide', dc:23,
        doom:{ title:'방청석 밑', what:'의자 밑에서 무대 쪽으로 끌려갑니다', dc:18, sec:50,
          text:`의자 밑으로 들어가 엎드렸다. 일어나지 않았다. 자리보다도 낮다.<br><br>세 줄쯤 기었을 때 발목이 잡혔다. 장갑이다. 손가락 넷. 하나는 발목, 하나는 무릎. 의자 밑에도 앉은 것들이 있었다. 낮게.<br>무대 쪽으로 끌려간다. 의자 다리마다 어깨가 부딪힌다. 한 줄, 또 한 줄. 손으로 의자 다리를 잡았다. 장갑이 손가락을 하나씩 편다.<br><br>스피커가 반긴다. 친구야, 자리가 거기가 아니잖아.`,
          dieText:`일어나지는 않았다. 끝까지.<br><br>무대 맨 앞에 낮은 의자가 하나 더 놓였다. 아이 엉덩이 크기다.<br>거기 앉은 것이 박수를 아주 크게 친다.` },
        ok:`의자 밑에 들기 전에 바닥부터 봤다. 의자 밑마다 장갑이 하나씩 엎드려 있다. 그래서 의자 다리가 박힌 쇠 레일을 따라 기었다. 장갑 손이 닿지 않는 쇠 위로.<br><br>장갑들이 레일 양옆에서 손을 뻗었다가 쇠에 닿자 거둔다. 찬 것은 싫어한다.<br>출구 앞에서 일어섰다. 그 순간 방청석 전체가 고개를 돌렸다.<br><br>일어선 데는 출구 밖이었다. 한 발 차이였다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 무력을 실어 맨 뒷벽 쇠봉에 매달려 돈다.', k:'evade', dc:22, cost:{ might:28 },
        ok:`방청석 맨 뒷벽에 쇠봉이 가로질렀다. 안내판을 달던 봉이다. 뛰어 잡고 몸을 올렸다.<br><br>쇠봉을 타고 옆으로 옮겼다. 손발 넷이 다 바빴다. 아래 방청석이 내려다보인다. 의자는 비었다. 의자 밑은 안 비었다.<br>건너편 끝에서 출구 위로 내렸다.<br><br>쇠봉에서 손을 떼니 손바닥에 하얀 털이 붙어 있다. 장갑 털이다. 누가 먼저 이 봉을 잡았었다.`,
        ng:`쇠봉 이음새에서 나사가 빠졌다.<br><br>봉이 기울며 이쪽을 방청석으로 떨어뜨렸다. 맨 뒷줄 의자 위로. 앉은 자세로 떨어졌다. 허리가 쇠 팔걸이에 찍혔다.<br>앉았다. 규칙대로. 장갑들이 흡족한 듯 무릎에 손을 얹는다. 일어나는 데 한참 걸렸다. 일어서자 다들 돌아봤다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A1', t:'조명 다리 — 위에서 본 동산',
    x:`스튜디오 천장 밑으로 조명 다리가 지나간다. 쇠 발판이다. 난간이 낮다. 조명들이 매달렸다. 뜨겁다.<br><br>
    아래가 동산 세트다. 위에서 보니 동산이 아니다. 풀밭 그림 사이로 네모난 바닥 문이 여럿이다. 무대로 불려 나온 아이가 서는 자리마다.<br>
    세트 가장자리에 삐뚤이가 서 있다. 파란 목이 길다. 고개를 숙인 채다. 숙인 목이 조금씩 위로 펴진다.<br><br>
    조명 다리 끝에 위층으로 가는 점검 사다리가 있다. 곡예사만 거기까지 간다.`,
    o:[
      { l:'① 발판 이음새만 디디며 조명 다리를 건넌다.', k:'evade', dc:23,
        ok:`발판 위를 걸었다. 쇠가 울리지 않게 이음새만 디뎠다.<br><br>삐뚤이의 목이 펴진다. 위로, 위로. 부리가 조명 다리 밑까지 왔다. 발판 틈으로 부리 끝이 보인다. 찾는다. 소리를 찾는다.<br>이음새만 디뎠다. 소리가 없다. 부리가 엉뚱한 발판을 쪼았다.<br><br>사다리에 닿았다. 내려다보니 삐뚤이가 고개를 꺾어 이쪽을 올려다본다. 처음부터 소리가 아니라 조명에 비친 그림자를 보고 있었다.`,
        ng:`발판 하나가 헐거웠다. 덜컥.<br><br>부리가 발판 틈으로 올라왔다. 발목 옆 쇠를 물었다. 쇠가 휘었다. 발을 뺐다. 신발 뒤축이 뜯겼다.<br>뛰어서 사다리까지 왔다. 발뒤꿈치가 찢어졌다. 피가 발판 틈으로 떨어진다. 밑에서 부리가 그걸 받는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-18 } },
      { l:'② 무력을 실어 조명 하나를 비틀어 떨어뜨린다.', k:'break', dc:22, cost:{ might:28 },
        ok:`조명 고리를 손으로 쥐었다. 쇠고리가 뜨겁다. 무력을 실어 비틀었다. 조명이 떨어졌다.<br><br>삐뚤이 바로 앞이다. 유리가 터지고 불꽃이 튄다. 삐뚤이가 목을 접었다. 세트 뒤로 물러났다.<br>그 틈에 조명 다리를 뛰어 건넜다. 발판이 울렸다. 아무것도 안 쫓아왔다.<br><br>손바닥에 고리 자국이 데었다. 아래에서 녹음된 아이들이 우와 한다.`,
        ng:`고리가 안 풀렸다. 비트는 사이 손바닥이 익었다.<br><br>조명이 떨어지지 않고 기울었다. 불빛이 이쪽을 비췄다. 세트 위에 이쪽 그림자가 크게 떴다. 삐뚤이가 그 그림자를 봤다. 목이 단번에 올라왔다.<br>부리가 난간을 물었다. 손 한 뼘 옆이다. 뛰었다. 데인 손바닥이 터졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'A2', t:'종탑 — 젖은 종줄',
    x:`종탑 안이다. 아래로 가는 나선 계단은 스무 칸 밑에서 물에 잠겼다.<br><br>
    위에 창이 하나 있다. 그 창으로 나가면 기숙사 지붕으로 건너간다. 물을 안 거치는 길이다. 위로 가는 나무 계단은 썩어 무너졌다.<br>
    남은 건 종줄이다. 굵은 밧줄이 종에서 내려와 물속으로 들어간다. 위쪽 반만 말랐다.<br><br>
    곡예사는 줄을 타기 전에 줄 끝이 어디 묶였는지 본다. 이 줄 끝은 물속이다. 벽 시계는 여섯 시 오십육 분이다.`,
    o:[
      { l:'① 종줄을 타고 오른다.', k:'evade', dc:23,
        doom:{ title:'종줄', what:'종줄에 감겨 물속으로 끌려 내려갑니다', dc:18, sec:45,
          text:`종줄을 손에 감아 쥐고 올랐다. 다리로 줄을 감았다. 반쯤 올랐다.<br><br>시계가 일곱 시를 쳤다. 종이 머리 위에서 울린다. 줄이 아래로 당겨진다. 한 번, 두 번. 당길 때마다 이쪽도 같이 끌려 내려간다. 다리에 감은 줄이 안 풀린다. 오히려 감긴다.<br>세 번, 네 번. 발끝이 물에 닿았다. 무릎. 허리. 물 밑에서 줄을 쥔 손들이 보인다. 작은 손들이 줄을 나눠 쥐었다.<br><br>일곱 번째 종이 울리기 전에 다리를 빼야 한다. 줄이 놓아주지 않는다.`,
          dieText:`줄을 타기 전에 줄 끝을 본다. 봤다. 안 보였다.<br><br>일곱 번째 종이 울렸다. 물속에서 대답이 하나 더 났다. 네.<br>종줄은 다시 위쪽 반만 말랐다.` },
        ok:`종줄을 타고 오르되 다리로 감지 않았다. 손으로만. 다리는 줄에서 뗐다.<br><br>반쯤 올랐을 때 시계가 일곱 시를 쳤다. 줄이 아래로 확 당겨졌다. 손을 놓고 벽 돌틈을 잡았다. 줄이 옆을 지나 물속으로 내려간다. 감았으면 같이 내려갔다.<br>종이 일곱 번 우는 동안 벽에 붙어 있었다. 줄이 멎자 다시 잡고 마저 올랐다. 창에 닿았다.<br><br>창틀에서 내려다봤다. 물 위로 대답이 하나씩 올라온다. 네. 네. 이쪽이 줄을 놓은 자리에서 물결이 오래 맴돈다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 무력을 실어 종탑 벽 돌틈을 짚고 오른다.', k:'evade', dc:22, cost:{ might:30 },
        ok:`종탑 벽은 돌이다. 돌과 돌 사이 틈이 손가락 하나만 하다. 하나면 된다.<br><br>무력을 손끝에 몰았다. 손가락 하나로 몸을 들었다. 발끝도 틈 하나. 그렇게 위로. 종줄은 옆에 늘어져 있다. 한 번도 안 잡았다.<br>일곱 시 종이 울렸다. 줄이 아래로 당겨진다. 이쪽은 벽에 있다. 줄과 상관이 없다.<br><br>창에 닿았다. 손가락 끝이 다 갈라졌다. 창틀 밑에 빗물 받는 양철통이 있다. 고인 물이 맑다. 물 밑이 아니라 하늘에서 온 물이다.`,
        ng:`중간에 돌 하나가 빠져나왔다. 손에 쥔 채로.<br><br>몸이 벽에서 떨어졌다. 종줄을 잡았다. 잡을 수밖에 없었다. 그때 일곱 시 종이 울렸다. 줄이 한 번 당겨졌다. 손바닥이 줄에 쓸리며 미끄러졌다. 놓았다.<br>물로 떨어졌다. 물 밑에서 뭔가 등을 받쳐 올려 줬다. 친절하게. 나와서 오래 떨었다.`,
        win:{ exp:20, dream:2, item:'맑은 물' }, lose:{ hp:-30, spirit:-20 } }
    ] },

  { at:'A2', t:'체육관 — 천장의 링',
    x:`체육관은 천장 바로 밑까지 물이 찼다. 위에 공기가 한 길 남았다.<br><br>
    천장 철골에서 링이 두 개씩 줄줄이 내려왔다. 체조 수업용이다. 링 끝이 수면에 닿았다 떨어졌다 한다. 물속에서 누가 링을 쥐었다 놓는 것처럼.<br>
    건너편 출입문 위 창으로 나가야 한다. 헤엄쳐 가면 물속 줄 사이를 지난다. 줄 선 자리마다 물이 무겁다.<br><br>
    곡예사는 링을 보면 손이 먼저 간다.`,
    o:[
      { l:'① 링에서 링으로 건너간다.', k:'evade', dc:23, wake:1,
        ok:`첫 링을 잡고 몸을 흔들었다. 흔들림 끝에서 다음 링으로. 쥐고, 놓고, 쥔다.<br><br>링 사이에 물이 있다. 다리를 접어 수면에 안 닿게 했다. 밑에서 손가락이 수면 위로 올라와 발끝을 찾는다. 이쪽은 늘 반 박자 먼저 떠났다.<br>마지막 링에서 창틀로 뛰었다. 잡았다. 올라섰다.<br><br>흔들림을 이어 붙이는 동안 한 번도 멈추지 않았다. 멈추지 않으니 밑의 것들이 박자를 못 잡았다. 흔들림이 그대로 길이 됐다. 손잡이가 끊겨도 몸이 다음까지 흔들림을 이어 간다.`,
        ng:`일곱째 링이 무거웠다. 이미 누가 쥐고 있었다. 물 밑에서.<br><br>링이 물속으로 당겨졌다. 이쪽 손도 같이. 팔이 어깨까지 잠겼다. 물속에서 작은 손이 이쪽 손을 쓰다듬었다. 그리고 놓았다.<br>다음 링으로 겨우 건너갔다. 어깨가 빠질 뻔했다. 그 손의 온도가 손등에 남았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-22 } },
      { l:'② 물속 평균대를 더듬어 딛고 간다.', k:'sense', dc:22,
        ok:`체육관 바닥 어딘가에 평균대가 있을 것이다. 발끝으로 더듬었다. 한 길 밑에 딱딱한 것. 평균대다.<br><br>평균대 위를 걸었다. 물이 가슴까지 온다. 양옆 물이 무겁다. 줄 선 자리다. 평균대는 줄과 줄 사이로 놓였다. 줄에 끼지 않았다.<br>끝에서 뜀틀을 딛고 창틀에 손을 걸었다.<br><br>평균대 끝에 실내화 한 짝이 놓여 있었다. 누가 벗어 두고 갔다. 뒤꿈치가 꺾여 있다.`,
        ng:`평균대가 중간에 끊겼다. 발이 빈 물을 디뎠다.<br><br>물속으로 잠겼다. 양옆 줄이 이쪽을 받았다. 줄을 맞춰 세웠다. 앞사람 등이 차갑다. 뒷사람 손이 이쪽 어깨를 짚었다. 앞으로나란히.<br>물을 차고 올라왔다. 숨을 몰아쉬었다. 어깨에 손 모양 멍이 들었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
      { l:'③ 무력을 실어 천장 철골에 올라 기어간다.', k:'evade', dc:22, cost:{ might:28 },
        ok:`링을 잡고 몸을 끌어올려 철골에 올랐다. 철골 위에 엎드렸다. 공기 한 길 중 맨 위다.<br><br>기었다. 철골이 녹슬어 손바닥에 가루가 묻는다. 밑의 수면이 이쪽을 비춘다. 이쪽 밑에서 이쪽이 기어간다. 수면 속 이쪽이 조금 느리다.<br>창 위 철골에서 내려 창틀에 닿았다.<br><br>수면을 돌아봤다. 수면 속에서 이쪽이 아직 기어가고 있다. 반쯤 왔다.`,
        ng:`철골 이음매가 녹아 끊겨 있었다.<br><br>손이 빈 데를 짚었다. 떨어졌다. 물 치는 소리가 체육관을 울렸다. 줄 선 것들이 일제히 이쪽을 향한다.<br>창까지 헤엄쳤다. 다리를 잡는 손을 셋 걷어찼다. 창틀에 올라서니 정강이에 손톱 자국이 줄줄이 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'A2', t:'수영장 — 다이빙대',
    x:`수영장 다이빙대가 물 위로 솟았다. 꼭대기 판이 높다. 물은 아직 거기까지 안 찼다.<br><br>
    관람석이 수영장 위를 빙 둘렀다. 관람석 난간 너머에 비상구 초록 불이 켜졌다. 다른 길은 레인을 헤엄쳐야 한다. 레인마다 물살이 오간다.<br>
    다이빙대 꼭대기에서 관람석 난간까지 네 걸음. 사이가 비었다.<br><br>
    판 끝에 물기가 있다. 젖은 발자국이 판 끝까지 갔다. 돌아오는 발자국은 없다.`,
    o:[
      { l:'① 판 끝에서 관람석 난간으로 뛴다.', k:'evade', dc:23, wake:1,
        ok:`판 끝에 섰다. 젖은 발자국을 피해 마른 데를 디뎠다. 판이 출렁인다. 출렁임을 세 번 탔다. 네 번째에 뛰었다.<br><br>판이 이쪽을 던졌다. 물 위를 지난다. 밑에서 레인 물살들이 멈추고 위를 본다. 떨어지기를 기다린다.<br>안 떨어졌다. 난간에 두 손이 걸렸다. 몸을 넘겼다.<br><br>판이 이쪽을 던진 건지 이쪽이 판을 쓴 건지 모르겠다. 디딘 것의 출렁임을 제 힘에 보태는 법을 발이 알았다. 출렁이는 것은 다 발판이다. 출렁일수록 좋은 발판이다.`,
        ng:`네 번째 출렁임에 판이 꺾였다. 젖은 발자국이 있던 자리에서.<br><br>뛰는 힘이 반만 실렸다. 관람석 밑 벽을 손으로 쳤다. 미끄러졌다. 떨어지는 순간 배수 턱을 잡았다. 발이 물에 잠겼다. 물살이 발목을 감아 레인 쪽으로 끌었다.<br>놓지 않았다. 기어올랐다. 발목에 물살 모양으로 붉은 줄이 감겼다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-20 } },
      { l:'② 다이빙대 기둥에서 관람석 기둥으로 옮겨 간다.', k:'steady', dc:22,
        ok:`사다리 뒤쪽은 철 기둥이다. 기둥이 관람석 기둥과 가까워지는 데가 있다. 한 팔 길이다.<br><br>기둥을 끌어안고 옮겨 갔다. 다리로 감고 팔로 건넜다. 곡예라기보다 나무 타기다. 물은 발밑 한 길 아래다.<br>관람석 기둥을 타고 올라 난간을 넘었다.<br><br>관람석 맨 앞줄에 수건이 개켜 있다. 젖지 않았다. 이름표가 붙었다. 17.`,
        ng:`기둥이 미끄러웠다. 물때가 끼었다.<br><br>한 팔로 버티는 사이 기둥 밑에서 물살이 올라왔다. 다리를 감는다. 레인 쪽으로 당긴다. 기둥을 끌어안고 버텼다. 가슴이 기둥에 쓸렸다.<br>물살이 그쳤을 때 올라왔다. 숨이 다 끊어질 뻔했다.`,
        win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-26, mind:-16 } }
    ] },

  { at:'A2', t:'기숙사 — 이층 침대',
    x:`기숙사 방이다. 이층 침대가 줄지어 섰다. 물이 아래 칸 매트리스 위까지 찼다.<br><br>
    아래 칸마다 이불이 덮였다. 이불이 물속에서 부풀었다. 사람 모양으로. 위 칸은 비었다.<br>
    종이 아홉 번 울렸다. 밤 점호다. 복도에서 물 헤치는 소리와 열쇠 소리가 다가온다. 점호 때는 다들 제 침대에 있어야 한다.<br><br>
    방 반대편 창으로 나가야 한다. 바닥은 물속이다. 위 칸 침대 난간이 줄줄이 이어진다.`,
    o:[
      { l:'① 위 칸 침대 난간을 타고 방을 건넌다.', k:'evade', dc:22,
        ok:`위 칸 난간에 올라섰다. 다음 침대 난간으로 건넜다. 철 침대가 끽 운다. 우는 소리에 맞춰 아래 칸 이불이 꿈틀한다.<br><br>울기 전에 다음 난간으로 갔다. 무게를 오래 두지 않으면 침대는 안 운다.<br>창틀에 닿았다. 복도 열쇠 소리가 문 앞에서 멈췄다.<br><br>창밖으로 몸을 뺐다. 문이 열렸다. 또박또박한 목소리가 센다. 열둘. 이상 없음. 이쪽은 세지 않았다.`,
        ng:`다섯째 침대 난간이 녹슬어 꺾였다.<br><br>위 칸 매트리스로 떨어졌다. 누운 채로. 그때 문이 열렸다. 안경 너머 눈이 방을 센다. 이쪽에서 멈췄다. 하나가 많네.<br>숨을 참았다. 눈길이 지나갔다. 문이 닫혔다. 일어나 창으로 갔다. 매트리스에 이쪽 이름이 적혀 있었다. 처음 보는 글씨로.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-24 } },
      { l:'② 빈 위 칸에 누워 점호를 넘긴다.', k:'steady', dc:23,
        doom:{ title:'이층 침대', what:'아래 칸 이불 속으로 끌려 내려갑니다', dc:18, sec:45,
          text:`빈 위 칸에 누웠다. 이불을 덮었다. 젖었다. 문이 열렸다. 안경 너머 눈이 센다.<br><br>세는 소리가 이쪽 침대에서 멈춘다. 이 침대는 아래 칸이 주인이에요. 목소리가 상냥하다.<br>매트리스 밑에서 손이 올라온다. 침대 판자 틈으로. 등을, 허리를 쥔다. 아래로 당긴다. 판자가 휜다. 아래 칸 이불이 펼쳐진다. 자리를 내준다. 물속에서.<br><br>판자 틈이 벌어진다. 몸 반쪽이 아래 칸으로 끌려 내려갔다. 물이 귀까지 올라온다.`,
          dieText:`점호 때는 다들 제 침대에 있어야 한다.<br><br>이쪽 침대는 아래 칸이었다. 원래 그랬던 것처럼.<br>열둘. 이상 없음. 다음 호실.` },
        ok:`눕기 전에 매트리스 이름표부터 봤다. 이름이 없는 침대가 하나 있다. 맨 끝, 창가. 거기 누웠다.<br><br>문이 열렸다. 안경 너머 눈이 센다. 이쪽 침대에서 멈춘다. 머뭇거린다. 이름 없는 침대에는 셀 사람이 없다. 누가 누워 있어도.<br>문이 닫혔다. 열쇠 소리가 다음 호실로 갔다.<br><br>일어나 창틀로 나갔다. 이름 없는 매트리스에 이쪽 몸 자국이 남았다. 그 자국에 물이 고이기 시작한다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 천장 들보에 거꾸로 매달려 점호를 넘긴다.', k:'evade', dc:23,
        ok:`천장 들보로 뛰어 매달렸다. 다리를 들보에 걸었다. 거꾸로. 숨을 죽였다.<br><br>문이 열렸다. 안경 너머 눈이 침대를 센다. 침대만 센다. 천장은 침대가 아니다.<br>열둘. 이상 없음. 문이 닫혔다.<br><br>내려와 창으로 갔다. 들보 위에 먼지가 없다. 손자국이 많다. 이쪽 말고도 여기 매달려 점호를 넘긴 이들이 있었다. 다 내려왔는지는 모른다.`,
        ng:`매달린 채 숨을 죽였다. 이쪽 머리카락에서 물이 떨어졌다.<br><br>똑, 똑. 물방울이 사감 발끝에 떨어진다. 안경이 위를 향한다. 눈이 마주쳤다. 사감이 장부에 뭔가 적는다. 그리고 나갔다.<br>내려오다 다리가 저려 침대 쇠에 정강이를 찍었다. 장부에 뭐라고 적혔는지 모르는 게 제일 무섭다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-26 } }
    ] },

  { at:'A2', t:'교실동 — 떠다니는 책상',
    x:`교실 하나가 통째로 물에 잠겼다. 책상이 떠다닌다. 서른 개쯤이다. 뒤집힌 것, 바로 선 것.<br><br>
    복도로 나가는 앞문까지 책상을 디딤돌 삼아야 한다. 물이 깊다. 바닥이 안 보인다.<br>
    책상 하나는 안 떠다닌다. 물 위에 떠 있는데 제자리에 있다. 의자가 빠져 있다.<br><br>
    곡예사는 떠 있는 것을 디딜 때 한 번에 하나만 디딘다. 둘을 디디면 둘 다 가라앉는다.`,
    o:[
      { l:'① 책상에서 책상으로 건너뛴다.', k:'evade', dc:22,
        ok:`가까운 책상부터 디뎠다. 발이 닿는 순간 다음 책상으로. 책상이 가라앉기 전에 떠났다.<br><br>제자리 책상은 피했다. 그 책상만 돌아서 갔다. 디딜 때마다 물에 동그라미가 퍼진다. 제자리 책상 둘레에서만 동그라미가 멎는다.<br>앞문 문턱에 내렸다.<br><br>돌아보니 제자리 책상 서랍이 열려 있다. 아까는 닫혀 있었다. 안에서 공책이 젖고 있다. 이쪽을 향해 펼쳐진 채.`,
        ng:`셋째 책상이 뒤집혔다. 디딘 쪽이 바닥이었다.<br><br>물에 빠졌다. 책상들이 이쪽 둘레로 모인다. 줄을 맞춘다. 수업이 시작된다는 듯이. 머리 위가 책상으로 덮인다.<br>책상 하나를 밀치고 머리를 내밀었다. 앞문까지 헤엄쳤다. 손바닥이 책상 모서리에 다 찢겼다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'② 무력을 실어 천장 형광등 틀을 잡고 건넌다.', k:'evade', dc:22, cost:{ might:26 },
        ok:`책상 하나를 딛고 뛰어 천장 형광등 틀을 잡았다. 틀이 볼트로 박혀 있다. 아직 튼튼하다.<br><br>틀에서 틀로 손을 옮겼다. 책상들이 밑에서 떠다닌다. 제자리 책상 위를 지날 때 그 책상 서랍이 덜컥 열렸다. 손을 뻗듯이.<br>앞문 위에서 내렸다.<br><br>마지막 틀에서 손을 뗄 때 유리관이 깨졌다. 조각이 제자리 책상 위로 떨어졌다. 책상이 처음으로 움직였다. 이쪽으로 한 뼘.`,
        ng:`둘째 틀의 볼트가 빠졌다.<br><br>틀째 기울었다. 매달린 채 물로 내려갔다. 허리까지 잠겼다. 제자리 책상이 바로 앞이다. 그 책상 의자가 물속에서 빠져나와 무릎 뒤를 쳤다. 앉으라고.<br>틀을 타고 다시 올랐다. 무릎이 펴지지 않는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] }
]);

// ── 경신술사 (lightfoot) · 내공 ──────────────
kJob('lightfoot', 'A', [
  { at:'A', t:'복도 — 무게를 세는 마루',
    x:`복도에 나무 마루가 깔렸다. 낡았다. 판마다 운다.<br><br>
    판이 한 번 울 때마다 복도 끝 어둠에서 숫자 하나가 들린다. 낮은 목소리다. 다섯. 여섯. 숫자가 하나 늘 때마다 어둠 속 발소리가 한 걸음 다가온다.<br>
    경신술사는 무게를 발에 안 싣는다. 판이 울려면 무게가 있어야 한다.<br><br>
    숫자는 지금 일곱에서 멈춰 있다. 앞서 들어간 이가 몇 걸음을 울렸는지는 모른다.`,
    o:[
      { l:'① 판에 무게를 싣지 않고 걷는다.', k:'evade', dc:22, wake:1,
        ok:`숨을 끌어올려 가슴에 띄웠다. 발은 판에 얹기만 했다. 디딘다고 하기도 어렵다.<br><br>판이 안 운다. 어둠도 안 센다. 일곱에서 멈춘 채다. 복도 가운데쯤에서 어둠 속 숨소리가 들렸다. 귀를 기울이고 있다. 셀 것을 기다린다.<br>복도 끝까지 왔다. 일곱.<br><br>지나와서 알았다. 발바닥이 판에 닿아 있던 시간이 숨 한 번 들이쉬는 것보다 짧았다. 닿는 시간을 줄이려고 애쓰지 않았다. 숨이 먼저 줄여 놓았다.`,
        ng:`열째 판이 다른 판보다 얇았다. 무게를 안 실었는데도 울었다.<br><br>여덟. 어둠에서 발소리가 한 걸음 왔다. 이쪽이 멈추자 발소리도 멈췄다. 다시 걸었다. 판이 또 울었다. 아홉.<br>남은 거리를 뛰었다. 판이 줄줄이 울었다. 숫자가 빨라졌다. 복도 끝 문을 닫을 때 문짝 너머에서 손톱이 긁었다. 등이 땀으로 다 젖었다.`,
        win:{ exp:22, dream:2 }, lose:{ mind:-18, spirit:-22 } },
      { l:'② 내공을 실어 벽을 옆으로 달려 지난다.', k:'evade', dc:22, cost:{ qi:28 },
        ok:`내공을 다리에 몰았다. 벽을 향해 뛰었다. 벽을 옆으로 디뎠다. 떨어지기 전에 다음 발.<br><br>마루는 한 번도 안 밟았다. 판이 울 일이 없다. 벽은 나무가 아니다. 세는 쪽은 나무만 듣는다.<br>복도 끝에서 내렸다. 문턱 돌 위에.<br><br>벽에 발자국이 한 줄로 남았다. 신발 자국이 아니라 먼지가 쓸린 자국이다. 어둠 속에서 누가 그 자국을 손으로 쓸어 본다.`,
        ng:`벽 중간에 액자가 걸려 있었다. 어두워서 못 봤다.<br><br>발이 액자 모서리에 걸렸다. 마루로 떨어졌다. 판이 한꺼번에 울었다. 여덟, 아홉, 열.<br>어둠에서 발소리가 뛰어온다. 일어나 달렸다. 무릎이 판 사이에 찍혀 피가 났다. 문을 닫자 발소리가 문 앞에서 멈췄다. 숨소리가 문틈으로 샌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'③ 동료들에게 안 우는 판을 짚어 준다.', k:'bond', dc:22,
        ok:`먼저 한 판씩 발끝으로 눌러 봤다. 무게 없이 누르면 판이 대답한다. 울 판인지 아닌지.<br><br>안 우는 판에 분필로 점을 찍었다. 점만 디디라고 손짓했다. 동료들이 하나씩 건넜다. 점에서 점으로.<br>마지막 사람이 건넜다. 숫자는 일곱 그대로다.<br><br>돌아보니 이쪽이 찍은 점들 사이에 점 하나가 더 찍혀 있다. 우는 판 위에. 이쪽은 안 찍었다.`,
        ng:`판을 짚다가 이쪽 무게가 실렸다. 한 판이 울었다. 여덟.<br><br>다들 얼어붙었다. 어둠에서 한 걸음이 왔다. 기다렸다. 오래. 발소리가 더 오지 않았다.<br>점을 다 못 찍고 건넜다. 동료 하나가 판을 울렸다. 아홉. 다들 끝까지 뛰었다. 숨이 한참 안 돌아왔다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
    ] },

  { at:'A', t:'계단 — 한 칸 먼저 찍히는 발자국',
    x:`계단을 내려간다. 젖은 발자국이 앞에 찍힌다.<br><br>
    이쪽이 한 칸 내려가면 한 칸 아래에 발자국이 먼저 찍힌다. 맨발이다. 보폭이 이쪽과 같다. 발 크기도 같다.<br>
    경신술사는 제 걸음을 안다. 남이 흉내 내면 어디가 다른지도 안다.<br><br>
    발자국은 늘 한 칸 먼저 간다. 계단 끝에 닿으면 거기서 뭘 할지는 모른다.`,
    o:[
      { l:'① 발자국을 피해 옆을 딛는다.', k:'evade', dc:22,
        ok:`발자국 옆 반 뼘에 디뎠다. 발자국이 찍힌 데는 안 디뎠다.<br><br>다음 칸에 또 발자국이 찍힌다. 이쪽이 피한 쪽으로 반 뼘 옮겨서. 또 피했다. 또 옮긴다.<br>계단 끝까지 왔다. 발자국이 마지막 칸에서 멈췄다. 맨 아래 바닥에는 안 찍혔다.<br><br>바닥에 내려서며 돌아봤다. 발자국이 계단을 거꾸로 올라가고 있다. 이쪽이 내려온 길을 덮으며.`,
        ng:`일곱째 칸에서 발자국이 이쪽 발밑에 바로 찍혔다. 피할 틈이 없었다.<br><br>발이 발자국 위에 겹쳤다. 차갑다. 발바닥이 계단에 붙었다. 떼는 데 한참 걸렸다. 발바닥 살갗이 계단에 조금 남았다.<br>나머지는 절며 내려갔다. 피 묻은 발자국이 이쪽 뒤로 따라온다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
      { l:'② 보법을 비틀어 발자국을 떨군다.', k:'evade', dc:23, wake:1,
        ok:`반 칸, 두 칸, 한 칸 반. 박자를 틀어서 내려갔다. 디딘 발을 다 디디기 전에 뗐다.<br><br>발자국이 따라오지 못한다. 한 칸 먼저 찍혀야 하는데 이쪽이 어디 디딜지 이쪽도 모른다. 발이 먼저 정한다. 머리는 나중에 안다.<br>발자국이 두 칸 뒤에서 헛디뎠다. 그 뒤로 안 찍혔다.<br><br>계단 끝에서 숨을 고르며 알았다. 걸음을 정하지 않고 걸었다. 정하지 않은 걸음은 아무도 흉내 내지 못한다. 이쪽 몸조차 미리 모른다.`,
        ng:`박자를 틀었는데 발자국도 틀었다. 똑같이. 한 칸 먼저.<br><br>이쪽이 흉내 내는 쪽이 된 것 같다. 발이 꼬였다. 계단 모서리에 무릎을 찍었다. 넘어진 자리 앞에 발자국 한 쌍이 서 있다. 이쪽을 내려다보는 자리에.<br>일어나 끝까지 굴러 내려갔다. 무릎이 펴지지 않는다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-14 } },
      { l:'③ 발자국 안에 발을 맞춰 딛는다.', k:'evade', dc:23,
        doom:{ title:'앞선 발자국', what:'발자국을 따라 계단 밑 어둠으로 끌려갑니다', dc:18, sec:50,
          text:`발자국에 발을 맞췄다. 크기가 딱 맞는다. 보폭도 맞는다. 걷기가 편하다. 너무 편하다.<br><br>발이 발자국에 붙는다. 다음 발자국이 찍힌다. 발이 저절로 거기 간다. 이쪽이 걷는 게 아니라 발자국이 이쪽을 걷게 한다.<br>계단 끝을 지났다. 발자국은 멈추지 않는다. 바닥을 지나 벽 밑 어둠으로 이어진다. 끌려가는 발이 어둠으로 들어간다. 발목까지 잠겼다.<br><br>뒤에서 동료가 부른다. 발자국이 한 칸 더 찍힌다. 어둠 안쪽에.`,
          dieText:`경신술사는 제 걸음을 안다. 남이 대신 걸어 주면 그건 이제 제 걸음이 아니다.<br><br>계단에 젖은 발자국이 찍혀 있다. 두 쌍이다.<br>다음에 내려오는 사람보다 한 칸 먼저.` },
        ok:`발자국에 발을 맞추되 무게는 안 실었다. 발자국 위에 발 모양만 얹었다.<br><br>발자국이 이쪽 무게를 찾다가 못 찾는다. 다음 발자국이 머뭇거리며 찍힌다. 반 칸 늦게.<br>이쪽이 먼저 계단 끝에 닿았다. 발자국은 한 칸 뒤에서 멈췄다. 처음으로 이쪽이 앞이다.<br><br>돌아보니 마지막 발자국이 돌아서 있다. 발끝이 이쪽을 향한다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A', t:'방 — 소리에 돌아보는 것',
    x:`방 가운데에 뭔가 벽을 보고 서 있다. 등이 좁다. 머리카락이 길다. 꼼짝 안 한다.<br><br>
    바닥에 깨진 그릇 조각이 흩어졌다. 앞서 누가 떨어뜨렸다. 조각 옆에 신발이 한 짝 있다. 한 짝뿐이다.<br>
    소리가 나면 돌아본다. 돌아본 다음 무엇을 하는지는 그 신발이 말해 준다.<br><br>
    건너편 문까지 열두 걸음. 그것의 숨은 길고 느리다.`,
    o:[
      { l:'① 그것이 숨을 내쉬는 동안에만 움직인다.', k:'evade', dc:22, wake:1,
        ok:`그것의 숨을 들었다. 들이쉬고, 오래 멈췄다가, 내쉰다. 내쉴 때는 제 숨소리에 귀가 막힌다.<br><br>내쉬는 동안 두 걸음. 들이쉬면 멈췄다. 이쪽 숨도 그것의 숨에 맞췄다. 같이 내쉬고 같이 멈췄다.<br>열두 걸음을 여섯 번에 갔다. 문고리를 잡을 때 그것이 길게 내쉬었다. 그 숨에 문소리를 묻었다.<br><br>문 밖에서 알았다. 남의 숨 위에 걸음을 얹는 법이 있다. 이쪽 발소리가 저쪽 숨 안에 들어가면 저쪽은 제 소리를 듣는 줄 안다.`,
        ng:`내쉬는 숨이 중간에 끊겼다. 이쪽은 발을 든 채였다.<br><br>발을 내렸다. 조각 하나를 밟았다. 작게 울렸다. 머리카락이 돌아갔다. 얼굴은 안 보였다. 머리카락만 이쪽을 본다.<br>문까지 뛰었다. 어깨에 손톱이 걸려 옷이 찢어졌다. 문을 닫았다. 문 너머에서 숨이 다시 길어진다. 어깨가 계속 화끈거린다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 내공을 실어 단숨에 달려 지난다.', k:'evade', dc:23, cost:{ qi:30 },
        doom:{ title:'돌아본 것', what:'돌아본 것에게 벽 쪽으로 끌려갑니다', dc:18, sec:50,
          text:`내공을 끌어올려 한 번에 달렸다. 열두 걸음을 네 걸음에. 빠르다.<br><br>빠른 것도 소리를 낸다. 바람이 그것의 머리카락을 흔들었다. 머리카락이 돌아갔다. 손이 먼저 왔다. 길다. 발목을 감았다.<br>끌린다. 벽 쪽으로. 그것이 보던 벽이다. 벽에 손톱 자국이 사람 키만큼 나 있다. 몸이 그 자국 앞으로 끌려간다.<br><br>얼굴은 아직 안 보인다. 보이기 전에 빠져나와야 한다.`,
          dieText:`빠른 발은 땅을 덜 밟는다. 그 대신 바람을 더 일으킨다.<br><br>벽에 손톱 자국이 한 줄 늘었다. 맨 아래, 바닥에 닿은 줄이다.<br>그것은 다시 벽을 보고 선다. 발 앞에 신발이 두 짝이다.` },
        ok:`달리기 전에 숨을 다 내렸다. 내공을 다리가 아니라 온몸에 펼쳤다. 몸이 바람을 안 일으키게.<br><br>네 걸음에 지났다. 그것의 머리카락이 하나도 안 흔들렸다. 이쪽이 지난 자리 공기가 그대로다.<br>문을 소리 없이 열고 나갔다.<br><br>문을 닫고 손바닥을 봤다. 땀이 하나도 안 났다. 그 대신 내공이 바닥까지 비었다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A', t:'천장 — 위에서 같이 걷는 발',
    x:`걷는데 위에서 발소리가 난다. 천장 바로 위다. 이쪽과 같이 걷는다.<br><br>
    멈추면 멈춘다. 빨리 가면 빨리 온다. 늘 이쪽 바로 위에 선다. 천장에서 먼지가 떨어진다. 이쪽 정수리에.<br>
    천장 위에 층이 있는지는 모른다. 지붕일 수도 있고 아무것도 아닐 수도 있다.<br><br>
    경신술사는 제 무게가 어디로 가는지 안다. 위의 것은 이쪽 무게를 듣는다.`,
    o:[
      { l:'① 무게를 거두고 그 자리에 선다.', k:'steady', dc:22,
        ok:`숨을 단전 아래로 내렸다. 발바닥에서 무게를 거뒀다. 서 있는데 바닥을 누르지 않는다.<br><br>위의 발소리가 멈칫했다. 이쪽을 잃었다. 천장 위를 이리저리 다닌다. 찾는다.<br>무게를 거둔 채 한 걸음씩 옮겼다. 위의 발소리는 엉뚱한 데를 맴돈다.<br><br>복도 끝에서 무게를 돌려놓았다. 그 순간 위에서 발소리가 뛰어왔다. 바로 위다. 문을 닫았다.`,
        ng:`무게를 거두는데 숨이 흔들렸다. 무게가 반쯤 남았다.<br><br>남은 반을 위의 것이 들었다. 바로 위에 섰다. 천장 판자가 휘었다. 판자 틈으로 손가락이 내려와 이쪽 머리카락을 집었다.<br>당겨지기 전에 뛰었다. 머리카락 한 움큼이 위로 올라갔다. 두피가 쓰라리다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } },
      { l:'② 내공을 실어 엉뚱한 벽을 차고 반대로 날아간다.', k:'evade', dc:22, cost:{ qi:26 },
        ok:`내공을 다리에 몰고 왼쪽 벽을 세게 찼다. 그 반동으로 오른쪽으로 소리 없이 날았다.<br><br>위의 발소리가 왼쪽으로 뛰어갔다. 찬 소리를 따라. 천장 왼쪽이 쿵 울렸다. 이쪽은 오른쪽 벽 밑에 내려 있다.<br>그대로 복도 끝까지 갔다. 위는 왼쪽만 계속 두드린다.<br><br>찬 자리 벽에 발자국이 패었다. 바로 위 천장도 같은 자리가 패었다. 위에서 거기를 쳤다.`,
        ng:`벽을 찼는데 반동이 짧았다. 바로 밑에 떨어졌다.<br><br>위의 발소리가 바로 위에서 멈췄다. 천장이 꺼졌다. 판자와 먼지가 쏟아졌다. 그 사이로 팔 하나가 내려와 휘저었다.<br>굴러서 피했다. 판자 모서리가 등을 찍었다. 팔이 거둬지고 판자 구멍으로 눈 하나가 내려다봤다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A', t:'복도 — 깔린 종이',
    x:`복도 바닥에 종이가 깔렸다. 빈틈없이. 낱장이다. 무엇이 적혔는지는 어두워서 안 보인다.<br><br>
    밟으면 바스락한다. 바스락할 때마다 양옆 문 하나가 조금 열린다. 문틈으로 아무도 안 나온다. 안에서 귀를 대고 있다.<br>
    경신술사는 마른 잎 위를 걷는 법부터 배운다. 종이는 잎보다 더 운다.<br><br>
    문이 스무 개다. 셋은 이미 열려 있다.`,
    o:[
      { l:'① 종이가 울기 전에 발을 뗀다.', k:'evade', dc:22, wake:1,
        ok:`발끝을 종이에 댔다. 종이가 무게를 알아채기 전에 뗐다. 다음 장, 다음 장.<br><br>종이가 안 운다. 문도 안 열린다. 열린 문 셋 앞을 지날 때 문틈에서 숨이 났다. 기다리는 숨이다. 이쪽은 소리 없이 지났다.<br>복도 끝에서 돌아보니 종이가 한 장도 안 구겨졌다.<br><br>종이가 우는 건 눌렸다가 펴질 때다. 눌리기 전에 떠나면 울 틈이 없다. 발이 그걸 처음으로 박자로 알았다. 디디는 박자가 아니라 떠나는 박자로.`,
        ng:`열한째 장이 젖어 있었다. 젖은 종이는 발에 붙는다.<br><br>발을 떼니 종이가 같이 들렸다. 들렸다가 떨어지며 바스락했다. 문 넷이 한꺼번에 열렸다. 틈마다 눈 하나씩.<br>종이를 밟으며 뛰었다. 바스락이 줄줄이 났다. 문이 줄줄이 열렸다. 끝에 닿아 문을 닫을 때 손등에 손톱이 그어졌다. 깊다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, spirit:-18 } },
      { l:'② 종이를 한 장씩 걷어 맨바닥 길을 낸다.', k:'fix', dc:22,
        ok:`쪼그려 앉아 종이를 한 장씩 들어 옆으로 겹쳐 놓았다. 소리 안 나게. 맨바닥이 드러난다.<br><br>오래 걸렸다. 사람 하나 너비 길이 났다. 동료들이 그 길로 지났다.<br>걷은 종이 맨 위 장에 글씨가 보였다. 출석부다. 이름이 적혔고 옆에 동그라미가 있다. 맨 아래 칸에 이쪽 일행 이름들. 동그라미는 아직 없다.<br><br>그 장은 접어서 품에 넣었다. 내려놓기가 싫었다.`,
        ng:`걷는데 종이 밑에서 종이가 또 나왔다. 몇 겹인지 모른다.<br><br>걷어도 바닥이 안 나온다. 그 사이 손 밑에서 한 장이 찢어졌다. 찌익. 문 하나가 활짝 열렸다. 아무도 안 나왔다. 열린 채로 있다.<br>다들 걷던 종이를 밟고 뛰었다. 등 뒤에 열린 문이 계속 열려 있다. 마음이 그쪽에 남았다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-16 } }
    ] },

  { at:'A', t:'계단참 — 뒤에서 부르는 목소리',
    x:`계단을 오른다. 이쪽이 맨 뒤다. 동료들은 위층에서 기다린다. 먼저 올라갔다.<br><br>
    뒤에서 동료 목소리가 부른다. 기다려. 같이 가. 숨이 찬 목소리다.<br>
    위에서도 동료 목소리가 부른다. 빨리 와.<br><br>
    둘 중 하나는 동료가 아니다. 경신술사의 걸음이면 위까지는 금방이다. 뒤를 확인하러 내려가는 것도 금방이다.`,
    o:[
      { l:'① 돌아보지 않고 위로 단숨에 오른다.', k:'evade', dc:22,
        ok:`돌아보지 않았다. 계단을 세 칸씩 발끝으로 차고 올랐다.<br><br>뒤의 목소리가 따라온다. 기다려. 기다려. 점점 가까이. 숨소리가 발뒤꿈치에 닿을 만큼.<br>위층에 닿았다. 동료들이 있다. 진짜다. 손을 잡혀 끌려 올라갔다.<br><br>뒤를 봤다. 계단이 비었다. 계단참 벽에 입김이 서린 자국이 있다. 사람 키보다 낮은 데에.`,
        ng:`오르는데 뒤 목소리가 울먹였다. 다리 다쳤어.<br><br>한 박자 멈췄다. 그 한 박자에 뒤에서 손이 발목을 쥐었다. 찼다. 손이 떨어졌다. 계단 모서리에 정강이를 찧었다.<br>위층에 닿았다. 동료들이 다 있다. 다친 사람은 없다. 정강이만 다쳤다. 이쪽 정강이만.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
      { l:'② 내공을 실어 한 번 내려가 확인하고 올라온다.', k:'sense', dc:23, cost:{ qi:25 },
        ok:`내공을 다리에 몰아 계단을 단숨에 내려갔다. 계단참 모퉁이에서 고개만 내밀었다.<br><br>계단참에 아무도 없다. 목소리만 있다. 벽에 뚫린 작은 구멍에서 난다. 구멍에서 젖은 숨이 나온다. 기다려.<br>확인하고 바로 올라왔다. 내려간 시간보다 올라온 시간이 짧았다.<br><br>동료들에게 말했다. 뒤에서 부르는 건 벽이다. 벽은 못 따라온다. 그다음부터 그 구멍이 이쪽 이름을 부른다.`,
        ng:`내려가 모퉁이를 돌았는데 목소리가 위에서 났다. 이번에는 위에서 기다려 한다.<br><br>어느 쪽이 진짜인지 모르겠다. 오를지 내려갈지 서 있다가 내공이 다 샜다.<br>결국 올랐다. 동료들이 다 있다. 다들 이쪽을 이상하게 본다. 너, 아까부터 여기 있었잖아.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-22 } }
    ] },

  { at:'A', t:'복도 — 분필 사방치기',
    x:`복도 바닥에 분필로 사방치기가 그려졌다. 칸이 열. 맨 끝 칸에 하늘이라고 적혔다.<br><br>
    칸 밖 바닥은 검게 젖었다. 젖은 데서 손가락이 하나씩 올라왔다 들어간다. 작다. 칸 안은 말랐다.<br>
    넷째 칸에 돌멩이 하나가 놓였다. 누가 던져 놓고 안 주웠다. 놀이는 돌을 줍고 돌아와야 끝난다.<br><br>
    하늘 칸 너머가 출구다. 경신술사는 한 발로도 오래 선다.`,
    o:[
      { l:'① 칸 안에만 놀이대로 딛어 간다.', k:'evade', dc:22, wake:1,
        ok:`한 발 칸에는 한 발, 두 발 칸에는 두 발. 놀이대로 디뎠다. 칸이 좁다. 발끝만 들어간다.<br><br>돌멩이 칸은 건너뛰었다. 놀이대로. 칸 밖에서 손가락들이 이쪽 발 둘레를 맴돈다. 금을 넘지는 않는다.<br>하늘 칸에 두 발로 섰다. 거기서 돌아가지 않고 출구로 나갔다. 등 뒤에서 아이 목소리가 반칙이라고 했다.<br><br>한 발로 선 시간이 길었는데 흔들리지 않았다. 무게가 한 점에 모이지 않고 온몸에 퍼져 있었다. 한 발이 두 발처럼 섰다.`,
        ng:`일곱째 칸 금이 번져 있었다. 발끝이 금을 밟았다.<br><br>금 밟았다. 아이 목소리가 말했다. 칸 밖 손가락들이 금을 넘어 들어왔다. 발목을 잡았다. 한 발로 버티던 몸이 기울었다.<br>하늘 칸으로 뛰어들었다. 발목에서 손이 떨어졌다. 그 자리가 퍼렇게 멍들었다. 출구를 나서는데 등 뒤에서 처음부터 다시 하자고 한다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-22 } },
      { l:'② 금을 무시하고 젖은 바닥을 질러 간다.', k:'evade', dc:23,
        doom:{ title:'사방치기', what:'칸 밖 젖은 바닥 밑으로 끌려 들어갑니다', dc:18, sec:45,
          text:`칸을 무시하고 젖은 바닥을 질러 뛰었다. 발이 빠르면 손이 못 잡는다.<br><br>세 걸음째에 바닥이 발을 삼켰다. 젖은 바닥은 바닥이 아니었다. 발목까지 빠졌다. 손가락들이 정강이를 기어오른다. 작다. 아이 손이다. 여럿.<br>당긴다. 아래로. 아이 목소리가 깔깔 웃는다. 금 밖은 술래야. 술래는 잡혀 가야 해.<br><br>무릎까지 끌려 들어갔다. 동료가 칸 안에서 손을 뻗는다. 칸 안에서만.`,
          dieText:`경신술사는 바닥이 빨리 지나가는 걸 안다. 바닥이 안 지나가면 소용없다.<br><br>사방치기 칸 밖이 조금 더 검어졌다.<br>넷째 칸 돌멩이 옆에 돌멩이가 하나 더 놓였다. 누가 던져 놓고 안 주웠다.` },
        ok:`젖은 바닥을 질렀다. 한 걸음마다 발이 바닥에 닿는 시간을 숨 반 토막으로 줄였다.<br><br>손가락들이 올라온다. 발이 있던 자리로. 늘 반 박자 늦다. 젖은 바닥이 발을 삼키려다 못 삼킨다.<br>출구 문턱에 내렸다. 발바닥이 젖지 않았다.<br><br>뒤에서 아이 목소리가 칭얼거린다. 반칙이야. 칸 밖 손가락들이 분필 금을 다 지워 버렸다. 다음 사람에게는 칸이 없다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 내공을 실어 하늘 칸까지 한 번에 건너뛴다.', k:'evade', dc:22, cost:{ qi:30 },
        ok:`첫 칸에서 내공을 다리에 몰았다. 뛰었다. 칸 아홉을 넘었다.<br><br>하늘 칸에 두 발로 내렸다. 분필 금 안이다. 손가락들이 칸 밖에서 이쪽을 향해 고개를 든다. 들어오지 못한다.<br>돌멩이는 안 주웠다. 놀이를 끝내지 않았다. 끝나지 않은 놀이는 술래가 안 정해진다.<br><br>출구를 나섰다. 등 뒤에서 아이 목소리가 묻는다. 내일 또 와?`,
        ng:`뛰는 순간 돌멩이가 굴러와 발에 걸렸다. 누가 굴렸다.<br><br>여섯 칸밖에 못 갔다. 일곱째 칸 금 위에 떨어졌다. 몸이 금 밖으로 쏠린다. 손가락이 옷자락을 잡았다. 찢고 하늘 칸으로 기어갔다.<br>무릎이 분필 금에 갈려 하얗고 붉다. 옷자락은 젖은 바닥 밑으로 들어갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } }
    ] },

  { at:'A', t:'통로 — 재가 깔린 바닥',
    x:`통로 바닥에 고운 재가 깔렸다. 발목까지 찬다.<br><br>
    앞서 발자국 한 줄이 지나갔다. 깊다. 그 발자국마다 다른 발자국이 겹쳤다. 뒤따라간 것이 있다. 발이 넷이다. 앞 발자국을 하나도 안 빼고 밟았다.<br>
    재에 발자국을 남기면 뒤따라온다. 경신술사는 발자국을 덜 남긴다. 아예 안 남기는 건 배운 적이 없다.<br><br>
    통로 저편에서 재가 날린다. 이쪽으로 바람이 분다.`,
    o:[
      { l:'① 재에 자국을 남기지 않고 지난다.', k:'evade', dc:23,
        ok:`재 위에 발을 얹었다. 재가 눌리기 전에 들었다. 재가 아주 조금 패었다. 바람이 그 팬 데를 덮었다.<br><br>바람이 이쪽 편이다. 얕은 자국은 바람이 지운다. 깊게만 안 디디면 된다.<br>통로를 다 지났다. 돌아보니 재가 판판하다. 앞서 간 발자국 한 줄과 그걸 밟은 네 발자국만 있다.<br><br>네 발자국이 통로 끝에서 멈췄다. 거기 재가 움푹 내려앉았다. 뭔가 거기 엎드려 있다. 이쪽을 보고.`,
        ng:`열째 걸음에서 재 밑에 돌이 있었다. 발이 걸려 깊이 디뎠다.<br><br>재 위에 발자국 하나가 깊게 찍혔다. 바람이 다 못 지웠다. 통로 끝에서 재가 꿈틀했다. 네 발이 다가온다. 그 발자국 하나를 찾아서.<br>뛰었다. 뛰니 발자국이 줄줄이 났다. 등 뒤에서 그것이 하나씩 밟아 온다. 출구 문을 닫았다. 문짝에 무게가 실렸다. 오래 버텼다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 다른 갈래로 발자국을 내고 거꾸로 되짚어 온다.', k:'hide', dc:22,
        ok:`옆 갈래로 열 걸음을 깊게 찍고 갔다. 그리고 그 발자국을 거꾸로 밟아 돌아왔다. 한 치도 안 틀리고.<br><br>원래 통로로는 자국 없이 지났다. 옆 갈래에만 발자국이 있다. 가서 안 돌아온 발자국이다.<br>통로 끝에서 숨었다. 네 발이 재를 헤치고 왔다. 옆 갈래로 들어갔다. 안 나왔다.<br><br>그 갈래 끝이 막혔는지 뚫렸는지는 모른다. 그것은 거기서 오래 기다릴 것이다.`,
        ng:`되짚어 오는데 발자국 하나를 틀렸다. 반 뼘.<br><br>발자국이 두 줄이 됐다. 가는 것과 오는 것. 네 발이 갈래 앞에서 멈추더니 오는 줄을 따라왔다.<br>통로 끝에서 뛰었다. 발뒤꿈치를 이빨이 스쳤다. 뒤꿈치 살이 패었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } }
    ] },

  { at:'A', t:'계단 — 끝나지 않는 아래',
    x:`계단을 내려간다. 층계참이 나오고 또 계단이다. 또 층계참이다.<br><br>
    층계참마다 같은 얼룩이 있다. 벽에 손바닥만 한 얼룩. 같은 자리, 같은 모양. 열 번째 층계참이다.<br>
    경신술사는 걸음을 숨으로 센다. 몇 숨에 몇 걸음. 몸이 기억한다.<br><br>
    열 번째 층계참까지 숨이 서른 번 들었다. 첫 층계참까지도 서른 번이었다.`,
    o:[
      { l:'① 숨으로 걸음을 세어 어긋난 칸을 찾는다.', k:'sense', dc:23, wake:1,
        ok:`숨 하나에 두 칸. 그렇게 내려가며 셌다. 층계참마다 서른 숨. 다 같다.<br><br>그런데 한 군데에서 숨이 반 토막 남았다. 열넷째 칸. 발은 디디는데 몸이 반 칸 덜 내려간다. 거기서 옆으로 디뎠다. 벽 쪽으로.<br>벽이 아니었다. 계단이 거기서 갈라져 있었다. 다음 층계참에는 얼룩이 없다.<br><br>눈은 같은 계단을 열 번 봤다. 숨은 처음부터 알았다. 숨으로 세면 발밑이 아니라 길이 보인다. 걸음이 어디서 어긋나는지 숨이 먼저 짚는다.`,
        ng:`세다가 숨이 흐트러졌다. 얼룩이 이쪽을 본다고 느꼈다.<br><br>숨을 다시 맞추느라 걸음이 섰다. 얼룩이 한 뼘 커졌다. 손바닥 하나가 둘이 됐다. 손가락이 이쪽으로 펴진다.<br>뛰어 내려갔다. 층계참이 또 나왔다. 얼룩이 셋이다. 결국 동료가 이쪽 손을 잡고 끌고 내려갔다. 어떻게 빠져나왔는지 기억이 없다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-24 } },
      { l:'② 내공을 실어 거꾸로 거슬러 뛰어오른다.', k:'evade', dc:22, cost:{ qi:28 },
        ok:`내공을 끌어올려 돌아섰다. 내려온 계단을 세 칸씩 뛰어 거슬러 올랐다.<br><br>층계참 하나를 지나니 얼룩이 없다. 그다음에 다시 있다. 얼룩 없는 층계참으로 돌아가 거기서 다른 문을 찾았다. 비상구다. 초록 불이 꺼져 있다.<br>문을 밀었다. 열렸다. 다른 계단이다. 이 계단에는 얼룩이 없다.<br><br>문을 닫기 전에 봤다. 얼룩 있는 계단으로 누가 내려간다. 이쪽과 같은 옷을 입었다.`,
        ng:`거슬러 오르는데 계단이 같이 내려왔다. 오르는 만큼.<br><br>내공이 다 빠질 때까지 뛰었다. 제자리다. 얼룩 앞이다. 다리가 풀렸다. 얼룩에 손을 짚었다. 차고 젖었다.<br>손바닥에 얼룩이 옮겨 붙었다. 벽의 얼룩이 그만큼 작아졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-26 } }
    ] },

  { at:'A', t:'방 — 숨 쉬는 바닥',
    x:`방 바닥이 오르내린다. 천천히. 판판한 바닥이 숨을 쉬듯 부풀었다 가라앉는다.<br><br>
    가라앉을 때 바닥 틈이 벌어진다. 틈 안이 붉고 젖었다. 부풀 때 닫힌다.<br>
    경신술사는 디딘 것이 움직이면 그 박자를 탄다. 숨 쉬는 것 위를 걸어 본 적은 없다.<br><br>
    건너편 문까지 바닥이 다 같다.`,
    o:[
      { l:'① 바닥이 부풀어 오르는 박자에만 딛는다.', k:'evade', dc:22, wake:1,
        ok:`바닥의 박자를 셌다. 가라앉기 시작할 때 틈이 벌어진다. 부풀기 시작할 때 닫힌다. 부풀 때만 디뎠다.<br><br>부푸는 바닥은 위로 민다. 미는 힘에 발을 얹으면 이쪽이 한 일 없이 앞으로 간다. 가라앉는 동안 발은 이미 다음 숨을 기다렸다. 숨 한 번에 한 걸음.<br>문에 닿았다. 문지방은 숨을 안 쉰다.<br><br>밑에서 미는 것을 발로 받으면 그게 길이 된다. 디딘 것이 이쪽을 밀어 주면 이쪽은 거의 안 디뎌도 된다. 발이 그 힘을 빌리는 법을 알았다.`,
        ng:`박자가 중간에 바뀌었다. 바닥이 숨을 참았다.<br><br>발밑에서 바닥이 갑자기 가라앉았다. 틈이 벌어졌다. 발이 빠졌다. 틈이 닫혔다. 발목이 물렸다. 부드럽게, 꽉.<br>바닥이 다시 부풀 때 틈이 열렸다. 발을 뺐다. 발목에 동그랗게 자국이 남았다. 이빨 자국은 아니다. 입술 자국 같다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-18 } },
      { l:'② 내공으로 몸무게를 지우고 그대로 걸어 지난다.', k:'evade', dc:23, cost:{ qi:30 },
        doom:{ title:'숨 쉬는 바닥', what:'바닥 틈으로 빨려 들어갑니다', dc:18, sec:45,
          text:`내공으로 몸무게를 지웠다. 가벼운 몸으로 걸었다. 바닥이 이쪽을 모른다.<br><br>가운데에서 바닥이 크게 들이쉬었다. 틈이 벌어졌다. 공기가, 먼지가, 가벼운 것이 틈으로 빨려 들어간다. 무게를 지운 몸이 제일 가볍다.<br>몸이 틈 쪽으로 빨려 간다. 발이 바닥에서 떴다. 틈 가장자리를 손으로 잡았다. 젖고 따뜻하다. 들이쉬는 숨이 길어진다.<br><br>내공을 풀어 무게를 돌려야 한다. 그러면 잡은 손이 미끄러진다.`,
          dieText:`무게가 없으면 바닥은 모른다. 숨은 안다.<br><br>바닥은 그 뒤로 한참 숨을 안 쉬었다. 배가 부른 것처럼.<br>다시 오르내리기 시작했을 때 박자가 조금 느려져 있었다.` },
        ok:`무게를 지우되 다 지우지 않았다. 바닥을 누를 만큼만 남겼다.<br><br>가운데에서 바닥이 크게 들이쉬었다. 먼지가 틈으로 빨려 들어간다. 이쪽은 안 빨려 갔다. 남겨 둔 무게가 발을 바닥에 붙여 줬다.<br>숨이 멎는 사이에 문까지 걸었다.<br><br>문지방을 넘고 돌아보니 바닥이 길게 내쉬었다. 틈에서 신발 한 짝이 뱉어져 나왔다. 이쪽 것이 아니다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A1', t:'중앙 계단 — 칸마다 박수',
    x:`방송국 중앙 계단이다. 층계참마다 표지가 붙었다. 조용히 해 주세요. 녹화 중.<br><br>
    한 칸 오르면 위에서 박수가 한 번 난다. 두 칸이면 두 번. 박수가 세는 건 칸이 아니다. 칸에 실린 무게다.<br>
    난간 틈으로 파란 목이 내려다본다. 박수가 날 때마다 부리가 그쪽으로 꺾인다.<br><br>
    경신술사의 발은 칸에 오래 머물지 않는다.`,
    o:[
      { l:'① 칸에 닿는 시간을 박수보다 짧게 한다.', k:'evade', dc:22, wake:1,
        ok:`발끝을 칸에 대자마자 뗐다. 칸이 무게를 알아채기 전에.<br><br>박수가 나려다 만다. 짝, 대신 손바닥 스치는 소리만 난다. 파란 목이 갸웃한다. 어디서 났는지 모른다.<br>한 층을 올랐다. 박수는 끝내 한 번도 제대로 안 났다.<br><br>층계참에서 숨을 고르며 알았다. 발이 칸에 닿은 건 맞다. 그 시간이 박수 한 번보다 짧았을 뿐이다. 이제 발이 닿는 시간을 잴 수 있다. 박수로, 숨으로, 심장 한 번으로.`,
        ng:`다섯째 칸이 미끄러웠다. 발이 반 박자 머물렀다.<br><br>짝. 박수가 났다. 파란 목이 꺾였다. 부리가 난간 틈으로 내려와 어깨를 쪼았다. 옷과 살이 같이 찢겼다.<br>나머지는 뛰어 올랐다. 박수가 연달아 났다. 위층 문을 닫자 박수가 그쳤다. 어깨에서 피가 계속 난다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-18 } },
      { l:'② 내공을 실어 난간 위를 달려 오른다.', k:'evade', dc:22, cost:{ qi:28 },
        ok:`난간 위에 올라섰다. 내공을 발에 모으고 달렸다. 난간은 계단이 아니다. 박수는 계단만 센다.<br><br>파란 목이 난간 틈에서 이쪽을 찾는다. 계단만 보다가 난간을 보는 데 시간이 걸렸다. 그 사이 두 층을 올랐다.<br>층계참에 내렸다. 발이 칸에 닿았다. 짝. 한 번.<br><br>파란 목이 그 한 번을 듣고 내려온다. 문을 닫았다. 문 너머에서 부리가 문짝을 두 번 두드렸다. 노크하듯이.`,
        ng:`난간 모퉁이를 돌다 발이 미끄러졌다. 계단에 떨어졌다. 세 칸이 한꺼번에 울렸다.<br><br>짝짝짝. 파란 목이 단번에 내려왔다. 부리가 뒷덜미 옷깃을 물었다. 들렸다. 옷깃이 찢어져 떨어졌다.<br>무릎으로 계단을 기어 올랐다. 칸마다 박수가 난다. 문까지 오는 동안 박수 소리에 귀가 먹먹했다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] },

  { at:'A1', t:'놀이 세트 — 공 바다',
    x:`공 바다다. 낮은 울타리 안에 색색 플라스틱 공이 가득하다. 허리 높이. 방 저편 문까지 이어진다.<br><br>
    공이 가운데서부터 천천히 돈다. 달그락, 달그락. 소용돌이처럼. 공 사이로 하얀 것이 보였다 사라진다. 장갑이다.<br>
    가장자리 매트는 좁고 미끄럽다. 매트 위에 젖은 발자국이 있다. 작다. 공 바다 쪽에서 끊겼다.<br><br>
    경신술사는 가벼운 것 위를 걷는 법을 안다. 공은 가볍다. 너무 가볍다.`,
    o:[
      { l:'① 공 위를 달려 건넌다.', k:'evade', dc:23,
        doom:{ title:'공 바다', what:'공 바다 밑으로 빨려 들어갑니다', dc:18, sec:45,
          text:`공 위를 달렸다. 발이 닿는 공마다 한 번씩 꺼진다. 꺼지기 전에 다음 공.<br><br>가운데쯤에서 소용돌이가 빨라졌다. 발밑 공이 다 같이 돌았다. 디딜 공이 발밑에서 빠져나간다. 무릎까지 빠졌다. 허리. 공이 귀 옆에서 달그락거린다.<br>밑에서 장갑이 발목을 쥔다. 손가락 넷. 공 사이로 끌어당긴다. 소용돌이 한가운데로 빨려 간다. 공 너머로 녹음된 아이 웃음이 깔린다.<br><br>공이 가슴까지 왔다. 손을 위로 뻗었다.`,
          dieText:`가벼운 것 위를 걷는 법은 안다. 가벼운 것끼리 짜고 돌면 그 위가 없다.<br><br>공 바다는 그 뒤로도 천천히 돈다. 달그락, 달그락.<br>공 하나가 색이 다르다. 이쪽 옷 색이다.` },
        ok:`공 위를 달렸다. 공 하나에 발끝 하나. 공이 꺼지기 전에 떠났다. 소용돌이 바깥쪽 공만 골랐다. 덜 도는 쪽.<br><br>가운데에서 장갑이 솟았다. 이쪽 발이 있던 공을 쥐었다. 공만 쥐었다.<br>저편 울타리를 넘어 문 앞에 내렸다.<br><br>돌아보니 소용돌이 한가운데가 움푹 꺼졌다. 거기로 공이 빨려 내려간다. 이쪽을 받으려고 파 둔 자리다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 가장자리 매트를 미끄러지지 않게 딛어 돈다.', k:'steady', dc:22,
        ok:`매트에 발을 붙였다. 미끄러운 데는 발바닥 전체로, 덜 미끄러운 데는 발끝으로. 천천히 돌았다.<br><br>공 바다에서 장갑이 하나씩 고개를 내민다. 이쪽 발을 본다. 매트는 공 바다가 아니다. 넘어오지 않는다.<br>문 앞에 닿았다. 젖은 발자국이 끊긴 자리를 지날 때 숨을 참았다.<br><br>문 옆 울타리 기둥에 이름표가 걸렸다. 공 바다에서 놀다 간 친구들. 이름이 스무 개. 맨 아래 칸이 비었다.`,
        ng:`젖은 발자국 자리에서 매트가 공 바다 쪽으로 기울었다.<br><br>발이 미끄러져 다리 하나가 공에 잠겼다. 장갑이 정강이를 쥐었다. 울타리를 붙잡고 버텼다. 장갑이 놓을 때까지.<br>정강이에 장갑 손가락 자국이 넷. 공 하나가 바짓단에 끼어 따라 나왔다. 버렸다. 공이 굴러서 공 바다로 돌아갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } },
      { l:'③ 공을 멀리 던져 장갑들을 그쪽으로 부른다.', k:'luck', dc:22,
        ok:`공 하나를 집어 반대편 구석으로 던졌다. 달그락. 장갑들이 그쪽으로 몰렸다.<br><br>그 틈에 가장자리로 빠르게 지났다. 반대편 구석에서 공들이 솟구친다. 장갑들이 던진 공을 찾는다.<br>문 앞에서 돌아보니 던진 공이 구석에서 튀어 올라 이쪽으로 굴러온다. 누가 되던졌다.<br><br>문을 닫았다. 문 밑으로 공이 와서 톡 부딪쳤다. 같이 놀자고.`,
        ng:`던졌는데 공이 울타리에 맞고 이쪽으로 튀었다.<br><br>공이 발밑에 떨어졌다. 장갑들이 그 공을 쫓아 몰려왔다. 이쪽으로. 공 바다 가장자리가 하얗게 들썩였다.<br>뛰었다. 매트에서 미끄러져 무릎을 찧었다. 문까지 기었다. 무릎이 부어오른다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-14 } }
    ] },

  { at:'A1', t:'분장실 — 분가루 바닥',
    x:`분장실 바닥에 하얀 분가루가 쏟아져 있다. 거울 앞 의자에서부터 문까지.<br><br>
    분가루 위에 발자국이 찍힌다. 아무도 안 걷는데. 거울 속에서 누가 걷는다. 거울 안 바닥에 찍히는 발자국이 거울 밖 바닥에도 찍힌다.<br>
    그것은 발자국을 따라온다. 이쪽 발자국도.<br><br>
    분가루는 무게를 다 기억한다. 경신술사는 무게를 덜 준다.`,
    o:[
      { l:'① 분가루에 자국 없이 문까지 간다.', k:'evade', dc:23, wake:1,
        ok:`숨을 가슴에 띄우고 발을 얹었다. 분가루가 눌리기 전에 떠났다. 분이 발끝에 아주 조금 묻었다. 자국은 안 남았다.<br><br>거울 속 발자국이 이쪽을 찾는다. 바닥을 헤맨다. 이쪽 길에는 찾을 게 없다.<br>문을 나섰다. 돌아보니 분가루 바닥에 거울 속 것의 발자국만 이리저리 찍혀 있다. 길 잃은 발자국이다.<br><br>발끝에 묻은 분가루를 봤다. 아주 조금이다. 디딘 무게가 딱 그만큼이었다. 분가루 한 겹이 이쪽 몸무게를 다 못 쟀다. 이제 그만큼으로도 걷는다.`,
        ng:`분가루가 날렸다. 발이 일으킨 바람에.<br><br>날린 분가루가 이쪽 발 모양으로 내려앉았다. 자국이 생겼다. 거울 속 발자국이 그 자국을 따라 다가온다. 거울 밖으로 한 걸음씩.<br>문까지 뛰었다. 등 뒤에서 분 냄새가 확 끼쳤다. 뒷덜미에 하얀 손가락 자국이 남았다. 씻어도 안 지워진다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 거울에 의상 천을 덮는다.', k:'fix', dc:22,
        ok:`옆 행거에서 큰 천을 끌어내 거울에 덮었다. 거울 둘레 전구 빛이 천에 막혀 붉게 번진다.<br><br>거울 속 발자국이 멈췄다. 보이지 않으니 걷지 않는다.<br>분가루 위를 그냥 걸었다. 발자국이 났다. 따라오는 것은 없다.<br><br>문을 나서기 전에 돌아봤다. 천 밑에서 손가락 하나가 천을 들추고 있다. 거울 안쪽에서.`,
        ng:`천을 덮는데 천이 짧았다. 한 귀퉁이가 남았다.<br><br>남은 귀퉁이에 거울 속 얼굴이 반쪽 보인다. 분을 두드리던 손이 멈췄다. 이쪽을 본다. 분가루 바닥에 발자국이 이쪽으로 찍혀 온다.<br>뛰었다. 의자에 걸려 넘어졌다. 분가루를 뒤집어썼다. 문을 나와 보니 얼굴이 하얗다. 거울 속 얼굴처럼.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
    ] },

  { at:'A1', t:'방청석 — 일어선 친구',
    x:`방청석 가운데 통로에 바람잡이가 서 있다. 얼굴이 사진이다. 웃는 남자 사진을 오려 붙였다.<br><br>
    사진 얼굴이 방청석을 천천히 훑는다. 일어선 것을 찾는다. 앉은 것은 방청객이고 선 것은 오늘의 친구다.<br>
    방청석 맨 위 출구까지 계단 마흔 칸. 앉은 높이로 가야 한다. 경신술사는 낮은 자세로도 걷는다. 무릎을 접고, 무게를 띄우고.<br><br>
    사진 얼굴이 이쪽 줄 끝에 왔다.`,
    o:[
      { l:'① 앉은 높이로 무릎을 접고 소리 없이 오른다.', k:'evade', dc:22,
        ok:`무릎을 깊이 접었다. 엉덩이가 등받이보다 낮다. 그 자세로 계단을 디뎠다. 무게는 접힌 무릎에 고루 나눴다.<br><br>사진 얼굴이 이쪽 줄을 훑고 지나갔다. 앉은 높이다. 방청객이다.<br>마흔 칸을 다 올랐다. 허벅지가 탄다. 출구 문틀을 잡고서야 일어섰다.<br><br>문 너머에서 돌아봤다. 이쪽이 오른 계단 칸마다 무릎 높이에 손자국이 찍혀 있다. 이쪽 손이 아니다. 같이 기어오른 손들이다.`,
        ng:`서른째 칸에서 허벅지에 쥐가 났다. 무릎이 펴졌다.<br><br>반쯤 일어섰다. 사진 얼굴이 이쪽에서 멎었다. 저기 키 큰 친구! 박수가 쏟아졌다. 보이지 않는 손들이 겨드랑이를 들었다. 주저앉았다. 손들이 놓쳤다.<br>앉은 채로 기어 출구까지 갔다. 허벅지가 끊어질 듯하다. 박수는 이쪽이 문을 닫을 때까지 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-20 } },
      { l:'② 내공을 실어 한 호흡에 출구까지 달린다.', k:'evade', dc:23, cost:{ qi:30 },
        doom:{ title:'오늘의 친구', what:'손에서 손으로 실려 무대로 갑니다', dc:18, sec:50,
          text:`내공을 끌어올려 마흔 칸을 한 호흡에 달렸다. 빠르다. 빠른 것은 선 것이다.<br><br>스무 칸쯤에서 사진 얼굴이 이쪽을 봤다. 저기 신난 친구! 스피커에서 박수가 쏟아졌다.<br>발이 계단에서 떴다. 빈 의자들 위로 몸이 들린다. 작은 손들이 등을, 다리를 받친다. 손에서 손으로 넘어간다. 앞으로. 무대 쪽으로 실려 간다.<br><br>계단은 위로 가는데 몸은 아래로 간다. 박수가 몸 밑에서 들린다.`,
          dieText:`빨리 가면 덜 밟는다. 그 대신 더 보인다.<br><br>그날 방송의 오늘의 친구는 아주 빨랐다.<br>박수가 그칠 때까지 무대 위를 쉬지 않고 뛰었다.` },
        ok:`달리기 전에 몸을 앉은 높이로 낮췄다. 그 높이 그대로 내공을 다리에 몰았다. 무릎을 접은 채 달렸다.<br><br>마흔 칸을 한 호흡에 올랐다. 사진 얼굴이 훑을 때마다 이쪽은 앉은 높이다. 자리만 계속 바뀔 뿐이다.<br>출구 앞에서 일어섰다. 이미 문 밖이다.<br><br>사진 얼굴이 고개를 갸웃한다. 맨 윗줄에 앉아 있던 친구가 어디 갔는지.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A1', t:'세트 뒤 — 카운트다운',
    x:`세트 뒤 좁은 통로다. 합판 벽 뒤편이라 각목이 얼기설기 드러났다. 바닥에 굵은 전선이 깔렸다.<br><br>
    스피커가 센다. 삼십. 이십구. 녹음된 언니 목소리다. 다 세면 세트 벽이 열린다. 열린 벽 앞에 선 것은 무대로 나간다. 무대 감독 카드에 그렇게 적혀 있었다.<br>
    통로 끝 문까지 마흔 걸음. 전선이 발에 감긴다. 전선이 꿈틀한다.<br><br>
    경신술사의 걸음이면 스물이면 된다. 전선만 아니면.`,
    o:[
      { l:'① 전선 사이 빈 바닥만 딛고 달린다.', k:'evade', dc:22,
        ok:`전선 사이 빈 바닥이 손바닥만 하다. 발끝만 거기 넣었다. 셈에 맞춰 두 걸음씩.<br><br>십오. 전선이 발을 따라 머리를 든다. 발이 떠난 데를 감는다. 늘 늦다.<br>오. 문고리를 잡았다. 열었다.<br><br>영. 등 뒤에서 세트 벽이 열렸다. 노란 빛이 통로를 채운다. 박수가 쏟아진다. 통로에 아무도 없다. 박수가 머뭇거린다.`,
        ng:`십에서 전선 하나가 발목에 감겼다. 굵다. 따뜻하다.<br><br>당긴다. 세트 벽 쪽으로. 각목을 잡고 버텼다. 셈이 줄어든다. 사, 삼. 발목을 비틀어 뺐다. 신발이 벗겨졌다.<br>영에 문을 넘었다. 등 뒤에서 벽 열리는 소리가 났다. 전선이 이쪽 신발을 노란 빛 쪽으로 끌고 갔다. 발목이 퉁퉁 붓는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
      { l:'② 셈 사이 쉬는 숨에만 움직인다.', k:'fix', dc:22,
        ok:`언니 목소리는 숫자 사이에 숨을 쉰다. 테이프에 녹음된 숨. 그 숨 동안 전선이 멈춘다. 전선도 듣고 있다.<br><br>숨 사이에만 걸었다. 숫자가 나오면 섰다. 동료들도 그렇게 했다.<br>오. 문을 열었다. 다 같이 넘었다.<br><br>영. 세트 벽이 열렸다. 무대 감독이 카드를 든 채 통로를 들여다본다. 카드가 한 장 넘어간다. 다음엔 꼭.`,
        ng:`숨 사이가 짧아졌다. 테이프가 늘어졌다. 숨 대신 지지직 소리가 났다.<br><br>전선이 지지직에 맞춰 움직였다. 동료 하나가 감겼다. 끌어냈다. 이쪽 손목이 전선에 쓸려 화끈거렸다.<br>영에 맞춰 문을 넘었다. 다 넘었는지 세어 봤다. 다 있다. 손목에서 탄내가 난다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-20 } },
      { l:'③ 내공을 실어 각목 위를 타고 달린다.', k:'evade', dc:22, cost:{ qi:26 },
        ok:`합판 벽을 받친 각목에 올라섰다. 내공을 발에 모으고 각목 위를 달렸다. 손가락 두 개 너비다.<br><br>전선은 바닥에 있다. 위를 못 본다. 발밑으로 전선들이 머리를 들고 소리를 쫓는다. 각목은 소리가 안 난다.<br>이십에 문 위에 내렸다. 십이 남았다.<br><br>남은 십 동안 문 밖에서 숨을 골랐다. 영. 세트 벽이 열렸다. 노란 빛이 각목 위를 비췄다. 거기 서 있는 것이 하나 있다. 이쪽이 아니다.`,
        ng:`각목 하나가 못이 빠져 있었다. 디디자 돌았다.<br><br>바닥으로 떨어졌다. 전선 위로. 전선들이 일제히 감겨 왔다. 팔, 허리. 팔을 뽑아 각목을 잡고 몸을 끌어냈다.<br>문을 넘을 때 셈은 이였다. 허리에 전선 자국이 감겼다. 덴 것처럼.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-14 } }
    ] },

  { at:'A2', t:'교실동 — 칠판까지 닿는 물결',
    x:`교실동 복도는 물이 허리까지다. 교실 하나를 가로질러야 앞문으로 나간다.<br><br>
    교실 물이 잔잔하다. 걸으면 물결이 퍼진다. 물결이 칠판에 닿으면 칠판에 글씨가 써진다. 물결을 일으킨 사람의 이름이다.<br>
    칠판에 이름이 이미 셋 있다. 셋 다 지워지다 만 자국이다.<br><br>
    경신술사는 물속 걸음을 따로 배우지 않았다. 다만 무게를 덜 주는 법은 물에도 통한다.`,
    o:[
      { l:'① 물결을 일으키지 않고 지난다.', k:'evade', dc:23,
        ok:`다리를 물속에서 내밀지 않고 미끄러뜨렸다. 무릎을 접어 물을 가르지 않게. 발은 바닥에 얹기만 했다.<br><br>물결이 생겨도 한 뼘 안에서 사라진다. 칠판까지 못 간다. 칠판 앞 물이 잔잔하다. 분필이 칠판 홈에서 들썩이다 멈췄다.<br>앞문을 나섰다.<br><br>복도에서 돌아보니 칠판에 글씨 하나가 써지다 만다. 첫 획만. 이쪽 이름의 첫 획이다. 물결 한 줄기가 늦게 닿았다.`,
        ng:`가운데에서 의자에 정강이가 걸렸다. 물결이 크게 일었다.<br><br>물결이 칠판에 닿았다. 분필이 홈에서 일어나 썼다. 이쪽 이름이다. 또박또박. 다 쓰자 물 밑에서 의자 빼는 소리가 났다. 서른 개가 한꺼번에.<br>앞문으로 뛰었다. 물 밑에서 소매를 잡는 손을 뿌리쳤다. 손목에 손톱 자국이 남았다. 칠판에서 이름은 안 지워졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-24 } },
      { l:'② 내공으로 숨을 늘여 물 밑으로 가라앉아 걷는다.', k:'steady', dc:22, cost:{ qi:28 },
        ok:`내공으로 숨을 길게 늘였다. 물 밑으로 몸을 가라앉혔다. 바닥을 걸었다. 물 밑 걸음은 물결이 위로 덜 간다.<br><br>책상 다리 사이를 지났다. 책상 밑에 실내화들이 가지런하다. 다 앞문 쪽을 향했다. 그 사이로 걸었다.<br>앞문 밑에서 올라왔다. 수면이 한 번 흔들렸다. 칠판까지는 안 갔다.<br><br>숨을 몰아쉬며 봤다. 책상 밑 실내화 한 켤레가 이쪽을 따라 앞문 앞까지 와 있다.`,
        ng:`물 밑에서 숨이 다 되기 전에 누가 어깨를 눌렀다. 앉으라고.<br><br>책상 밑으로 밀렸다. 의자가 무릎 뒤를 받쳤다. 앉혀졌다. 내공을 다 쏟아 몸을 빼냈다. 숨이 터졌다. 물결이 크게 일었다.<br>칠판에 이쪽 이름이 써지는 소리를 들으며 앞문으로 나왔다. 숨이 한참 안 돌아왔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'A2', t:'중정 — 유리 온실 지붕',
    x:`중정은 물에 잠겼다. 유리 온실 지붕만 수면 위로 나와 있다. 둥근 지붕이다. 유리판 사이 철골이 가늘다.<br><br>
    건너편 본관 창까지 지붕을 넘어가야 한다. 유리는 금이 갔다. 금 간 유리 밑에 얼굴들이 붙어 있다. 위를 본다. 손바닥을 유리에 댔다.<br>
    유리 밑 온실 안은 물이 덜 찼다. 화분이 줄지어 있다. 초록이 아직 산다.<br><br>
    경신술사는 깨질 것 위를 걷는 법을 안다. 깨지기 전에 지나가면 된다.`,
    o:[
      { l:'① 금 간 유리 위를 가볍게 건넌다.', k:'evade', dc:23, wake:1,
        ok:`유리 위에 발을 얹었다. 금이 소리를 냈다. 금이 더 가기 전에 다음 판으로.<br><br>발밑 유리 너머로 얼굴들이 이쪽을 따라 고개를 돌린다. 손바닥이 유리를 두드린다. 똑똑. 이쪽이 지난 판을. 늘 지난 판이다.<br>본관 창틀에 닿았다. 돌아보니 지붕 유리판마다 금이 하나씩 더 갔다. 깨진 판은 없다.<br><br>유리가 금을 내는 소리가 발바닥으로 왔다. 그 소리가 나기 전에 발은 이미 떠나 있었다. 깨지는 것이 깨지는 데 걸리는 시간을 발이 잴 줄 알게 됐다. 그 시간이면 넉넉하다.`,
        ng:`가운데 판이 무게를 못 견뎠다. 깨졌다.<br><br>발 하나가 유리를 뚫고 들어갔다. 밑의 손들이 발목을 잡았다. 유리 조각이 종아리를 그었다. 철골을 끌어안고 다리를 뺐다. 손들이 놓아줬다. 놓아주면서 쓰다듬었다.<br>창까지 기어갔다. 종아리 상처가 깊다. 물이 닿으면 따갑다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, spirit:-18 } },
      { l:'② 유리 사이 철골만 골라 딛는다.', k:'sense', dc:22,
        ok:`유리판 사이 철골을 봤다. 손가락 두 개 너비다. 녹이 슬었지만 이어져 있다. 철골만 디뎠다.<br><br>유리 밑 얼굴들이 철골 밑으로 모인다. 철골은 유리가 아니라서 그 밑이 안 보인다. 손바닥들이 철골 양옆 유리를 더듬는다.<br>창에 닿았다. 철골이 끝까지 버텼다.<br><br>창틀에서 내려다보니 얼굴들이 철골 밑에 줄지어 있다. 철골 모양대로. 이쪽이 지나온 길 그대로.`,
        ng:`철골 이음매 하나가 녹아 끊겼다.<br><br>발이 유리판으로 미끄러졌다. 금이 쩍 갈라졌다. 깨지지는 않았다. 갈라진 금 사이로 손가락 하나가 올라와 발바닥을 긁었다. 간지럽고 차다.<br>철골로 다시 올라 기어갔다. 긁힌 발바닥이 걸을 때마다 얼얼하다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
      { l:'③ 깨진 판으로 팔을 넣어 온실 화분에서 약초를 딴다.', k:'luck', dc:23,
        ok:`깨진 유리판 하나를 찾아 팔을 넣었다. 밑의 화분까지 닿는다. 얼굴들이 그쪽으로 모이기 전에.<br><br>잎을 더듬었다. 향이 짙다. 약초다. 뿌리째 한 줌 뽑았다. 다른 손이 손목을 스치기 직전에 뺐다.<br>나머지는 철골로 건넜다.<br><br>창틀에서 약초를 봤다. 잎이 싱싱하다. 물 밑에서 누가 계속 물을 줬다.`,
        ng:`팔을 넣었는데 화분이 아니라 손을 잡았다. 작은 손이다.<br><br>손이 놓지 않는다. 당긴다. 어깨까지 들어갔다. 유리 모서리가 겨드랑이를 그었다. 동료가 허리를 잡아 빼냈다.<br>손에 약초 대신 꽃 한 송이가 쥐여 있다. 젖은 하얀 꽃이다. 버리지 못했다.`,
        win:{ exp:16, dream:1, item:'약초 뭉치' }, lose:{ hp:-28, spirit:-22 } }
    ] },

  { at:'A2', t:'나선 계단 — 물가의 대답',
    x:`종탑 나선 계단을 내려간다. 스무 칸 밑에서 물이 시작된다. 물속으로도 계단은 이어진다.<br><br>
    계단 바깥쪽 난간이 물 위로 한 바퀴 더 돈다. 그 끝에 아래층 창이 물 위로 반쯤 나와 있다. 물에 들어가지 않는 길은 그 난간뿐이다.<br>
    시계가 일곱 시 이 분 전이다. 일곱 시가 되면 점호가 시작된다. 물 밑 칸마다 대답한다.<br><br>
    경신술사의 걸음이면 난간 한 바퀴는 숨 몇 번이다.`,
    o:[
      { l:'① 내공을 실어 난간 위를 달려 창으로 간다.', k:'evade', dc:23, cost:{ qi:30 },
        doom:{ title:'물가 난간', what:'물속 계단으로 끌려 내려갑니다', dc:18, sec:45,
          text:`내공을 발에 모아 난간 위를 달렸다. 물이 발밑에서 반짝인다. 반 바퀴.<br><br>종이 울렸다. 일곱 시다. 물 밑에서 대답이 올라온다. 네. 대답이 날 때마다 물이 한 칸씩 출렁 오른다. 물이 난간에 닿았다. 발이 젖었다.<br>젖은 발목을 작은 손이 잡았다. 난간 밑 물속에서. 하나, 또 하나. 칸마다 앉은 것들이 손을 내밀었다. 아래 칸으로 당긴다.<br><br>몸이 난간에서 미끄러진다. 물이 무릎까지 온다. 다음 이름이 불린다.`,
          dieText:`빠른 발은 젖지 않는다. 물이 따라 올라오면 이야기가 다르다.<br><br>물 밑 계단에서 대답이 하나 더 났다. 처음 듣는 목소리였다.<br>다음 날 아침에는 그 목소리가 귀에 익었다.` },
        ok:`종이 울리기 전에 달렸다. 내공을 발에 모아 난간 꼭대기 쇠를 발끝으로만 짚었다.<br><br>종이 울렸다. 물 밑에서 대답이 오른다. 네. 물이 출렁 올라온다. 이쪽 발이 그 위를 지난 다음에.<br>창틀에 닿아 창 안으로 몸을 넣었다. 그제야 물이 난간을 덮었다.<br><br>창 안에서 보니 난간 위에 젖은 손자국이 줄줄이 찍혀 있다. 이쪽 발이 짚은 자리마다 하나씩. 다 반 박자 늦은 손이다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 계단참에 서서 점호가 끝나기를 기다린다.', k:'steady', dc:22,
        ok:`물에서 다섯 칸 위 계단참에 섰다. 숨을 죽였다.<br><br>종이 일곱 번 울렸다. 이름이 불리고 대답이 오른다. 물이 한 칸씩 오른다. 넷째 칸. 셋째 칸. 계단참 바로 밑에서 멎었다.<br>점호가 끝났다. 물이 천천히 내려간다. 다 내려간 뒤 난간을 타고 창으로 갔다.<br><br>계단참 바로 밑 칸에 물이 고여 있다. 그 칸에 대답 하나가 남았다. 아직 안 불린 이름을 기다린다.`,
        ng:`물이 계단참까지 올라왔다. 발이 젖었다.<br><br>발등에 차가운 손이 얹혔다. 아이 손이다. 줄 서라는 듯 발목을 톡톡 친다. 숨을 참았다. 대답하지 않았다.<br>점호가 끝나고 물이 내려갔다. 발목에 손가락 자국이 남았다. 그 자국이 젖은 채로 마르지 않는다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
    ] },

  { at:'A2', t:'수영장 — 레인 로프',
    x:`수영장 물은 맑고 미지근하다. 소독약 냄새가 난다. 레인 로프가 물 위에 떠 있다. 여섯 줄. 둥근 부표가 줄줄이 꿰였다.<br><br>
    레인마다 물살이 오간다. 누가 헤엄친다. 물살만 헤엄친다.<br>
    건너편 배수구 쪽으로 가려면 레인을 가로질러야 한다. 로프 위로 가면 물에 안 들어간다. 부표는 사람 하나를 못 받친다.<br><br>
    경신술사 하나는 받칠지도 모른다.`,
    o:[
      { l:'① 레인 로프 부표를 밟고 건넌다.', k:'evade', dc:23,
        doom:{ title:'레인', what:'레인 로프째 물 밑으로 가라앉습니다', dc:18, sec:45,
          text:`부표 위에 발끝을 얹었다. 가라앉기 전에 다음 부표. 첫 로프를 건넜다. 둘째.<br><br>셋째 로프에서 물살이 지나갔다. 로프가 출렁 휘었다. 부표가 발밑에서 뒤집혔다. 발이 로프에 감겼다. 로프가 가라앉는다. 이쪽 발목을 감은 채로.<br>물 밑 레인에서 물살이 돌아온다. 이쪽을 지나며 감는다. 같이 돌자고. 로프와 물살이 이쪽을 바닥으로 끌어당긴다.<br><br>수면이 머리 위에서 흔들린다. 소독약 냄새가 코로 들어온다.`,
          dieText:`부표는 사람 하나를 못 받친다. 경신술사 하나는 받쳤다. 물살 하나는 못 받쳤다.<br><br>여섯 레인 중 하나가 비어 있었는데 이제 다 찼다.<br>출석 칠판의 결석 칸 숫자가 하나 줄었다.` },
        ok:`부표에 발끝만 얹었다. 물살이 지나가는 박자를 들었다. 물살이 지난 직후 로프가 잔잔하다. 그때만 디뎠다.<br><br>여섯 로프를 건넜다. 부표가 하나도 안 뒤집혔다. 발은 반도 안 젖었다.<br>건너편 타일 위에 내렸다.<br><br>돌아보니 레인 물살들이 로프 앞에서 다 멈춰 있다. 이쪽을 보고. 그러다 다시 헤엄친다. 수업은 끝나지 않는다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 출발대에서 출발대로 건너뛰어 돈다.', k:'evade', dc:22,
        ok:`출발대가 레인마다 하나씩 있다. 수영장 끝을 따라 한 줄로. 출발대에서 출발대로 뛰었다.<br><br>이쪽이 뛸 때마다 출발대 밑 물살이 출발한다. 출발대 위에 누가 있으면 출발하는 것이다. 이쪽이 떠난 다음에. 아무도 이쪽을 못 잡는다.<br>마지막 출발대에서 배수구 쪽 타일로 내렸다.<br><br>출발대마다 젖은 발자국이 하나씩 남았다. 이쪽이 디딘 데 옆에. 같이 뛴 발이 있었다.`,
        ng:`넷째 출발대가 미끄러웠다. 발이 물 쪽으로 미끄러졌다.<br><br>물에 반쯤 빠졌다. 물살이 와서 다리를 감았다. 출발대 손잡이를 잡고 버텼다. 물살이 놓고 지나갔다. 다음 물살이 돌아온다.<br>출발대로 기어 올라와 나머지를 뛰었다. 다리에 물살 자국이 감겼다. 살갗이 하얗게 불었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-18 } },
      { l:'③ 내공으로 숨을 늘여 수영장 바닥을 걸어 건넌다.', k:'steady', dc:22, cost:{ qi:28 },
        ok:`숨을 단전에 깊이 묻고 길게 늘였다. 물속으로 가라앉아 바닥 타일 위를 걸었다.<br><br>머리 위로 물살들이 지나간다. 레인을 따라. 바닥은 레인이 아니다. 물살은 바닥까지 안 내려온다.<br>배수구 쪽 벽에 닿아 올라왔다. 숨이 반쯤 남았다.<br><br>바닥 타일에 검은 레인 줄이 그어져 있었다. 줄마다 실내화가 한 켤레씩 놓였다. 이쪽이 지나온 빈 레인 줄에만 없다.`,
        ng:`레인 가운데에서 물살 하나가 바닥까지 내려왔다. 이쪽을 찾으러.<br><br>물살이 이쪽 둘레를 돈다. 몸이 들린다. 타일 틈을 손가락으로 잡고 버텼다. 숨이 줄어든다. 물살이 지나갔다.<br>올라와 한참 기침했다. 소독약 물을 먹었다. 손톱 하나가 타일 틈에 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A2', t:'본관 복도 — 열쇠 소리',
    x:`본관 복도다. 물이 턱 밑까지 찼다. 천장과 수면 사이에 머리 하나 들어갈 공기가 있다.<br><br>
    복도 저편에서 열쇠 소리가 온다. 물 헤치는 소리도. 사감이다. 안경이 수면 위로 반짝인다. 교실 문을 하나씩 열고 센다.<br>
    뒤는 막혔다. 지나가려면 사감 옆을 지나야 한다. 복도 폭이 사람 셋이다.<br><br>
    경신술사는 남 옆을 지날 때 바람을 일으키지 않는 법을 안다. 물속에서는 해 본 적이 없다.`,
    o:[
      { l:'① 사감이 문 안을 세는 순간 등 뒤로 흘러 지난다.', k:'evade', dc:23, wake:1,
        ok:`사감이 교실 문을 열고 안을 셌다. 등을 보였다. 그 한 순간.<br><br>물속에서 몸을 미끄러뜨렸다. 팔도 다리도 젓지 않았다. 숨을 끌어올려 몸을 띄우고 벽을 손가락으로 한 번 밀었다. 그 한 번이 이쪽을 끝까지 실어 갔다. 사감 등 뒤 한 뼘으로.<br>사감이 문을 닫고 돌아섰다. 이쪽은 이미 다음 모퉁이다.<br><br>모퉁이에서 숨을 내쉬었다. 몸을 안 움직이고 움직였다. 한 번 민 힘을 끝까지 흘려 쓰는 법을 처음 알았다. 땅에서도 될 것이다. 한 번 딛고 오래 가는 걸음.`,
        ng:`등 뒤를 지나는데 물결이 사감 허리에 닿았다.<br><br>사감이 천천히 돌아봤다. 안경 너머 눈이 이쪽을 셌다. 하나. 장부에 뭔가 적는다. 길쭉한 손가락이 이쪽 손목을 잡았다. 차다. 놓아줬다. 다 적고 나서.<br>모퉁이를 돌아 숨을 몰아쉬었다. 손목에 잡힌 자국이 하얗다. 장부에 뭐라고 적혔는지 모른다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
      { l:'② 사물함 위 공기 속에 몸을 붙이고 기다린다.', k:'hide', dc:22,
        ok:`복도 벽 사물함 위로 몸을 올렸다. 천장과 사물함 사이 공기에 엎드렸다. 숨을 아주 가늘게.<br><br>사감이 밑을 지나간다. 물 헤치는 소리, 열쇠 소리. 사물함을 하나하나 연다. 안을 센다. 위는 안 센다.<br>지나갔다. 사물함에서 내려와 반대쪽으로 갔다.<br><br>엎드렸던 사물함 문에 이름표가 있다. 17. 사감이 그 사물함만 안 열었다.`,
        ng:`사물함 위에서 숨을 참는데 머리카락 끝이 수면에 닿았다.<br><br>물결이 아주 작게 퍼졌다. 사감이 걸음을 멈췄다. 위는 안 보고 사물함 문을 두드렸다. 이쪽 바로 밑 사물함이다. 똑똑. 안에서 대답이 났다. 네.<br>사감이 지나갔다. 이쪽은 한참 사물함에서 못 내려왔다. 밑 사물함 안에서 계속 숨소리가 났다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
    ] }
]);

// ── 환영술사 (illusion) · 마력 ──────────────
kJob('illusion', 'A', [
  { at:'A', t:'복도 — 이름 부르는 방',
    x:`복도 옆 방에서 누가 이쪽 이름을 부른다. 문이 반쯤 열렸다. 안은 깜깜하다.<br><br>
    부르는 목소리는 다정하다. 대답할 때까지 부른다. 앞서 간 이의 이름도 불렀을 것이다. 그 이는 대답했다. 문틈 앞에 그 이 신발이 가지런히 놓여 있다.<br>
    환영술사는 모양을 만든다. 목소리도 모양이다. 이쪽 목소리로 대답하는 모양을 만들 수 있다.<br><br>
    목소리가 또 부른다. 조금 가까이.`,
    o:[
      { l:'① 마력으로 이쪽 모양 환영을 세워 대신 대답하게 한다.', k:'evade', dc:23, cost:{ mana:30 },
        doom:{ title:'대답한 환영', what:'대답한 환영과 함께 방 안으로 끌려갑니다', dc:18, sec:50,
          text:`환영을 문 앞에 세웠다. 이쪽 얼굴, 이쪽 목소리. 환영이 대답했다. 네.<br><br>방 안에서 손이 나와 환영의 손목을 잡았다. 환영은 잡히지 않는다. 그런데 잡혔다. 손이 환영을 끌고 간다. 환영과 이쪽 사이 마력 줄이 팽팽해진다.<br>줄을 끊으려 했다. 안 끊어진다. 저쪽이 줄째 당긴다. 이쪽 몸이 문 쪽으로 끌려간다. 발이 바닥을 긁는다.<br><br>문틈 앞에 이쪽 신발이 놓인다. 가지런히. 이쪽은 아직 신고 있는데.`,
          dieText:`맞는 것은 늘 진짜가 아닌 쪽이었다. 이번에는 둘 다 끌려갔다.<br><br>복도 옆 방에서 누가 이름을 부른다. 다정하다.<br>이쪽 목소리다.` },
        ok:`환영을 세우되 마력 줄을 가늘게 했다. 언제든 끊을 수 있을 만큼.<br><br>환영이 대답했다. 네. 방 안에서 손이 나와 환영을 잡았다. 끌고 들어간다. 줄이 당겨진다. 바로 끊었다.<br>환영이 방 안으로 사라졌다. 목소리가 그쳤다. 흡족한 침묵이다.<br><br>그 틈에 복도를 지났다. 등 뒤 방에서 이쪽 목소리가 웃는다. 끊은 줄 끝이 아직 손끝에서 따끔거린다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 대답하지 않고 혀를 깨문 채 지난다.', k:'steady', dc:22,
        ok:`입을 다물었다. 이름이 불려도 대답하지 않았다. 혀를 이 사이에 물었다.<br><br>목소리가 점점 다정해진다. 다음엔 서운해한다. 다음엔 울먹인다. 그래도 대답하지 않았다.<br>방 앞을 지났다. 문틈 신발 옆을 지날 때 목소리가 귀에 바로 대고 불렀다. 숨이 닿았다.<br><br>복도 끝에서 혀를 놓았다. 피 맛이 난다. 대답 대신 그걸 삼켰다.`,
        ng:`목소리가 이쪽 어릴 적 이름을 불렀다. 아무도 모르는 이름이다.<br><br>입이 저절로 벌어졌다. 반쯤 대답했다. 응. 문틈에서 바람이 불어왔다. 손이 나왔다. 동료가 이쪽 입을 막고 끌어냈다.<br>그 뒤로 한참 그 이름이 머리에서 안 나간다. 누가 알았는지 모른다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
      { l:'③ 부르는 목소리의 이음매를 본다.', k:'gaze', dc:22,
        ok:`목소리를 모양으로 봤다. 목소리도 만든 것이면 이음매가 있다.<br><br>있다. 이름 끝 글자에서 목소리가 한 번 꺾인다. 다른 목소리를 이어 붙인 자리다. 앞서 간 이들 목소리를 한 글자씩 잘라 이어 만들었다.<br>이음매를 알고 들으니 다정하지 않다. 그냥 조각이다. 조각에는 대답할 필요가 없다.<br><br>지나면서 들었다. 이쪽 이름 첫 글자는 아직 아무 목소리로도 안 채워졌다. 빈칸이다.`,
        ng:`보려고 귀를 기울였다. 기울인 만큼 목소리가 가까워졌다.<br><br>귀 안에서 부른다. 이음매를 찾을 틈이 없다. 머리가 울린다. 무릎을 꿇었다. 동료가 귀를 막아 줬다.<br>복도를 기다시피 지났다. 귀 안에서 이름이 한참 메아리친다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
    ] },

  { at:'A', t:'방 — 등 뒤의 눈',
    x:`방에 들어온 뒤로 등 뒤가 계속 무겁다. 누가 본다.<br><br>
    돌아보면 없다. 돌아봤다가 다시 앞을 보면 앞의 것이 조금 바뀌어 있다. 의자 하나가 반 뼘 옮겨졌다. 문이 조금 더 닫혔다.<br>
    돌아보지 않으면 등이 계속 무겁다. 무거운 등은 점점 가까워진다.<br><br>
    환영술사는 보이는 것을 만든다. 등 뒤에도 눈을 그릴 수 있다. 그려 본 적은 없다.`,
    o:[
      { l:'① 마력으로 뒤통수에 뒤를 보는 얼굴을 그린다.', k:'evade', dc:22, cost:{ mana:28 }, wake:1,
        ok:`뒤통수에 이쪽 얼굴을 하나 더 그렸다. 뒤를 보는 얼굴. 눈을 뜨고 있다.<br><br>등 뒤 무게가 멈췄다. 보고 있는 얼굴 앞에서는 다가오지 못한다. 앞을 보고 걸었다. 뒤통수 얼굴은 뒤를 봤다.<br>방을 다 지났다. 문을 나서며 환영을 거뒀다. 거두기 직전 뒤통수 얼굴이 본 것이 이쪽 눈에 비쳤다. 잠깐. 길쭉한 것이 방 한가운데 서 있었다.<br><br>환영은 보지 못한다. 그런데 봤다. 이쪽이 그린 눈이 잠깐 이쪽 것이 됐다. 만든 것을 통해 보는 길이 있다는 걸 몸이 먼저 알았다.`,
        ng:`얼굴을 그리는데 마력이 떨렸다. 웃는 얼굴로 그려졌다.<br><br>등 뒤 무게가 웃는 얼굴 앞에서 멈칫했다가 더 가까이 왔다. 웃는 건 오라는 뜻이다. 뒷덜미에 숨이 닿았다.<br>뛰었다. 문을 나와 환영을 거뒀다. 뒷덜미에 서늘한 자국이 남았다. 입술 모양이다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
      { l:'② 눈은 앞에 둔 채 고개만 돌린다.', k:'gaze', dc:23,
        ok:`돌아봤다. 아무것도 없다. 앞을 다시 봤다. 의자가 옮겨졌다.<br><br>다시 돌아봤다. 이번에는 돌아보는 척만 했다. 눈은 앞에 둔 채 고개만. 의자가 움직이는 게 보였다. 바닥에 닿지 않은 손이 의자를 민다. 반 뼘.<br>손이 어디로 가는지 봤다. 문 쪽이다. 이쪽 앞길을 막으러.<br><br>손이 문에 닿기 전에 먼저 문으로 갔다. 등 뒤 무게가 늦게 따라왔다. 문을 닫았다.`,
        ng:`돌아봤다. 없다. 앞을 봤다. 바로 앞에 얼굴이 있다.<br><br>코앞이다. 눈이 없다. 숨이 차다. 뒷걸음질 쳤다. 얼굴이 따라온다. 그러다 갑자기 없다.<br>방을 나왔다. 손이 덜덜 떨린다. 다시는 안 돌아보겠다고 했는데 문을 닫으며 또 돌아봤다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-22 } }
    ] },

  { at:'A', t:'문 — 문구멍의 눈',
    x:`문에 문구멍이 있다. 안에서 밖을 보는 작은 렌즈다. 렌즈가 축축하다. 눈이 대고 있다.<br><br>
    문 앞을 지나야 복도 끝으로 간다. 눈은 지나가는 것을 본다. 본 다음 문이 열린다. 문 앞 바닥에 문짝이 긁은 반원 자국이 깊다.<br>
    환영술사는 보는 것에게 다른 것을 보여 준다. 그게 일이다.<br><br>
    렌즈 너머에서 눈이 한 번 깜박였다.`,
    o:[
      { l:'① 마력으로 문구멍 앞에 빈 복도를 씌운다.', k:'evade', dc:22, cost:{ mana:28 }, wake:1,
        ok:`손바닥만 한 환영을 문구멍 앞에 띄웠다. 빈 복도. 조금 전 이쪽이 오기 전의 복도다. 먼지까지 그대로.<br><br>눈이 빈 복도를 본다. 문은 안 열린다. 그 앞을 지났다. 이쪽은 렌즈 바로 앞 한 뼘에 있는데 렌즈 안에는 없다.<br>복도 끝에서 환영을 거뒀다.<br><br>작은 환영 하나로 큰 것을 가렸다. 상대가 보는 구멍만 가리면 된다. 세상을 다 그릴 필요가 없다. 보는 눈 하나 크기면 된다. 그걸 알고 나니 마력이 반만 들었다.`,
        ng:`빈 복도를 씌웠는데 렌즈가 돌아갔다. 문구멍이 하나가 아니었다.<br><br>문 아래쪽 구멍에서 다른 눈이 이쪽 발을 봤다. 문이 열렸다. 반원을 긁으며. 손이 발목을 쓸었다.<br>뛰었다. 발목이 긁혔다. 문은 다시 닫혔다. 반원 자국이 한 줄 더 깊어졌다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-18 } },
      { l:'② 손바닥으로 문구멍을 막고 지난다.', k:'steady', dc:23,
        doom:{ title:'문구멍', what:'문구멍 너머로 끌려 들어갑니다', dc:18, sec:50,
          text:`손바닥으로 렌즈를 덮었다. 축축하다. 눈이 손바닥에 닿았다. 깜박인다. 손바닥 안에서.<br><br>렌즈가 빠졌다. 안쪽에서 빼냈다. 구멍에 이쪽 손가락이 들어갔다. 안에서 뭔가 손가락을 감쌌다. 입이다. 당긴다.<br>손이 구멍으로 끌려 들어간다. 구멍은 손가락 하나 너비다. 손이 다 들어간다. 손목, 팔꿈치.<br><br>어깨가 문에 붙었다. 문 너머에서 눈이 이쪽 팔을 타고 얼굴까지 올라온다. 반가워한다.`,
          dieText:`보는 것을 막으면 보지 못한다. 대신 만질 수는 있다.<br><br>문에 문구멍이 있다. 렌즈가 축축하다.<br>렌즈 아래 문짝 한가운데에 손바닥 자국이 하나 찍혀 있다. 안쪽에서 민 자국이다.` },
        ok:`손바닥을 렌즈 앞 한 치에 띄웠다. 닿지 않게. 눈이 손바닥 그늘만 본다.<br><br>그늘 아래로 지났다. 눈은 그늘이 지나가는 것만 본다. 그늘은 무게가 없다. 문이 안 열린다.<br>복도 끝에서 손을 내렸다. 손바닥이 차다. 닿지도 않았는데 젖어 있다.<br><br>문구멍 렌즈가 이쪽을 따라 돌아간다. 끼익. 렌즈 돌아가는 소리가 처음 났다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A', t:'갈림길 — 탁해지는 불빛',
    x:`뒤에서 뭔가 따라온다. 소리가 없다. 다만 이쪽이 지난 자리 불빛이 하나씩 탁해진다.<br><br>
    앞이 두 갈래다. 왼쪽은 넓고 오른쪽은 좁다. 어느 쪽이 나가는 길인지 모른다.<br>
    환영술사는 갈림길에서 둘로 간다. 하나는 진짜, 하나는 모양.<br><br>
    뒤의 탁한 기운이 한 칸 가까워졌다.`,
    o:[
      { l:'① 환영을 넓은 쪽으로 보내고 좁은 쪽으로 간다.', k:'evade', dc:22,
        ok:`이쪽 환영을 넓은 갈래로 걷게 했다. 발소리도 넣었다. 느리게, 크게.<br><br>이쪽은 좁은 갈래로 들어갔다. 숨을 죽였다. 뒤의 탁한 기운이 갈림길에서 멈췄다. 넓은 쪽으로 갔다. 큰 발소리를 따라.<br>좁은 갈래 끝에 문이 있었다. 열렸다.<br><br>문을 닫기 전에 들었다. 넓은 갈래 끝에서 환영이 멈추는 소리. 이쪽은 멈추라고 하지 않았다.`,
        ng:`환영을 보냈는데 뒤의 것이 환영을 안 따라갔다.<br><br>갈림길에서 멈춰 냄새를 맡는 소리가 났다. 환영은 냄새가 없다. 좁은 갈래로 들어왔다. 이쪽 뒤로.<br>뛰었다. 좁은 벽에 어깨가 갈렸다. 문을 닫는데 문틈으로 탁한 기운이 스며들었다. 숨이 한동안 무거웠다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-18 } },
      { l:'② 마력으로 이쪽 몸 위에 벽을 그리고 선다.', k:'hide', dc:22, cost:{ mana:30 },
        ok:`갈림길 모서리 벽에 붙었다. 이쪽 몸 위에 벽을 그렸다. 벽돌, 얼룩, 금 간 데까지.<br><br>뒤의 것이 왔다. 갈림길에서 멈췄다. 이쪽 벽 앞에. 숨이 닿을 거리다. 벽을 봤다. 벽이다. 넓은 갈래로 갔다.<br>한참 있다가 환영을 거뒀다. 좁은 갈래로 갔다.<br><br>이쪽이 그린 벽 얼룩 하나를 진짜 벽에서 봤다. 같은 자리에. 이쪽이 그리기 전부터 있었는지 모르겠다.`,
        ng:`벽을 그리는데 숨이 가빴다. 그린 벽이 숨에 맞춰 부풀었다.<br><br>뒤의 것이 부푸는 벽 앞에 멈췄다. 손을 댔다. 손이 환영을 뚫고 이쪽 가슴에 닿았다. 차다. 얼음을 댄 것 같다.<br>뿌리치고 좁은 갈래로 뛰었다. 가슴에 손자국이 하얗게 남았다. 숨 쉴 때마다 시리다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-18 } }
    ] },

  { at:'A', t:'어둠 — 빛으로 오는 것',
    x:`등불을 켜면 그것이 온다. 끄면 멈춘다. 어둠 속에서 이쪽은 아무것도 안 보인다.<br><br>
    불을 켜자 저쪽 어둠에서 기는 소리가 났다. 빠르다. 껐다. 멈췄다. 가깝다. 아까보다 더 가깝다.<br>
    환영술사는 빛도 만든다. 진짜 불은 아니다. 따뜻하지 않다.<br><br>
    따뜻하지 않은 빛에도 오는지는 모른다.`,
    o:[
      { l:'① 마력으로 멀리 따뜻한 빛을 띄운다.', k:'evade', dc:22, cost:{ mana:28 }, wake:1,
        ok:`반대편 끝에 빛을 띄웠다. 등불 모양. 그리고 그 빛에 온기를 그려 넣었다. 해 본 적 없다. 손바닥에 남은 등불 온기를 떠올려 옮겼다.<br><br>기는 소리가 그쪽으로 갔다. 빠르게. 빛 둘레를 맴돈다. 핥는 소리가 난다. 빛이 따뜻하다.<br>이쪽은 어둠 속에서 벽을 더듬어 반대로 갔다. 문을 찾았다.<br><br>문을 나와서 손바닥을 봤다. 차다. 온기를 저쪽으로 다 보냈다. 보이는 것만 만들던 손이 이제 느껴지는 것도 만든다. 그 값으로 손이 차다.`,
        ng:`빛을 띄웠는데 온기가 안 실렸다. 그것은 빛을 지나쳤다.<br><br>어둠에서 이쪽 온기 쪽으로 온다. 살 온도다. 빛보다 따뜻하다. 다리에 무엇이 닿았다. 비늘 같은 것. 감는다.<br>뿌리치고 벽을 따라 뛰었다. 문에 부딪쳤다. 열었다. 다리에 감긴 자국이 나선으로 남았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 불을 끈 채 숨을 줄이고 기다린다.', k:'steady', dc:23,
        ok:`불을 끄고 가만히 섰다. 숨을 줄였다. 어둠 속에서 기는 것도 멈췄다.<br><br>오래 기다렸다. 어둠 속에서 다른 쪽으로 기는 소리가 났다. 다른 불빛을 찾아갔다. 멀리서 누가 불을 켰는지도 모른다.<br>소리가 멀어진 뒤 불 없이 벽을 더듬어 나왔다.<br><br>나와서 불을 켜자 손등에 하얀 비늘 하나가 붙어 있다. 언제 지나갔는지 모른다.`,
        ng:`기다리는데 어둠 속에서 숨소리가 났다. 이쪽 숨 박자로.<br><br>바로 앞이다. 그것도 기다린다. 누가 먼저 움직이나. 다리가 저렸다. 휘청했다. 그것이 왔다.<br>등불을 켜서 휘둘렀다. 빛에 그것이 멈칫한 틈에 뛰었다. 팔에 긁힌 자국이 셋 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
    ] },

  { at:'A', t:'문 너머 — 다시 같은 방',
    x:`문을 열고 나왔다. 같은 방이다. 또 열었다. 같은 방이다.<br><br>
    의자 셋, 창 하나, 벽에 걸린 달력. 달력 날짜가 같다. 넷째 문을 열자 의자가 넷이다.<br>
    환영술사는 남이 만든 환영을 알아본다. 이음매가 있다. 빛이 안 맞는 데가 있다.<br><br>
    넷째 의자에 누가 앉아 있다. 등을 보이고.`,
    o:[
      { l:'① 방의 이음매를 찾는다.', k:'gaze', dc:23, wake:1,
        ok:`방을 그림으로 봤다. 벽, 창, 달력. 빛이 어디서 오는지 봤다. 창에서다. 그런데 그림자는 창 쪽으로 진다.<br><br>빛과 그림자가 거꾸로다. 그린 쪽이 빛을 그리고 그림자를 따로 그렸다. 둘이 만나는 데가 이음매다. 창틀 아래 한 줄.<br>그 줄에 손톱을 넣고 그었다. 방이 종이처럼 벌어졌다. 그 너머에 진짜 복도가 있다.<br><br>복도로 나오며 알았다. 남의 환영을 찢는 데에는 마력이 안 든다. 이음매만 알면 손톱으로 된다. 남의 그림에서 이쪽 손이 들어갈 자리가 보인다.`,
        ng:`이음매를 찾는데 넷째 의자에 앉은 것이 돌아앉았다.<br><br>얼굴이 이쪽 얼굴이다. 이쪽보다 조금 늙었다. 이 방에 오래 있었다. 그것이 말했다. 나도 찾았어. 이음매.<br>문을 열었다. 같은 방이다. 의자가 다섯이다. 다섯째가 비었다. 동료가 이쪽을 끌고 문을 여러 번 열어 겨우 나왔다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
      { l:'② 마력으로 벽에 문을 그려 넣고 나간다.', k:'evade', dc:23, cost:{ mana:30 },
        doom:{ title:'그린 문', what:'그린 문 안쪽 벽 속으로 끌려 들어갑니다', dc:18, sec:50,
          text:`벽에 문을 그렸다. 손잡이까지. 남의 환영 위에 이쪽 환영을 덧그렸다. 문을 열었다.<br><br>열린 문 너머가 벽 속이다. 회반죽과 각목 사이. 거기 사람이 줄지어 서 있다. 벽 안에. 다들 문을 그리던 손 모양으로 손을 들고 있다.<br>손 하나가 이쪽 손목을 잡았다. 들어오라고. 당긴다. 몸 반이 벽 속으로 끌려 들어갔다. 회반죽이 등을 감싼다. 굳어 간다.<br><br>남의 그림 위에 그림을 그리면 둘 다 그 그림 것이 된다.`,
          dieText:`남의 환영에 덧그리지 않는다. 예의가 아니라 규칙이다. 예전에도 배웠다.<br><br>같은 방이다. 의자 셋, 창 하나, 달력.<br>벽에 문이 하나 그려져 있다. 손잡이까지. 그 옆에 손 모양 얼룩이 하나 있다.` },
        ok:`문을 그리되 벽 위가 아니라 바닥에 그렸다. 남의 그림 가장자리 밖에.<br><br>바닥은 이 방 그림에서 덜 그려진 데다. 그린 쪽이 벽에만 공을 들였다. 이쪽 문이 바닥에서 열렸다. 아래로 계단이 있다. 진짜 계단이다.<br>내려가서 문을 닫았다. 위에서 의자 끄는 소리가 났다.<br><br>남의 그림에서 덜 그린 데를 찾아 이쪽 것을 그렸다. 거기만은 이쪽 것이다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 동료 손을 잡고 다 같이 눈을 감고 걷는다.', k:'bond', dc:22,
        ok:`동료 손을 잡았다. 다 같이 눈을 감았다. 환영은 보는 눈에만 있다.<br><br>눈 감고 걸었다. 의자에 무릎이 부딪쳤다. 의자는 진짜다. 벽을 손으로 짚었다. 벽도 진짜다. 그런데 문이 있던 자리는 손에 아무것도 안 닿았다. 그냥 지나갔다.<br>열 걸음쯤에서 바람이 달라졌다. 눈을 떴다. 복도다.<br><br>뒤를 보니 방이 없다. 벽만 있다. 그 벽에 손자국이 여럿 찍혀 있다. 이쪽 일행보다 하나가 많다.`,
        ng:`눈 감고 걷는데 잡은 손이 하나 늘었다.<br><br>오른손에 동료 손, 왼손에도 손이 있다. 왼쪽엔 아무도 없었다. 차다. 놓으려 했다. 안 놓는다. 눈을 떴다. 같은 방이다. 왼손이 비었다.<br>다시 눈 감고 걸었다. 겨우 나왔다. 왼손바닥에 손금이 하나 더 그어졌다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
    ] },

  { at:'A', t:'복도 — 손을 내미는 아이',
    x:`복도 가운데 작은 것이 서 있다. 아이 키다. 손을 내민다. 같이 가자는 손이다.<br><br>
    얼굴은 그늘에 가렸다. 손만 보인다. 손가락이 작고 하얗다. 손톱 밑이 까맣다.<br>
    지나가려면 그 옆을 지나야 한다. 벽에 긁힌 자국이 길다. 손을 안 잡고 지나가려던 이의 자국이다.<br><br>
    환영술사는 손 하나쯤은 금방 만든다.`,
    o:[
      { l:'① 마력으로 환영 손을 만들어 대신 잡게 한다.', k:'evade', dc:23, cost:{ mana:28 },
        doom:{ title:'잡은 손', what:'아이 손에 이끌려 복도 끝 어둠으로 끌려갑니다', dc:18, sec:50,
          text:`환영 손을 만들어 내밀었다. 이쪽 손 모양이다. 아이가 잡았다.<br><br>잡은 순간 환영 손에 무게가 생겼다. 아이가 잡은 데부터 살이 됐다. 환영이 진짜가 된다. 진짜가 된 손은 이쪽 손목에 붙어 있다.<br>아이가 걷는다. 끈다. 복도 끝 어둠으로. 팔이 끌려간다. 몸이 따라간다. 발이 미끄러진다.<br><br>그늘 아래 얼굴이 웃는다. 이제 같이 가.`,
          dieText:`맞는 것은 늘 진짜가 아닌 쪽이다. 잡힌 쪽이 진짜가 되면 이야기가 다르다.<br><br>복도 가운데 작은 것이 둘 서 있다. 손을 잡고.<br>남은 손 하나를 내민다. 같이 가자고.` },
        ok:`환영 손을 만들되 손목에서 떼어 냈다. 손만 띄웠다.<br><br>아이가 환영 손을 잡았다. 손에 무게가 생겼다. 살이 됐다. 그런데 이쪽 몸에 안 붙었다. 손 하나만 진짜가 됐다. 아이가 그 손을 잡고 걸어갔다. 어둠으로.<br>그 옆을 지났다.<br><br>복도 끝에서 돌아봤다. 어둠 속에서 아이가 손을 흔든다. 이쪽 손 모양을 한 손으로.`,
        win:{ exp:24, dream:3 } },
      { l:'② 손을 못 본 척 벽에 붙어 옆걸음으로 지난다.', k:'steady', dc:22,
        ok:`손을 안 봤다. 벽을 보고 옆걸음으로 지났다. 아이가 손을 따라 돌린다. 이쪽 쪽으로.<br><br>아이 옆을 지날 때 소매가 손끝에 스쳤다. 소매만. 아이가 소매 끝을 잡으려다 놓쳤다. 작은 한숨이 났다.<br>복도를 다 지났다.<br><br>소매 끝이 까맣다. 손톱 밑의 그 색이다. 털어도 안 털린다.`,
        ng:`옆걸음 하는데 아이가 따라 옆걸음 했다. 이쪽 앞에서.<br><br>손이 이쪽 손을 찾아온다. 피했다. 벽에 등이 긁혔다. 손이 손등을 잡았다. 작은 손이 놀랍게 세다. 뿌리쳤다. 손톱이 손등을 그었다.<br>복도 끝까지 뛰었다. 손등에 까만 줄이 넷. 피가 한참 안 멈춘다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } }
    ] },

  { at:'A', t:'계단참 — 하나 남는 그림자',
    x:`계단참 벽에 일행 그림자가 비친다. 등불 하나에 그림자들.<br><br>
    하나가 많다. 그림자 하나가 남는다. 누구 것도 아니다. 일행이 움직이면 같이 움직인다. 조금 늦게.<br>
    남는 그림자는 계단 쪽에 서 있다. 내려가려면 그 그림자를 지나야 한다.<br><br>
    환영술사는 그림자도 만든다. 지우는 것도 된다.`,
    o:[
      { l:'① 마력으로 일행 그림자를 다 지워 남는 것을 드러낸다.', k:'gaze', dc:22, cost:{ mana:28 },
        ok:`손을 펴서 일행 그림자를 하나씩 지웠다. 빛 모양을 바꿔서. 벽이 맨벽이 된다.<br><br>하나만 남았다. 지울 수 없다. 이쪽이 만든 게 아니다. 빛 때문에 생긴 것도 아니다. 그림자가 아니라 벽에 붙은 것이다.<br>지워진 그림자들 사이에서 혼자 드러나자 그것이 당황한 듯 벽을 타고 위로 올라갔다. 계단이 비었다.<br><br>그림자를 돌려놓고 내려갔다. 위쪽 벽에서 무엇이 이쪽 정수리를 내려다본다.`,
        ng:`그림자를 지우는데 남는 것도 같이 흐려졌다. 흉내를 낸다.<br><br>다 지웠다. 벽이 맨벽이다. 남는 것이 어디 갔는지 모르게 됐다. 계단을 내려갔다. 발목에 찬 것이 감겼다. 벽에서 떨어져 나온 것이다.<br>떼어 냈다. 발목에 그림자처럼 검게 멍이 들었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 남는 그림자 옆에 그림자 하나를 더 세운다.', k:'evade', dc:23, wake:1,
        ok:`등불 빛을 휘어 이쪽 그림자를 하나 더 만들었다. 남는 그림자 바로 옆에. 하나가 더 남게.<br><br>남는 그림자가 옆을 봤다. 저 같은 것이 하나 더 있다. 흔들렸다. 진짜를 고르려 한다. 고르는 사이에 일행이 계단을 내려갔다.<br>마지막에 이쪽이 내려가며 만든 그림자를 거뒀다.<br><br>거둔 다음에도 그림자가 벽에 잠깐 붙어 있었다. 등불이 비키고 나서도. 만든 것이 손을 떠나서도 서 있는 시간이 늘었다. 숨 한 번만큼. 그 숨 한 번이면 많은 걸 속인다.`,
        ng:`그림자를 세웠는데 남는 그림자가 그걸 먹었다.<br><br>그림자가 커졌다. 둘을 합친 크기다. 계단 쪽을 다 막았다. 등불이 흔들렸다. 그림자가 이쪽 그림자를 잡았다. 발이 바닥에 붙었다.<br>등불을 들어 빛을 비틀었다. 그림자가 풀렸다. 다리가 한참 저렸다. 계단을 기어 내려갔다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-18 } }
    ] },

  { at:'A', t:'방 — 숨바꼭질',
    x:`방 안에서 목소리가 센다. 하나, 둘, 셋. 아이 목소리다. 벽을 보고 센다.<br><br>
    열까지 세면 찾으러 온다. 숨지 못한 것은 술래가 된다. 숨을 데가 별로 없다. 옷장, 침대 밑, 커튼 뒤.<br>
    옷장 문이 조금 열렸다. 안에 신발이 있다. 술래가 된 신발이다.<br><br>
    환영술사는 숨는 대신 모양을 바꾼다. 일곱.`,
    o:[
      { l:'① 마력으로 이쪽 위에 의자 모양을 씌운다.', k:'hide', dc:22, cost:{ mana:28 },
        ok:`방 구석에 쪼그려 앉아 이쪽 위에 의자를 그렸다. 방에 있던 의자와 같은 모양으로. 의자가 하나 늘었다.<br><br>열. 목소리가 돌아섰다. 찾는다. 옷장을 열고, 침대 밑을 보고, 커튼을 걷었다. 의자 앞에서 멈췄다. 의자가 하나 많다.<br>작은 손이 등받이를 짚었다. 환영이다. 손이 쑥 들어왔다. 어깨에 닿기 직전에 멈췄다. 이상하네. 그리고 갔다.<br><br>목소리가 다시 센다. 하나, 둘. 그 틈에 방을 나왔다. 어깨에 손가락 끝 온도가 남았다.`,
        ng:`의자를 그렸는데 방에 있던 의자들과 다리 수가 달랐다. 셋이다.<br><br>목소리가 웃었다. 찾았다. 다리 셋 의자가 술래야. 손이 의자를 뚫고 들어와 손목을 잡았다. 환영을 거두고 뛰었다.<br>문 밖으로 나왔다. 손목에 작은 손 자국. 목소리가 등 뒤에서 센다. 이번엔 네가 술래야.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 이쪽 모양 환영을 방 곳곳에 숨긴다.', k:'evade', dc:23,
        ok:`이쪽 모양 환영을 셋 만들어 옷장, 침대 밑, 커튼 뒤에 숨겼다. 일부러 조금씩 삐져나오게.<br><br>열. 목소리가 찾는다. 커튼 뒤에서 하나. 찾았다! 환영이 흩어졌다. 옷장에서 하나. 찾았다! 흩어졌다. 침대 밑에서 하나.<br>세 번 찾고 세 번 다 흩어졌다. 목소리가 멈췄다. 화가 났다. 그 사이 이쪽은 문 뒤로 빠져나갔다.<br><br>복도에서 들었다. 방 안에서 목소리가 운다. 하나도 못 잡았다고. 울음이 길다. 끝에 웃음이 섞인다.`,
        ng:`환영 셋을 숨겼는데 목소리가 하나도 안 찾았다.<br><br>똑바로 이쪽에게 왔다. 숨지도 않은 이쪽에게. 찾는 척도 안 했다. 처음부터 진짜를 안다. 작은 손이 소매를 잡았다. 뿌리쳤다. 소매가 찢겼다.<br>방을 나왔다. 숨긴 환영 셋이 방 안에 그대로 남았다. 거둘 수가 없다. 줄이 끊겼다. 머리가 깨질 듯 아프다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-22 } },
      { l:'③ 술래가 된 신발을 본다.', k:'gaze', dc:22,
        ok:`옷장 안 신발을 봤다. 끈이 묶인 채다. 벗은 게 아니다. 발이 빠져나간 신발이다.<br><br>신발 앞코가 옷장 안쪽을 향했다. 술래는 벽을 보고 센다. 옷장 안쪽 벽이 술래 자리다. 술래가 되면 옷장 안에서 센다.<br>그래서 옷장도 침대 밑도 커튼 뒤도 아닌, 열린 문 바로 뒤에 섰다. 술래는 문을 안 찾는다. 문은 나가는 데라서.<br><br>열. 목소리가 방을 다 뒤지고 못 찾았다. 그 사이 문 뒤에서 그대로 나왔다.`,
        ng:`신발을 보는데 옷장 안에서 목소리가 났다. 아홉.<br><br>세는 목소리가 둘이다. 하나는 방에서, 하나는 옷장에서. 옷장 안 목소리는 이쪽 바로 앞이다. 열. 옷장 문이 열렸다.<br>안에 아무도 없다. 신발만 이쪽을 향해 돌아앉았다. 방을 뛰쳐나왔다. 한참 숨이 안 돌아왔다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-20 } }
    ] },

  { at:'A', t:'끝 — 이쪽 모양을 쓴 것',
    x:`앞에 이쪽이 서 있다.<br><br>
    환영이 아니다. 이쪽은 아무것도 안 띄웠다. 저것이 이쪽 모양을 쓰고 있다. 이음매가 없다. 이쪽보다 잘 만들었다.<br>
    이쪽이 손을 들자 저것도 든다. 이쪽이 환영을 띄우자 저것도 띄운다. 똑같이. 저것의 환영이 이쪽 환영을 덮는다.<br><br>
    환영술사가 환영으로 지는 날이 있다.`,
    o:[
      { l:'① 띄운 것을 다 거두고 맨몸으로 지난다.', k:'evade', dc:23, wake:1,
        ok:`띄운 것을 다 거뒀다. 맨몸이다. 저것도 거뒀다. 맨몸이다. 똑같다.<br><br>걸었다. 저것도 걷는다. 이쪽에게로. 마주 걷는다. 부딪치기 직전에 이쪽만 반 걸음 옆으로 갔다. 아무 생각 없이. 저것은 그대로 왔다. 흉내 낼 것이 없는 걸음이었다.<br>저것이 이쪽이 있던 자리를 지나쳤다. 등 뒤로 갔다. 이쪽은 앞으로 갔다.<br><br>그제야 알았다. 아무것도 안 띄운 이쪽도 하나의 모양이다. 저쪽은 그걸 못 따라 했다. 꾸미지 않은 걸음이 가장 따라 하기 어려운 환영이다.`,
        ng:`거뒀는데 저것은 안 거뒀다.<br><br>저것이 띄운 이쪽 모양들이 이쪽을 둘러쌌다. 열. 다 이쪽 얼굴이다. 진짜가 어느 것인지 동료들이 모른다. 동료 하나가 이쪽을 밀쳤다. 가짜인 줄 알고.<br>벽에 머리를 부딪쳤다. 저것들이 흩어졌다. 머리에서 피가 났다. 동료는 미안하다는 말을 못 했다.`,
        win:{ exp:25, dream:3 }, lose:{ hp:-30, spirit:-22 } },
      { l:'② 마력을 쏟아 저것의 모양을 대신 띄운다.', k:'evade', dc:22, cost:{ mana:32 },
        ok:`마력을 쏟았다. 이쪽 모양을 하나, 둘, 다섯. 저것이 따라 띄운다. 하나, 둘, 다섯.<br><br>여섯째에 이쪽 모양 대신 저것의 모양을 띄웠다. 저것이 따라 띄웠다. 저것의 모양을. 저것들끼리 구별이 안 된다.<br>저것들 사이에서 진짜 저것이 멈칫했다. 어느 것이 자기인지. 그 틈에 지났다.<br><br>마력이 바닥났다. 손끝이 하얗다. 등 뒤에서 저것들이 서로를 본다.`,
        ng:`다섯째에서 마력이 끊겼다. 저것은 안 끊겼다. 여섯, 일곱.<br><br>저것의 모양들이 이쪽 것들을 하나씩 덮어 지웠다. 마지막에 이쪽만 남았다. 저것이 이쪽 앞에 섰다. 이쪽 얼굴로 웃었다. 이쪽 손으로 이쪽 뺨을 쓸었다.<br>뒤로 넘어지며 굴러 빠져나왔다. 뺨에 손가락 자국이 붉다. 물에 비친 얼굴을 볼 때마다 그 자국이 웃는다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-20 } }
    ] },

  { at:'A1', t:'부조정실 — 모니터 벽',
    x:`부조정실 벽 한 면이 모니터다. 수십 개. 방송국 곳곳이 나온다. 복도, 계단, 방청석, 동산 세트.<br><br>
    화면 하나에 이쪽 일행이 나온다. 지금 이 방이다. 다 있다. 한 사람이 더 있다. 화면 속 이쪽 바로 뒤에.<br>
    뒤를 보면 없다. 화면에만 있다.<br><br>
    환영술사의 환영은 눈을 속인다. 카메라는 눈이 아니다.`,
    o:[
      { l:'① 화면에 찍히는 것과 안 찍히는 것을 견주어 본다.', k:'gaze', dc:22, wake:1,
        ok:`손바닥에 작은 환영을 띄웠다. 나비. 화면을 봤다. 화면 속 손바닥에 나비가 없다. 카메라는 환영을 안 찍는다.<br><br>그러면 화면 속 이쪽 뒤에 선 것은 환영이 아니다. 진짜다. 눈에만 안 보이는 진짜. 환영과 정반대다.<br>그것이 화면 속에서 이쪽 어깨에 손을 올리려 한다. 화면을 보면서 어깨를 비켰다. 손이 빈 데에 내려앉는다. 화면 속에서.<br><br>눈으로 못 보는 것은 화면으로 보고, 화면이 못 보는 것은 눈으로 본다. 보이는 것과 찍히는 것 사이에 틈이 있다. 그 틈을 보는 눈이 생겼다.`,
        ng:`화면을 보다가 화면 속 이쪽과 눈이 마주쳤다. 화면 속 이쪽이 이쪽을 본다.<br><br>카메라는 다른 데를 찍는데 화면 속 얼굴이 고개를 돌려 이쪽을 본다. 그 뒤의 것도. 둘이 같이 웃는다. 화면 속에서.<br>모니터 벽이 일제히 그 장면으로 바뀌었다. 수십 개의 웃는 이쪽. 눈을 감고 방을 나왔다. 눈꺼풀 안에서도 한참 웃는다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } },
      { l:'② 모니터 전원을 하나씩 내린다.', k:'fix', dc:22,
        ok:`모니터 밑 스위치를 하나씩 내렸다. 화면이 하나씩 까매진다. 복도, 계단, 방청석.<br><br>이 방 화면만 남았다. 스위치를 내렸다. 안 꺼진다. 화면 속 이쪽 뒤의 것이 화면 쪽으로 고개를 돌렸다. 꺼지기 싫어한다.<br>전원 줄을 뽑았다. 화면이 꺼지면서 까만 유리에 이쪽 일행이 비쳤다. 뒤에 아무도 없다.<br><br>방을 나왔다. 복도 스피커에서 언니 목소리가 났다. 화면 꺼진 친구들, 어디 갔니?`,
        ng:`스위치를 내리자 다른 화면들이 켜졌다. 끈 만큼 켜진다.<br><br>새로 켜진 화면들이 다 이 방이다. 각도만 다르다. 화면마다 이쪽 뒤에 그것이 있다. 각도마다 조금씩 더 가깝다.<br>뛰쳐나왔다. 문을 닫으며 어깨에 무게가 실렸다. 문 밖에서 보니 어깨에 손자국이 젖어 있다. 화면 밖으로 나온 손이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } }
    ] },

  { at:'A1', t:'방청석 — 앞으로 나와 볼 친구',
    x:`바람잡이가 마이크를 든다. 오려 붙인 사진 얼굴이 방청석을 훑는다. 앞으로 나와 볼 친구?<br><br>
    아무도 손을 안 들면 바람잡이가 고른다. 고르는 쪽은 늘 제일 조용한 쪽이다. 지금 방청석에서 제일 조용한 쪽은 이쪽 일행이다.<br>
    대기실 포스터의 첫째 규칙. 박수는 크게.<br><br>
    환영술사에게 손 하나 드는 건 일도 아니다. 이쪽 손이 아니어도.`,
    o:[
      { l:'① 마력으로 맨 앞줄에 손 든 아이 환영을 세운다.', k:'evade', dc:23, cost:{ mana:30 },
        doom:{ title:'오늘의 친구', what:'환영과 이어진 줄째 무대로 끌려 나갑니다', dc:18, sec:50,
          text:`맨 앞줄에 아이 환영을 세웠다. 손을 번쩍 들게 했다. 저요!<br><br>사진 얼굴이 활짝 웃는다. 그래, 너! 보이지 않는 손들이 환영을 들어 올려 무대로 넘긴다. 환영은 들리지 않는다. 여기 손들은 든다.<br>무대 위에서도 환영을 놓지 않았다. 줄이 이쪽 손끝에서 무대까지 이어진다. 손들이 그 줄을 찾았다. 줄을 감아 당긴다. 몸이 의자에서 들린다. 줄을 따라 무대로 끌려 나간다.<br><br>박수가 쏟아진다. 친구가 친구를 데려왔네!`,
          dieText:`환영은 들리지 않는다. 여기서는 들렸다.<br><br>그날 오늘의 친구는 둘이었다. 손을 잡고 나왔다.<br>하나는 끝까지 박수를 안 쳤다.` },
        ok:`아이 환영을 세워 손을 들게 한 다음 바로 줄을 끊었다. 환영 혼자 남게.<br><br>그래, 너! 손들이 환영을 무대로 넘긴다. 무대 위에서 환영이 손을 흔든다. 시키지 않았다. 끊긴 환영은 혼자 할 줄 안다.<br>방청석 전체가 무대를 본다. 그 틈에 일행이 출구로 갔다.<br><br>나가기 전에 무대를 봤다. 환영이 인형탈들 사이에서 웃고 있다. 그려 넣은 입이다. 이쪽이 그려 준 적 없는 입이다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 박수를 크게 친다.', k:'fix', dc:22,
        ok:`박수를 크게 쳤다. 일행에게도 치게 했다. 방청석에서 제일 시끄러운 쪽이 됐다.<br><br>사진 얼굴이 이쪽을 지나친다. 시끄러운 쪽은 안 고른다. 시끄러운 건 방청객이 잘하는 일이다.<br>바람잡이가 다른 쪽을 골랐다. 빈자리다. 빈자리에서 무엇이 일어나 무대로 갔다.<br><br>손바닥이 빨갛게 부었다. 박수를 멈추는 게 무서워서 한참 쳤다.`,
        ng:`박수를 쳤는데 박자가 스피커와 어긋났다.<br><br>사진 얼굴이 어긋난 박자를 찾아 이쪽을 봤다. 박수 잘 치는 친구! 손들이 이쪽 손목을 잡아 위로 들었다. 손 든 꼴이 됐다.<br>손목을 비틀어 뺐다. 손목이 접질렸다. 바람잡이가 아쉬운 얼굴로 다른 쪽을 본다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } },
      { l:'③ 사진 얼굴의 들뜬 테두리를 본다.', k:'gaze', dc:22,
        ok:`사진 얼굴을 봤다. 오려 붙인 테두리가 들떴다. 테두리 밑에 진짜 얼굴이 있다. 아주 조금 보인다.<br><br>진짜 얼굴은 눈을 감았다. 잠들었다. 사진이 대신 본다. 사진은 그려진 눈이라 한쪽만 본다. 눈동자 그림이 오른쪽으로 쏠렸다.<br>사진이 못 보는 왼쪽으로 일행을 옮겼다. 사진은 끝까지 오른쪽만 훑었다.<br><br>출구에서 돌아보니 사진 테두리가 한 번 들렸다. 밑의 눈꺼풀이 떨렸다. 깨어날 것 같다.`,
        ng:`테두리 밑을 보려고 가까이 갔다. 너무 가까이.<br><br>테두리 밑에서 진짜 눈이 떠졌다. 사진 얼굴과 진짜 눈이 같이 이쪽을 본다. 가까이 온 친구! 마이크가 이쪽을 가리켰다.<br>뛰어 물러났다. 손들이 옷자락을 잡았다. 찢고 출구로 뛰었다. 옆구리를 의자 팔걸이에 찧었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-20 } }
    ] },

  { at:'A1', t:'의상실 — 열린 지퍼',
    x:`의상실 레일에 인형탈이 걸렸다. 방글이, 뭉치, 삐뚤이. 머리는 위 칸에 따로. 몸통만 축 늘어졌다.<br><br>
    등 지퍼가 다 열렸다. 레일이 아주 천천히 돈다. 덜, 덜. 열린 탈들이 사람 지나가는 쪽으로 몸을 돌린다. 빈 속을 채우고 싶어 한다.<br>
    건너편 문까지 탈 사이를 지나야 한다.<br><br>
    환영술사는 빈 데를 채우는 일을 안다. 무게 없는 것으로.`,
    o:[
      { l:'① 마력으로 탈마다 안을 채우고 지퍼를 올린다.', k:'evade', dc:22, cost:{ mana:30 }, wake:1,
        ok:`열린 탈 하나에 환영을 채웠다. 사람 모양은 그리지 않았다. 안이 찼다는 느낌만 그렸다. 묵직함, 온기. 지퍼를 올렸다. 지익. 탈이 몸을 바로 했다.<br><br>찬 탈은 몸을 안 돌린다. 하나씩 채웠다. 다섯, 여섯. 레일이 돈다. 찬 탈들이 그냥 지나간다. 열 벌째에서 문에 닿았다.<br>문을 닫기 전에 봤다. 찬 탈들이 레일에 걸린 채 머리 없는 몸으로 손뼉을 친다. 박수 치라고 넣은 적 없다.<br><br>탈 안은 아무도 들여다보지 않는다. 보이지 않는 데에 그린 환영이다. 눈이 아니라 탈 자신을 속였다. 보이는 것만 만들던 손이 안 보이는 것을 만들었다.`,
        ng:`환영을 채우는데 탈이 환영을 먹었다. 순식간에. 다시 비었다. 더 배고프다.<br><br>탈들이 일제히 이쪽으로 몸을 돌렸다. 열린 지퍼가 다가온다. 하나가 등을 덮쳤다. 지퍼가 등을 물었다. 지익. 올라간다. 동료가 지퍼를 끌어내렸다.<br>탈을 벗어나 문으로 뛰었다. 등에 지퍼 자국이 한 줄 났다. 쇠 이빨 자국이다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 몸을 낮추고 숨을 가늘게 해 탈 사이를 지난다.', k:'hide', dc:23,
        ok:`몸을 낮추고 숨을 줄였다. 탈은 숨 쉬는 쪽으로 돈다. 숨을 아주 가늘게.<br><br>탈들이 옆을 지나간다. 몸통이 등을 쓴다. 털, 털, 깃털. 열린 지퍼가 머리카락을 스친다. 돌지는 않는다.<br>문에 닿았다. 문틀을 잡고 첫 숨을 쉬었다.<br><br>그 숨에 탈 하나가 몸을 돌렸다. 방글이다. 지퍼가 이쪽을 향해 벌어진다. 문을 닫았다. 문 너머에서 지퍼 닫히는 소리가 났다. 아쉽다는 듯이.`,
        ng:`숨을 참았는데 심장이 컸다.<br><br>탈들이 심장 소리 쪽으로 돌았다. 뭉치 탈이 앞을 막았다. 지퍼 안이 따뜻하다. 좀약 냄새가 난다. 이쪽으로 기운다.<br>밀치고 지났다. 털이 입에 들어갔다. 문 밖에서 털을 뱉는데 계속 나온다. 목 안이 한참 간지럽다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
    ] },

  { at:'A1', t:'인형극 무대 — 손 인형',
    x:`인형극 무대다. 작은 무대 위로 손 인형 셋이 나와 있다. 방글이, 뭉치, 삐뚤이. 작게 만든 것이다.<br><br>
    인형들이 움직인다. 고개를 끄덕이고 손을 흔든다. 가림막 뒤에 손이 있어야 한다. 가림막 밑으로 다리가 안 보인다.<br>
    인형 셋이 동시에 이쪽을 본다. 같이 놀자. 녹음된 목소리다.<br><br>
    환영술사는 인형극을 안다. 안 보이는 데서 보이는 것을 움직이는 일이다. 같은 일이다.`,
    o:[
      { l:'① 무릎을 꿇고 가림막 밑을 들여다본다.', k:'gaze', dc:23,
        doom:{ title:'손 인형', what:'가림막 밑 손들에게 무대 안으로 끌려 들어갑니다', dc:18, sec:45,
          text:`무릎을 꿇고 가림막 밑을 봤다. 어둡다. 팔이 보인다. 위로 뻗은 팔 셋. 팔만 있다. 어깨가 없다. 팔이 바닥에서 바로 자랐다.<br><br>팔 하나가 인형을 벗었다. 맨손이 됐다. 이쪽을 향해 내려온다. 가림막 밑으로. 손목을 잡았다. 가림막 안으로 당긴다.<br>어깨가 들어갔다. 위에서 녹음된 목소리가 반긴다. 새 친구가 왔어요! 빈 인형 하나가 이쪽 손 위로 씌워진다.<br><br>팔이 위로 들린다. 무대 위로. 이쪽 손에 낀 인형이 손을 흔든다.`,
          dieText:`안 보이는 데서 보이는 것을 움직이는 일. 같은 일이었다.<br><br>인형극 무대 위로 손 인형이 넷 나와 있다.<br>넷째 인형이 제일 잘 움직인다. 조금 슬프게.` },
        ok:`가림막 밑을 보되 이쪽 얼굴 대신 얼굴 환영을 먼저 들이밀었다.<br><br>밑에서 팔 하나가 인형을 벗고 얼굴 환영을 잡으려 했다. 손이 환영을 지나 빈 데를 쥐었다. 바닥에서 자란 팔이 셋. 어깨가 없다.<br>그걸 알고 일어섰다. 바닥에서 자란 팔은 뻗는 만큼만 뻗는다. 무대 반경을 피해 돌아갔다.<br><br>등 뒤에서 녹음된 목소리가 서운해한다. 가지 마. 팔 셋이 인형을 다시 꼈다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 마력으로 넷째 인형을 세워 극을 끝낸다.', k:'evade', dc:22, cost:{ mana:28 },
        ok:`무대 앞에서 손을 들어 마력으로 넷째 인형을 그렸다. 방글이를 닮게. 무대 위에 세웠다.<br><br>이쪽 인형이 인사했다. 오늘 공연 끝! 인형 셋이 멈칫했다. 녹음 목소리가 따라 했다. 끝! 인형 셋이 무대 밑으로 내려갔다.<br>막이 내렸다. 저절로. 그 사이 지났다.<br><br>마력을 거두는데 이쪽 인형이 막 뒤에서 잠깐 남아 있었다. 손을 흔들고 있었다. 막이 다 내려서야 사라졌다.`,
        ng:`이쪽 인형을 세웠는데 인형 셋이 이쪽 인형을 둘러쌌다.<br><br>같이 놀자. 셋이 이쪽 인형을 끌고 무대 밑으로 들어갔다. 마력 줄이 팽팽해졌다. 끊었다. 끊는 순간 손끝이 터졌다.<br>무대를 피해 돌아갔다. 손끝 피가 안 멈춘다. 무대 밑에서 넷째 목소리가 웃는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A1', t:'녹음 부스 — 언니의 목소리',
    x:`녹음 부스다. 유리창 너머 마이크 하나. 그 앞에 아무도 없다. 테이프가 돈다.<br><br>
    스피커에서 노래 언니 목소리가 나온다. 친구들, 이리 와요. 복도의 장갑들이 그 소리를 따라 이 방으로 몰려온다. 문 밑으로 하얀 손가락들이 보인다.<br>
    언니 목소리는 장갑을 부른다. 장갑은 그 목소리만 듣는다.<br><br>
    환영술사는 목소리도 만든다. 모양이 있으니까.`,
    o:[
      { l:'① 마력으로 언니 목소리를 지어 장갑들을 다른 데로 부른다.', k:'evade', dc:22, cost:{ mana:30 }, wake:1,
        ok:`테이프의 언니 목소리를 들었다. 높이, 떨림, 숨 쉬는 자리. 마력으로 그 목소리를 지었다. 복도 저편에 놓았다. 친구들, 이쪽이에요.<br><br>문 밑 손가락들이 멈칫했다. 목소리가 둘이다. 하나는 이 방, 하나는 저편. 저편이 조금 더 다정하다. 더 다정하게 지었다.<br>손가락들이 저편으로 갔다. 복도가 비었다.<br><br>지은 목소리가 저편에서 계속 부른다. 이쪽은 이미 다른 말을 하는데. 소리로 그린 것이 그림보다 오래 남는다. 소리 환영은 눈에 기대지 않는다. 귀만 있으면 된다.`,
        ng:`목소리를 지었는데 숨 쉬는 자리가 틀렸다.<br><br>장갑들이 멈췄다. 틀린 숨을 들었다. 진짜 언니는 거기서 숨을 안 쉰다. 손가락들이 틀린 목소리가 나온 데를 찾았다. 이쪽 입이다.<br>문 밑으로 장갑이 밀려 들어왔다. 발목을 덮었다. 걷어차며 부스 안으로 피했다. 정강이에 장갑 손가락 자국이 줄줄이.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-22 } },
      { l:'② 테이프를 멈춘다.', k:'fix', dc:22,
        ok:`부스로 들어가 테이프 기계의 정지 단추를 눌렀다. 딸깍.<br><br>목소리가 멎었다. 문 밑 손가락들이 멈췄다. 부르는 소리가 없다. 어디로 갈지 모른다. 손가락들이 바닥을 더듬다 흩어졌다.<br>복도가 조용해졌다. 너무 조용하다.<br><br>나가려는데 테이프가 혼자 돌기 시작했다. 거꾸로. 거꾸로 도는 언니 목소리가 무슨 말을 한다. 거꾸로라 알아들을 수 없다. 다행이다.`,
        ng:`정지 단추를 눌렀는데 안 멈춘다. 단추가 눌린 채 테이프가 돈다.<br><br>언니 목소리가 이쪽 이름을 불렀다. 테이프에 이쪽 이름이 녹음되어 있다. 친구야, 언니가 기다렸어. 문 밑 손가락들이 일제히 이쪽을 향했다.<br>기계 전원을 뽑고 부스 문을 등으로 막았다. 장갑들이 유리를 두드렸다. 오래. 그 박자에 귀가 먹먹하다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-20 } },
      { l:'③ 테이프 공책에서 부르는 순서를 찾는다.', k:'gaze', dc:23,
        ok:`테이프 딱지를 봤다. 같은 회차 번호가 줄줄이다. 같은 날을 계속 녹음했다.<br><br>테이프 옆 공책에 진행 순서가 있다. 언니 목소리가 부르는 순서. 복도, 계단, 방청석, 이 방. 그다음은 세트다.<br>그 순서를 기다렸다. 부르는 소리가 세트로 옮겨 갔다. 장갑들이 그리 갔다. 그 사이 나왔다.<br><br>공책 맨 아래에 연필로 한 줄. 대본에 없는 말이다. 오지 마.`,
        ng:`딱지를 보는데 회차 날짜가 오늘이다. 오늘 녹음했다.<br><br>누가 녹음했는지 마이크 앞을 봤다. 아무도 없다. 마이크 망에 입김이 서렸다. 아직 따뜻하다. 장갑들이 문 밑으로 들어왔다.<br>뛰쳐나왔다. 장갑 하나가 등에 붙어 따라 나왔다. 떼는 데 한참 걸렸다. 등에 손바닥 자국이 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-24 } }
    ] },

  { at:'A2', t:'종탑 — 출석 칠판',
    x:`종탑 벽에 칠판이 걸렸다. 출석 칠판이다. 반, 번호, 이름. 이름 옆에 동그라미.<br><br>
    분필이 칠판 홈에 놓였다. 가끔 혼자 일어나 이름을 쓴다. 새 이름이다. 맨 아래 칸에 막 쓴 이름이 있다. 이쪽 일행 중 하나다.<br>
    동그라미는 아직 없다. 점호 때 대답하면 동그라미가 쳐진다.<br><br>
    환영술사는 글씨도 그린다. 분필보다 빠르게.`,
    o:[
      { l:'① 마력으로 칠판의 동료 이름 위에 다른 이름을 덧그린다.', k:'evade', dc:22, cost:{ mana:28 },
        ok:`칠판에 쓰인 동료 이름 위에 환영 글씨를 덧그렸다. 아무 이름. 이 학교에 있었을 법한 이름.<br><br>분필이 일어났다. 동그라미를 치려고. 다가와서 멈췄다. 이름이 다르다. 분필이 칠판 위를 헤맨다. 제가 쓴 이름을 찾는다. 못 찾는다.<br>분필이 홈으로 돌아갔다.<br><br>환영을 그대로 두고 왔다. 거두면 이름이 다시 보인다. 마력이 조금씩 샌다. 종탑을 떠나서도 한참.`,
        ng:`덧그렸는데 분필이 환영 글씨 위에 동그라미를 쳤다.<br><br>아무 이름에 동그라미가 쳐졌다. 물 밑에서 대답이 났다. 네. 이쪽이 지어낸 이름에 누가 대답했다. 환영 글씨가 분필 글씨로 굳었다.<br>지어낸 이름이 칠판에 남았다. 이쪽이 만든 누군가가 물 밑에 생겼다. 그 생각이 떠나지 않는다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-22, spirit:-26 } },
      { l:'② 칠판 글씨를 맨 위부터 끝까지 본다.', k:'gaze', dc:22,
        ok:`칠판을 봤다. 맨 위부터. 이름마다 동그라미. 동그라미 없는 이름은 둘. 하나는 이쪽 동료. 하나는 오래된 이름. 3학년 2반 17번.<br><br>17번 옆에 동그라미가 그려졌다 지워진 자국이 여러 겹이다. 누가 계속 지웠다. 분필이 아니라 손가락으로.<br>동료 이름을 손가락으로 지웠다. 17번이 했던 것처럼. 분필이 일어났다가 빈칸을 보고 돌아갔다.<br><br>손가락 끝이 하얗다. 17번도 이 손가락을 했을 것이다.`,
        ng:`보는데 분필이 일어나 이쪽 이름을 썼다. 동료 이름 밑에.<br><br>또박또박. 모르는 글씨로 쓰니 남의 이름 같다. 손가락으로 지우려 했다. 안 지워진다. 칠판에 손바닥이 붙었다. 차다.<br>떼어 냈다. 손바닥 살갗이 하얗게 일어났다. 이름은 그대로다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-26 } }
    ] },

  { at:'A2', t:'기숙사 — 열둘을 맞추는 밤',
    x:`종이 아홉 번 울렸다. 밤 점호다. 복도에서 물 헤치는 소리와 열쇠 소리가 다가온다.<br><br>
    일행은 빈 호실 안에 있다. 침대가 열둘. 매트리스가 젖었다. 사감은 문을 열고 센다. 열둘이면 이상 없음이다. 하나가 많아도, 모자라도 이상이 있다.<br>
    이불이 부푼 침대가 일곱이다. 일행이 다 누워도 열둘이 안 된다.<br><br>
    환영술사는 수를 맞출 줄 안다. 보이는 수를.`,
    o:[
      { l:'① 마력으로 빈 침대마다 누운 환영을 채운다.', k:'evade', dc:22, cost:{ mana:30 }, wake:1,
        ok:`일행이 눕고 남은 빈 침대에 환영을 눕혔다. 이불 덮은 모양. 숨에 따라 오르내리게.<br><br>문이 열렸다. 안경 너머 눈이 센다. 하나, 둘. 열둘. 이상 없음. 문이 닫혔다.<br>열쇠 소리가 멀어졌다. 일어났다. 환영을 거두려는데 하나가 안 거둬졌다. 숨을 쉬고 있다. 이쪽이 그린 박자가 아니다.<br><br>그 하나는 두고 나왔다. 수가 맞으려면 그래야 했다. 오래 둔 환영은 제 박자를 갖는다. 이쪽이 붙잡고 있지 않아도 버틴다. 버티는 시간이 처음으로 이쪽 숨보다 길었다.`,
        ng:`환영을 눕혔는데 하나를 더 눕혔다. 셈이 틀렸다.<br><br>문이 열렸다. 하나, 둘. 열셋. 사감이 웃었다. 하나가 많네. 손가락 긴 손이 환영 침대를 짚었다. 환영이 꺼졌다. 손이 그 옆 침대를 짚었다. 이쪽 침대다.<br>이불째 끌려가기 전에 굴러 떨어졌다. 침대 밑 물에 잠겨 숨을 참았다. 사감이 지나갔다. 나와 보니 이불이 없다. 사감이 들고 갔다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
      { l:'② 수가 넘치면 동료 하나를 빈 매트리스로 가린다.', k:'hide', dc:23,
        ok:`셈해 보니 하나가 많다. 동료 하나 위에 빈 매트리스 모양을 덮었다. 사람 위에 빈 침대.<br><br>문이 열렸다. 센다. 열둘. 이상 없음. 빈 매트리스 위를 눈이 그냥 지나갔다.<br>문이 닫혔다. 환영을 거뒀다. 동료가 숨을 몰아쉰다. 빈 침대 밑에 깔린 느낌이었다고 한다.<br><br>그 동료는 그 뒤로 한동안 자꾸 제 손을 봤다. 있는지.`,
        ng:`덮었는데 빈 매트리스 위로 동료 숨이 올라왔다. 물결이 떴다.<br><br>사감 눈이 빈 매트리스에 멎었다. 빈 침대가 숨을 쉬네. 손이 매트리스를 눌렀다. 동료 가슴이 눌렸다. 동료가 기침했다. 환영을 거두고 동료를 끌어냈다.<br>문 밖으로 뛰었다. 등 뒤에서 열쇠 소리가 뛰어온다. 모퉁이까지 달렸다. 숨이 끊어질 듯하다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-20 } },
      { l:'③ 줄을 서서 차례로 대답한다.', k:'bond', dc:23,
        doom:{ title:'호실 점호', what:'사감 손에 호실 안으로 끌려 들어갑니다', dc:18, sec:45,
          text:`문이 열렸다. 대답하면 센다고 했다. 줄을 서서 차례로 대답했다. 네. 네.<br><br>사감이 이쪽 앞에서 멈췄다. 이름을 안 불렀는데 대답했네. 손가락이 길다. 손목을 잡았다. 차다. 장부를 쥐던 손이다.<br>당긴다. 침대 쪽으로. 열셋째 침대가 새로 놓였다. 이불이 개어져 있다. 이쪽 크기다. 끌려간다. 무릎이 침대 쇠에 걸렸다.<br><br>사감이 장부를 편다. 이름 칸이 비었다. 연필을 든다.`,
          dieText:`맞는 것은 늘 진짜가 아닌 쪽이다. 대답한 것은 진짜였다.<br><br>이 호실. 열세 명. 이상 없음.<br>다음 날 아침 점호에서도 열세 명이었다.` },
        ok:`대답하기 전에 이쪽 앞에 환영을 하나 세웠다. 이쪽 모양. 줄에 섰다. 대답은 환영이 했다.<br><br>사감이 환영 앞에서 멈췄다. 이름을 안 불렀는데 대답했네. 손이 환영 손목을 잡았다. 환영이 꺼졌다. 빈손이 됐다. 사감이 제 손을 들여다봤다.<br>그 사이 일행은 문 밖으로 빠졌다.<br><br>복도 모퉁이에서 들었다. 사감이 장부 넘기는 소리. 연필 소리. 지우개 소리. 오래.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A2', t:'교실동 — 수면 밑의 얼굴',
    x:`교실동 복도 물이 가슴까지다. 수면이 판판하다.<br><br>
    수면에 천장이 비친다. 그리고 얼굴이 비친다. 물 밑에서 올려다보는 얼굴들. 수면 바로 밑이다. 비친 게 아니다.<br>
    얼굴들이 위로 지나가는 것의 얼굴을 본다. 본 얼굴은 물 밑에도 하나 생긴다. 물 밑 얼굴이 하나 늘 때마다 위에서 누가 하나 줄었을 것이다.<br><br>
    환영술사는 수면에도 그림을 그린다. 물은 좋은 화폭이다.`,
    o:[
      { l:'① 마력으로 수면에 빈 천장만 비치게 그리며 걷는다.', k:'evade', dc:22, cost:{ mana:28 }, wake:1,
        ok:`손을 수면 위로 펴고 그렸다. 천장만. 이쪽 얼굴 자리에 천장 얼룩을 그려 넣었다. 수면이 이쪽을 안 비춘다.<br><br>밑의 얼굴들이 수면을 올려다본다. 천장만 보인다. 이쪽은 그 그림 위로 걸었다. 몸이 지나는 자리마다 그림이 따라왔다.<br>복도 끝 계단에 닿았다. 물 밖으로 올라서서 그림을 거뒀다.<br><br>그림을 들고 걸었다. 한자리에 세워 두는 그림이 아니라 몸을 따라 움직이는 그림이다. 만든 자리에 두지 않고 데리고 다녔다. 환영이 이쪽 걸음을 따라왔다.`,
        ng:`그리는데 손이 수면에 닿았다. 그림이 일렁였다.<br><br>일렁인 틈으로 이쪽 얼굴이 수면에 비쳤다. 밑의 얼굴 하나가 그 얼굴을 따라 했다. 이쪽 얼굴로 바뀌었다. 물 밑에 이쪽 얼굴이 하나 생겼다.<br>계단까지 허우적거리며 갔다. 그 뒤로 물을 볼 때마다 물 밑에서 이쪽이 이쪽을 본다. 눈 깜박이는 박자가 다르다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
      { l:'② 고개를 들고 수면을 보지 않고 지난다.', k:'steady', dc:23,
        ok:`고개를 들었다. 천장만 봤다. 수면을 안 봤다. 비친 얼굴을 안 보면 이쪽 얼굴도 안 비친다. 보는 쪽이 비친다.<br><br>천장에 금이 있다. 그 금을 따라 걸었다. 발밑에서 얼굴들이 따라온다. 발목이 차다. 물 밑 숨이 정강이에 닿는다. 고개를 안 내렸다.<br>계단에 닿았다. 물 밖에서야 고개를 내렸다.<br><br>수면에 비친 이쪽 얼굴이 고개를 든 채다. 이쪽은 내렸는데.`,
        ng:`걷다가 발에 뭔가 걸렸다. 고개가 내려갔다.<br><br>수면 바로 밑 얼굴과 눈이 마주쳤다. 웃는다. 얼굴이 수면을 뚫고 올라오려 한다. 동료가 이쪽 턱을 들어 올렸다. 위를 보라고.<br>계단까지 동료 손에 턱을 맡기고 갔다. 목이 뻣뻣하다. 눈을 감으면 그 얼굴이 웃는다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
    ] },

  { at:'A2', t:'수영장 — 결석 한 명',
    x:`수영장 출발대 옆 칠판. 수영 수업 출석. 오늘 결석 한 명. 이름 칸에 17.<br><br>
    레인 여섯 중 다섯에 물살이 오간다. 한 레인만 비었다. 결석한 자리다. 건너편 배수구 쪽으로 가려면 레인 쪽을 지나야 한다.<br>
    빈 레인에 들어가면 그 자리를 채우게 된다. 물살들이 그걸 안다.<br><br>
    환영술사는 빈자리를 채우는 일을 안다.`,
    o:[
      { l:'① 마력으로 빈 레인에 헤엄치는 아이 환영을 띄운다.', k:'evade', dc:23, cost:{ mana:30 },
        doom:{ title:'빈 레인', what:'환영과 함께 레인 물살에 끌려갑니다', dc:18, sec:45,
          text:`빈 레인에 아이 환영을 띄웠다. 헤엄치는 모양. 물살이 반겼다. 다섯 레인이 박자를 맞춘다.<br><br>환영 옆을 따라 레인을 건너려 했다. 환영을 데리고. 반쯤 왔다. 옆 레인 물살이 환영을 감았다. 같이 돌자고. 환영과 이쪽 사이 줄도 같이 감겼다.<br>몸이 물살에 끌려간다. 레인을 따라. 끝에 닿으면 돌아오고, 끝에 닿으면 돌아온다. 환영은 숨을 안 쉰다. 이쪽은 쉬어야 한다.<br><br>수업은 쉬는 시간이 없다.`,
          dieText:`빈자리를 채우는 일을 안다. 채운 자리는 다시 비지 않는다.<br><br>출석 칠판. 오늘 결석 영 명.<br>여섯 레인이 다 찼다. 하나는 아주 서툴게 헤엄친다.` },
        ok:`아이 환영을 띄우고 바로 줄을 끊었다. 환영 혼자 헤엄치게.<br><br>물살이 환영을 반겼다. 다섯 레인이 박자를 맞춘다. 여섯 레인이 다 찼다. 수업이 굴러간다. 아무도 출발대 쪽을 안 본다.<br>그 사이 출발대 뒤 타일 턱을 따라 건너편으로 갔다. 레인에는 안 들어갔다.<br><br>칠판을 봤다. 오늘 결석 영 명. 17번 칸이 지워졌다. 끊긴 환영이 그 자리에서 아주 서툴게 헤엄친다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 마력으로 출발대 그늘에 물빛을 덮고 지난다.', k:'hide', dc:22, cost:{ mana:26 },
        ok:`출발대 밑 그늘을 따라 몸을 붙였다. 이쪽 위에 물빛을 그렸다. 일렁이는 빛. 수영장 가장자리에서 늘 일렁이는 그것.<br><br>레인 물살들이 지나간다. 가장자리 일렁임은 신경 쓰지 않는다. 늘 있는 것이다.<br>건너편 배수구 쪽에 닿았다. 그림을 거뒀다.<br><br>타일 턱에 이쪽이 지나온 길로 젖은 자국이 났다. 손바닥 자국이 군데군데. 이쪽 손은 턱을 짚지 않았다.`,
        ng:`그린 물빛이 진짜 물살과 박자가 달랐다.<br><br>물살 하나가 가장자리로 왔다. 다른 박자를 찾아서. 이쪽 그림을 뚫고 지나가며 다리를 감았다. 레인 쪽으로 당긴다.<br>출발대 다리를 끌어안고 버텼다. 물살이 놓고 갔다. 다리에 물살 자국이 감겼다. 살갗이 하얗게 불었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-20 } },
      { l:'③ 물살 다섯의 박자를 본다.', k:'gaze', dc:22,
        ok:`물살 다섯을 봤다. 박자가 같다. 하나만 반 박자 늦다. 셋째 레인. 늦는 물살은 끝에 닿을 때마다 머뭇거린다. 출발대 칠판 쪽을 본다.<br><br>그 물살이 머뭇거리면 다른 물살들도 같이 머뭇거린다. 그때 가장자리를 건너면 아무도 안 돌아본다.<br>머뭇거릴 때마다 열 걸음씩. 건너편에 닿았다.<br><br>셋째 레인 물살이 이쪽으로 한 번 왔다가 돌아갔다. 칠판의 17을 보다가.`,
        ng:`박자를 보는데 물살 하나가 이쪽을 봤다. 보는 것을 본다.<br><br>그 물살이 레인을 벗어나 가장자리로 왔다. 발목에 닿았다. 차고 미끄럽다. 손 모양이다. 발목을 쥐었다 놓았다. 다음엔 안 놓겠다는 듯.<br>뒷걸음질로 물러났다. 다리가 풀려 타일에 엉덩방아를 찧었다. 꼬리뼈가 울린다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } }
    ] },

  { at:'A2', t:'강당 — 졸업 사진',
    x:`강당 벽에 졸업 사진이 줄지어 걸렸다. 해마다 한 장. 학생들이 줄을 서서 웃는다.<br><br>
    맨 끝 사진은 날짜가 없다. 사진 속 학생들이 젖어 있다. 머리카락이 이마에 붙었다. 다들 웃는다. 맨 앞줄 가운데에 빈자리가 있다. 사람 하나 서는 자리.<br>
    그 자리에 얼굴이 서서히 떠오른다. 사진 속에서. 일행 중 하나의 얼굴이다. 아직 흐리다.<br><br>
    환영술사는 남이 그린 얼굴을 알아본다. 덧칠한 데가 있다.`,
    o:[
      { l:'① 마력으로 떠오르는 얼굴 위를 사진 색으로 덧칠한다.', k:'gaze', dc:22, cost:{ mana:28 }, wake:1,
        ok:`사진 앞에 손을 댔다. 떠오르는 얼굴 위에 환영을 덧칠했다. 젖은 벽 색. 빈자리 색.<br><br>얼굴이 덧칠 밑에서 떠오르려 한다. 더 칠했다. 얼굴이 가라앉았다. 빈자리가 다시 비었다. 사진 속 학생들 웃음이 조금 굳었다.<br>동료가 숨을 몰아쉰다. 방금까지 숨이 안 쉬어졌다고 한다.<br><br>남의 그림에 이쪽 칠을 섞었다. 남의 환영을 찢지 않고 그 위에 그 색으로 칠했다. 남의 색을 빌려 쓰는 법이다. 빌린 색은 그쪽 눈에 안 띈다.`,
        ng:`덧칠하는데 사진 속 손 하나가 이쪽 칠을 밀어냈다.<br><br>맨 앞줄 학생이 손을 뻗어 빈자리 위의 칠을 닦았다. 얼굴이 더 선명해졌다. 동료 얼굴이다. 웃는다. 동료는 지금 안 웃는다.<br>사진을 벽에서 떼어 뒤집었다. 뒷면에서 젖은 손자국이 배어 나왔다. 동료가 한동안 숨이 거칠었다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } },
      { l:'② 사진을 내려 뒤집어 건다.', k:'luck', dc:23,
        ok:`사진을 벽에서 내려 뒤집어 걸었다. 뒷면에 연필로 이름들이 적혔다. 줄 선 순서대로.<br><br>맨 앞줄 가운데 이름 칸이 비었다. 그 빈칸 위에 지운 자국이 겹겹이다. 17.<br>뒤집힌 사진에서는 얼굴이 안 떠오른다. 앞을 못 보니까. 동료 숨이 돌아왔다.<br><br>사진 틀 뒤에 기름종이 꾸러미가 끼워져 있었다. 말린 고기다. 누가 졸업식 날 먹으려고 숨겨 뒀다.`,
        ng:`내리는데 틀이 무거웠다. 물이 찼다.<br><br>틀 유리 안쪽에서 물이 찰랑인다. 사진 속 학생들이 그 물에 잠겼다. 웃는다. 내리다 놓쳤다. 틀이 깨졌다. 물이 쏟아져 발을 적셨다. 차갑다. 발목을 손들이 스쳤다.<br>깨진 유리에 손바닥을 베였다. 바닥에 떨어진 사진의 빈자리가 이쪽 발을 향했다.`,
        win:{ exp:16, dream:1, item:'말린 고기' }, lose:{ hp:-26, spirit:-20 } }
    ] }
]);

// ── 척후병 (scout) · 무력 ────────────────────
kJob('scout', 'A', [
  { at:'A', t:'복도 — 열 걸음 앞의 혼자',
    x:`무리보다 열 걸음 앞이다. 늘 그렇듯.<br><br>
    멈춰 섰다. 뒤에서 발소리가 계속 온다. 멈추라고 손짓했는데. 발소리가 멈추지 않는다. 다가온다. 열 걸음, 아홉 걸음.<br>
    척후병은 무리 발소리를 안다. 몇 명인지, 누가 다리를 저는지. 이 발소리는 하나다. 무리는 하나가 아니다.<br><br>
    돌아보면 무리가 있을 것이다. 또는 없을 것이다.`,
    o:[
      { l:'① 돌아보지 않고 멈춘 채 뒤 발소리를 센다.', k:'sense', dc:22, wake:1,
        ok:`돌아보지 않고 들었다. 발소리 하나. 맨발이다. 무리는 신을 신었다. 무리 발소리는 저 멀리 열 걸음 밖에서 멈춰 있다. 이쪽 손짓대로.<br><br>그 사이에 하나가 있다. 무리와 이쪽 사이. 다섯 걸음. 넷.<br>손을 등 뒤로 돌려 무리에게 신호했다. 손가락 하나를 폈다. 하나가 사이에 있다. 무리가 벽에 붙었다. 이쪽도 옆으로 비켰다. 맨발이 이쪽이 있던 자리를 지나 앞으로 갔다. 계속 갔다.<br><br>발소리로 세는 일은 늘 앞을 위한 것이었다. 이번엔 등 뒤를 셌다. 앞을 보면서 뒤를 세는 귀가 생겼다. 열 걸음 앞에 서 있어도 무리 전부가 귀에 들어온다.`,
        ng:`세다가 숫자가 틀렸다. 맨발이 둘이었다.<br><br>하나를 비켰는데 다른 하나가 이쪽 앞에 섰다. 숨이 닿는다. 얼굴이 안 보인다. 손이 어깨를 짚었다. 무겁다. 꾹 누른다.<br>주저앉으며 빠져나왔다. 어깨가 빠질 듯하다. 무리 쪽으로 기어 돌아갔다. 무리는 맨발을 못 봤다고 한다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 신호를 보내고 무리 쪽으로 돌아간다.', k:'bond', dc:22,
        ok:`멈춤 신호를 한 번, 돌아간다는 신호를 한 번. 그리고 뒤로 걸었다. 무리 쪽으로.<br><br>발소리와 마주쳤다. 안 보인다. 무리와 이쪽 사이 어둠에 서 있다. 이쪽이 지나가자 발소리가 멈췄다. 바로 옆이다. 숨을 죽였다.<br>무리에 닿았다. 맨 뒤에 붙었다.<br><br>무리를 셌다. 맞다. 다시 앞을 보니 이쪽이 서 있던 열 걸음 앞에 누가 서 있다. 무리를 등지고. 이쪽 자리에.`,
        ng:`돌아가는데 무리가 생각보다 멀었다. 열 걸음이 스무 걸음이다.<br><br>그 사이 발소리가 이쪽을 따라 돌아섰다. 바짝 붙어 걷는다. 무리에 닿았을 때 무리가 이쪽 뒤를 보고 얼굴이 하얘졌다. 뭘 봤는지 말을 안 한다.<br>등이 계속 시리다. 무리 하나가 등을 털어 줬다. 젖은 손자국이 있었다고.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } },
      { l:'③ 무력을 실어 앞을 끝까지 달려 보고 온다.', k:'evade', dc:22, cost:{ might:28 },
        ok:`발소리를 두고 앞으로 달렸다. 무력을 다리에 다 실었다. 복도 끝까지, 모퉁이 너머까지.<br><br>모퉁이 너머에 문이 있다. 열려 있다. 나가는 길이다. 확인하고 바로 돌아섰다. 달려서 돌아왔다. 맨발 발소리가 이쪽을 못 따라잡았다. 너무 빨리 갔다 왔다.<br>무리에게 손짓했다. 모퉁이, 오른쪽, 문.<br><br>무리가 이쪽을 따라 달렸다. 등 뒤에서 맨발이 느리게 쫓아온다. 문을 닫았다. 문 밑 틈으로 맨발 발가락 다섯이 들어왔다가 물러갔다.`,
        ng:`달려갔는데 모퉁이 너머가 막혀 있었다. 막다른 벽이다.<br><br>돌아섰다. 맨발 발소리가 모퉁이 입구에 섰다. 갇혔다. 몸을 낮추고 그 옆을 뚫고 달렸다. 무릎이 벽에 갈렸다. 차가운 손가락이 귀를 스쳤다.<br>무리에 닿아 막혔다는 신호를 하는데 손이 떨렸다. 귓바퀴가 찢어져 피가 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A', t:'갈림목 — 고쳐진 표식',
    x:`지나온 갈림목에 남긴 표식을 확인하러 왔다. 숯으로 그린 화살표다.<br><br>
    화살표가 다 고쳐져 있다. 방향이 바뀌었다. 이쪽 글씨다. 이쪽 손버릇 그대로 꺾였다. 이쪽은 고친 적이 없다.<br>
    고친 화살표들은 한 방향을 가리킨다. 이쪽이 안 가 본 쪽이다.<br><br>
    척후병은 제 표식을 안다. 남이 흉내 내면 어디가 다른지도.`,
    o:[
      { l:'① 표식을 버리고 바람과 냄새로 길을 고른다.', k:'sense', dc:22,
        ok:`화살표를 안 봤다. 바람을 봤다. 손등에 침을 묻혀 들었다. 차가운 쪽이 바깥이다.<br><br>화살표가 가리키는 쪽에서는 바람이 안 온다. 따뜻한 냄새가 온다. 뭔가 먹은 다음의 냄새.<br>바람 쪽으로 무리를 이끌었다. 지나는 갈림목마다 화살표를 지우고 새로 그렸다. 이번엔 끝에 점을 하나 찍었다. 이쪽만 아는 점.<br><br>뒤를 보니 지운 자리에 화살표가 다시 떠 있다. 점은 없다.`,
        ng:`바람이 사방에서 왔다. 갈림목마다 바람이 다르다.<br><br>고른 쪽이 막혀 있었다. 되돌아왔다. 또 골랐다. 막혔다. 세 번째에 무리 하나가 말했다. 화살표 따라가자. 말리느라 목소리를 높였다. 어둠 속에서 누가 따라 웃었다.<br>결국 처음 갈림목에서 다시 시작했다. 다리가 풀렸다. 숯이 손에서 부서졌다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-20 } },
      { l:'② 고쳐진 화살표대로 가 본다.', k:'evade', dc:23,
        doom:{ title:'고쳐진 표식', what:'화살표 끝 방 안으로 끌려 들어갑니다', dc:18, sec:50,
          text:`화살표대로 갔다. 이쪽 글씨니까. 몸이 제 글씨를 믿는다.<br><br>화살표 끝에 문이 있다. 문에도 화살표가 그려졌다. 안쪽을 가리킨다. 열었다. 방 바닥에 숯 화살표가 빽빽하다. 다 방 한가운데를 가리킨다. 한가운데에 누가 쪼그려 앉아 화살표를 그리고 있다.<br>고개를 든다. 이쪽 얼굴이다. 손에 숯을 쥐었다. 그 손이 이쪽 발목을 잡았다. 방 한가운데로 끌어당긴다.<br><br>무리가 문 밖에서 부른다. 문이 닫히려 한다.`,
          dieText:`척후병의 표식은 뒤에 오는 이들이 따라온다.<br><br>갈림목마다 숯 화살표가 그려져 있다. 이쪽 글씨다.<br>점은 없다.` },
        ok:`화살표대로 가되 열 걸음마다 멈춰 숯 냄새를 맡았다. 이쪽 숯은 그을린 나무 냄새다. 고쳐진 화살표는 젖은 재 냄새다.<br><br>화살표 끝 문 앞에서 멈췄다. 문틈에서 숯 긁는 소리가 난다. 누가 안에서 화살표를 그린다.<br>열지 않았다. 문에 가위표를 크게 그었다. 무리를 돌려 반대로 갔다.<br><br>등 뒤에서 숯 긁는 소리가 멈췄다. 이쪽이 그은 가위표 위로 화살표가 덧그려지는 소리가 났다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A', t:'복도 — 먼저 와 있는 발자국',
    x:`복도 먼지 위에 발자국이 있다. 이쪽 신발 밑창 무늬다. 크기도 같다.<br><br>
    이쪽이 오기 전에 찍혔다. 먼지가 아직 덜 가라앉았다. 방금이다. 발자국은 복도 끝 문 앞까지 가서 멈췄다. 돌아온 발자국은 없다.<br>
    척후병은 남보다 먼저 간다. 오늘은 누가 이쪽보다 먼저 갔다.<br><br>
    문이 아주 조금 열려 있다.`,
    o:[
      { l:'① 발자국 옆을 따라 문 앞까지 간다.', k:'evade', dc:22,
        ok:`발자국 옆으로 걸었다. 밟지 않고. 이쪽 걸음이 발자국과 나란하다. 보폭이 같다. 왼발이 조금 바깥으로 도는 것까지.<br><br>문 앞에서 발자국이 끝난다. 문틈으로 안을 봤다. 아무도 없다. 방 한가운데 바닥에 발자국이 하나 더 찍혀 있다. 거기서 끝났다. 위로 간 것처럼.<br>천장을 봤다. 천장에 발자국이 이어진다. 거꾸로.<br><br>문을 닫고 무리를 다른 길로 돌렸다. 문 너머 천장에서 걷는 소리가 났다. 이쪽 걸음 박자로.`,
        ng:`옆으로 걷다가 발이 발자국 하나에 겹쳤다. 딱 맞았다.<br><br>그 발자국에서 발이 안 떨어졌다. 밑창이 먼지에 붙었다. 다리가 저절로 다음 발자국으로 간다. 문 쪽으로. 무리가 허리를 잡아당겼다.<br>신발을 벗고 빠져나왔다. 신발은 혼자 문 앞까지 걸어가 멈췄다. 남은 길을 맨발로 갔다. 발바닥이 다 까졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-24 } },
      { l:'② 발자국도 문도 비켜 아무도 안 간 길을 연다.', k:'evade', dc:23, wake:1,
        ok:`발자국과 문을 둘 다 비켰다. 옆방 창으로 나가 벽 바깥 턱을 타고 돌았다. 무리에게는 기다리라 했다.<br><br>돌면서 이 층이 어떻게 생겼는지 머리에 그렸다. 문 안 방은 막혀 있다. 창이 없다. 들어가면 나올 데가 없는 방이다. 그 옆으로 복도가 하나 더 있다. 먼지에 발자국이 없다.<br>돌아와 무리를 그 복도로 이끌었다.<br><br>먼저 간 발자국을 안 따라갔다. 아무도 안 간 데로 갔다. 먼저 간다는 건 처음 가는 길로 간다는 뜻이었다. 남이 낸 길은 이미 앞이 아니다. 그걸 알고 나니 발이 빈 먼지를 먼저 찾는다.`,
        ng:`옆방 창 밖 턱이 부서져 있었다.<br><br>매달렸다. 손끝이 미끄러진다. 밑은 깜깜하다. 끌어올리는데 창 안에서 누가 손목을 잡아 올려 줬다. 고맙다고 하려는데 손목 잡은 손이 이쪽 손이다. 소매도 같다.<br>창 안으로 굴러 들어왔다. 아무도 없다. 손목에 이쪽 손 모양 자국이 있다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } }
    ] },

  { at:'A', t:'계단 — 밑에서 올라오는 등불',
    x:`계단 밑에서 불빛이 올라온다. 흔들린다. 등불이다. 무리 하나가 든 등불과 같은 모양이다.<br><br>
    무리는 이쪽 뒤에 있다. 등불도 뒤에 있다. 그런데 밑에서 같은 등불이 올라온다.<br>
    척후병은 신호로 묻는다. 불빛으로 두 번, 쉬고 한 번. 무리만 아는 신호다.<br><br>
    밑에서 불빛이 한 칸 올라왔다.`,
    o:[
      { l:'① 등불로 묻는 신호를 보내 대답을 본다.', k:'bond', dc:22,
        ok:`등불을 손으로 가렸다 뗐다. 두 번, 쉬고 한 번.<br><br>밑에서 대답이 왔다. 두 번, 쉬고 한 번. 같은 신호다. 따라 했다. 대답은 한 번, 쉬고 두 번이어야 한다. 무리끼리 정한 대답이다.<br>틀렸다. 밑의 것은 묻는 신호만 봤다. 대답은 모른다.<br><br>무리를 위로 돌렸다. 밑에서 불빛이 계속 신호한다. 두 번, 쉬고 한 번. 점점 빠르게.`,
        ng:`신호를 보냈더니 밑에서 맞는 대답이 바로 왔다. 한 번, 쉬고 두 번.<br><br>무리인 줄 알았다. 한 칸 내려갔다. 불빛 뒤에 아무도 없다. 등불만 떠 있다. 등불 손잡이에 손가락 마디 넷이 감겨 있다. 손가락만.<br>뒷걸음질로 올라오다 계단에 정강이를 찧었다. 대답을 어떻게 알았는지 무리 누구도 모른다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 불을 끄고 계단참 구석에 붙어 지켜본다.', k:'hide', dc:22,
        ok:`이쪽 등불을 껐다. 무리 등불도 끄게 했다. 계단참 구석에 붙었다.<br><br>밑의 불빛이 올라온다. 계단참에 닿았다. 등불이 혼자 떠 있다. 아무도 안 들었다. 불빛이 계단참을 비춘다. 구석은 안 비춘다. 구석을 안 보는 불빛이다.<br>불빛이 위로 올라갔다. 이쪽이 온 쪽으로.<br><br>그 뒤에 내려갔다. 밑에서 그을음 냄새가 짙다. 계단마다 등불을 내려놓았던 동그란 자국이 있다.`,
        ng:`숨었는데 무리 하나가 숨을 크게 쉬었다.<br><br>불빛이 구석을 향했다. 눈부시다. 불빛 뒤에서 뭔가 손을 뻗었다. 무리 하나의 머리채를 잡았다. 이쪽이 그 손을 쳤다. 손이 놓았다. 손등이 차다. 쇠처럼.<br>다들 밑으로 뛰었다. 이쪽 손등이 퍼렇게 부어오른다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
    ] },

  { at:'A', t:'쉬는 자리 — 하나 많은 무리',
    x:`척후병은 쉴 때마다 무리를 센다. 버릇이다.<br><br>
    하나가 많다. 몇 번을 세도 많다. 얼굴을 보면 다 아는 얼굴이다. 누가 더해졌는지 모른다.<br>
    더해진 하나는 무리 맨 뒤에 있을 것이다. 늘 그렇다고 들었다. 맨 뒤는 아무도 안 본다.<br><br>
    맨 뒤에 누가 서 있는지 지금은 안 보인다. 어둡다.`,
    o:[
      { l:'① 무리를 한 줄로 세워 앞에서부터 이름을 부른다.', k:'fix', dc:22,
        ok:`한 줄로 세웠다. 맨 앞부터 이름을 불렀다. 대답하면 한 걸음 앞으로 나오게.<br><br>하나씩 나왔다. 마지막 이름을 불렀다. 대답이 둘이다. 하나는 무리 속에서, 하나는 맨 뒤 어둠에서. 무리 속 대답이 진짜다. 이름 주인이 제 얼굴을 가리키며 나왔다.<br>맨 뒤 어둠에 아무도 안 남은 줄 알았다. 남았다. 이름이 없는 것은 안 나온다.<br><br>무리를 앞으로 이끌었다. 이름 없는 것은 따라오지 않았다. 부를 이름이 없어 못 따라온다.`,
        ng:`이름을 부르는데 대답이 하나씩 늦었다. 다 늦었다.<br><br>누가 진짜인지 모르게 됐다. 다들 서로를 본다. 무리 하나가 울었다. 우는 소리가 둘이다. 하나는 흉내다.<br>그대로 출발했다. 오래 걸은 뒤 다시 셌다. 맞다. 언제 빠졌는지 모른다. 다들 말이 없다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-22 } },
      { l:'② 맨 뒤로 돌아가 직접 본다.', k:'evade', dc:23,
        doom:{ title:'맨 뒤', what:'맨 뒤의 것에게 어둠 속으로 끌려갑니다', dc:18, sec:50,
          text:`무리 옆을 지나 맨 뒤로 갔다. 어둠이다. 손을 뻗었다. 누가 있다. 어깨다. 차다.<br><br>그것이 이쪽 손을 잡았다. 그리고 뒤로 걸었다. 이쪽을 끌고. 무리에게서 멀어진다. 열 걸음. 열 걸음 앞이 아니라 열 걸음 뒤다.<br>무리가 이쪽 이름을 부른다. 대답하려는데 그것이 대신 대답했다. 응. 이쪽 목소리로. 무리가 안심한다.<br><br>스무 걸음. 손이 안 빠진다. 무리 불빛이 작아진다.`,
          dieText:`척후병은 남보다 먼저 가서 남보다 먼저 돌아온다.<br><br>무리를 세 보니 수가 맞았다. 다들 안심했다.<br>맨 앞에서 누가 걸었다. 척후병 걸음으로.` },
        ok:`맨 뒤로 가되 무리 맨 끝 사람 어깨를 잡고 갔다. 손을 놓지 않았다.<br><br>어둠 속에 손을 뻗었다. 어깨가 닿았다. 차다. 그것이 이쪽 손을 잡으려는 순간 무리 끝 사람을 당겨 앞으로 돌아왔다. 그것의 손이 소매 끝을 스쳤다.<br>무리를 다 앞으로 몰았다. 맨 뒤에 이쪽이 섰다. 등불을 뒤로 들고.<br><br>등불 빛 끝에 그것이 서 있다. 빛이 닿는 데까지만. 무리를 셌다. 맞다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 들어오기 전에 정한 손짓으로 진짜를 가린다.', k:'gaze', dc:22, wake:1,
        ok:`손짓을 하나 했다. 들어오기 전에 무리끼리 정한 것이다. 손가락 접는 순서. 다들 따라 했다.<br><br>하나가 늦다. 한 박자 늦게, 남을 보고 접는다. 그 손가락이 하나 모자란다. 넷이다.<br>그쪽을 등불로 비췄다. 아무도 없다. 무리 수가 맞았다.<br><br>이쪽이 만든 신호가 이쪽 무리를 지켰다. 신호는 알리려고 만든다고만 알았다. 가려내려고도 만든다. 신호를 아는 것과 모르는 것 사이에 금이 그어진다. 그 금을 이제 일부러 긋는다.`,
        ng:`손짓을 했는데 다들 똑같이 따라 했다. 늦는 손이 없다.<br><br>그것은 신호를 안다. 언제 배웠는지 모른다. 들어오기 전 문 앞에서 정할 때 이미 거기 있었다.<br>더 묻지 못하고 출발했다. 맨 뒤에서 이쪽 신호를 따라 하는 손이 계속 있다. 등이 한참 서늘했다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } }
    ] },

  { at:'A', t:'통로 — 위부터 본다',
    x:`척후병은 앞을 본다. 그리고 위를 본다. 그다음에 발밑을. 그 순서가 몸에 붙었다.<br><br>
    통로 천장이 높다. 어둡다. 천장에서 물방울이 떨어진다. 물방울이 아니다. 떨어진 데마다 바닥이 조금씩 패었다. 침이다.<br>
    위에 뭔가 매달렸다. 무리가 지나갈 통로 한가운데 위다.<br><br>
    바닥만 보고 걸으면 침 자국을 피해 걷게 된다. 피하다 보면 한가운데로 몰린다.`,
    o:[
      { l:'① 침 자국을 읽어 위의 것들이 보는 쪽을 잡는다.', k:'evade', dc:22, wake:1,
        ok:`침 자국을 봤다. 동그랗다. 퍼진 쪽이 있다. 위의 것이 고개를 돌리는 쪽으로 퍼진다.<br><br>퍼진 방향을 이어 보니 위의 것이 셋이다. 셋이 서로 다른 쪽을 본다. 셋 다 안 보는 길이 하나 있다. 왼쪽 벽 반 뼘.<br>무리를 그 길로 한 줄로 세웠다. 벽에 어깨를 붙이고. 다 지났다. 침 한 방울 안 맞았다.<br><br>바닥을 보고 위를 읽었다. 발밑 얼룩으로 천장 셋을 그렸다. 안 보이는 것도 남긴 자국으로 세는 법을 알았다. 자국은 늘 주인보다 정직하다.`,
        ng:`읽는데 위에서 침이 떨어졌다. 정수리에.<br><br>뜨겁다. 머리카락 녹는 냄새가 났다. 위에서 셋이 동시에 고개를 내렸다. 이쪽 정수리를 향해. 무리를 밀쳐 앞으로 뛰게 했다.<br>통로 끝에서 머리를 물에 씻었다. 정수리에 동전만 한 데가 벗겨졌다. 화끈거린다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-18 } },
      { l:'② 무력을 실어 무리를 몸으로 덮고 단숨에 지난다.', k:'bond', dc:22, cost:{ might:28 },
        ok:`무리를 벽 쪽으로 몰았다. 팔을 펴서 몸으로 덮었다. 무력을 다 실어 한 덩이로 밀며 달렸다.<br><br>위에서 침이 떨어진다. 이쪽 등에, 팔에. 무리 위에는 안 떨어졌다. 이쪽이 덮었다.<br>통로 끝에서 무리를 놓았다. 다들 멀쩡하다.<br><br>이쪽 등에서 연기가 난다. 옷이 군데군데 녹았다. 살은 덜 녹았다. 무력이 살갗까지 단단하게 해 줬다.`,
        ng:`밀다가 하나가 넘어졌다. 다들 엉켰다.<br><br>통로 한가운데에서. 위에서 셋이 내려왔다. 긴 목이다. 무리 하나를 물려고 했다. 이쪽이 팔로 막았다. 팔에 이빨이 스쳤다.<br>다 같이 기어서 빠져나왔다. 팔에 이빨 자국이 줄줄이다. 침 묻은 데가 탄다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'A', t:'통로 — 바뀐 돌아갈 길',
    x:`척후병은 지나온 길을 머리에 담아 둔다. 돌아갈 때 쓰려고.<br><br>
    돌아갈 길이 바뀌었다. 지나온 갈림목이 없다. 벽이다. 벽에 이쪽이 남긴 숯 표식 반쪽이 걸려 있다. 나머지 반은 벽 속이다.<br>
    벽이 새것이다. 회칠이 아직 젖었다.<br><br>
    무리가 이쪽을 본다. 돌아갈 길을 아는 사람은 이쪽뿐이다.`,
    o:[
      { l:'① 머릿속 길을 믿고 다른 쪽으로 이어 돈다.', k:'sense', dc:23, wake:1,
        ok:`눈을 감고 지나온 길을 다시 걸었다. 머릿속에서. 갈림목, 계단, 왼쪽, 문.<br><br>막힌 벽 뒤가 어디인지 알았다. 그 뒤 갈림목은 다른 쪽으로도 이어져 있었다. 처음 지날 때 곁눈으로 본 문 하나. 거기로 돌아가면 된다. 멀다. 길은 있다.<br>무리를 이끌고 돌았다. 곁눈으로 본 문이 거기 있었다.<br><br>돌면서 알았다. 머릿속 길은 지나온 한 줄이 아니라 그물이다. 곁눈으로 본 것까지 다 담겨 있다. 벽 하나로는 그물이 안 끊어진다.`,
        ng:`머릿속 길을 따라갔는데 두 번째 갈림목도 벽이 됐다.<br><br>회칠이 젖었다. 방금 생겼다. 이쪽이 생각하는 길을 저쪽이 먼저 막는다. 머릿속을 읽는 것 같다. 세 번째 갈림목 앞에서 생각을 멈췄다. 생각하면 막힌다.<br>생각 없이 아무 데로 걸었다. 겨우 빠져나왔다. 머리가 깨질 듯 아프다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-22 } },
      { l:'② 젖은 벽을 더듬어 표식 나머지 반쪽을 쫓는다.', k:'evade', dc:22,
        ok:`젖은 벽을 손으로 더듬었다. 표식 반쪽이 벽 속으로 들어간 자리부터 회칠 결을 봤다.<br><br>덜 마른 결을 따라가니 벽 아래쪽에 틈이 있다. 기어서 들어갈 너비다. 그 너머로 원래 갈림목이 보인다.<br>틈으로 무리를 하나씩 들여보냈다. 맨 마지막에 이쪽이 들어갔다.<br><br>들어가 보니 틈 안쪽 회칠에 손톱 자국이 있다. 안에서 긁어 판 틈이다. 누가 갇혔다가 나갔다.`,
        ng:`더듬는데 젖은 회칠에 손이 빠졌다. 팔꿈치까지.<br><br>벽 속에서 뭔가 손목을 쥐었다. 손가락이 회반죽투성이다. 굳은 손이다. 당겼다. 이쪽도 당겼다. 회칠이 터지며 손이 빠졌다.<br>팔이 하얗게 굳어 있다. 떼어 내는 데 살갗이 같이 벗겨졌다. 길은 결국 무리 하나가 찾았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-20 } }
    ] },

  { at:'A', t:'방 — 끌린 자국',
    x:`방 바닥에 끌린 자국이 있다. 두 줄. 사람 발뒤꿈치 너비다. 문에서 방 안쪽 벽까지 이어진다.<br><br>
    자국 양옆에 손톱 자국이 있다. 바닥을 긁은 손톱. 끌려가며 붙잡으려던 손이다.<br>
    안쪽 벽 밑에 개구멍만 한 구멍이 있다. 자국이 거기로 들어갔다.<br><br>
    척후병은 끝을 봐야 무리에게 알린다. 끝을 보는 사람은 늘 혼자다.`,
    o:[
      { l:'① 자국을 따라가 구멍 안을 본다.', k:'sense', dc:23,
        doom:{ title:'끌린 자국', what:'구멍 안으로 끌려 들어갑니다', dc:18, sec:50,
          text:`자국을 따라 기어 구멍 앞까지 갔다. 등불을 구멍에 비췄다. 안이 길다. 끝이 안 보인다.<br><br>안쪽에서 숨소리가 났다. 가깝다. 등불 빛 끝에 손이 하나 놓여 있다. 손바닥이 위로. 기다린다.<br>그 손이 등불 쥔 손목을 잡았다. 당긴다. 어깨가 구멍에 걸렸다. 구멍이 넓어진다. 바닥에 새 자국이 두 줄 생긴다. 이쪽 발뒤꿈치다.<br><br>손톱으로 바닥을 긁었다. 앞서 간 손톱 자국 옆에.`,
          dieText:`끝을 보는 사람은 늘 혼자다. 알리는 사람도 혼자다.<br><br>방 바닥에 끌린 자국이 네 줄이다.<br>무리는 다음 방에서 척후병을 기다렸다. 오래.` },
        ok:`자국을 따라가되 구멍 두 걸음 앞에서 멈췄다. 손이 닿을 거리 밖에서.<br><br>등불을 바닥에 밀어 굴려 넣었다. 등불이 구멍 안을 비추며 굴러간다. 안에 손이 줄지어 놓였다. 손바닥이 위로. 다 기다린다. 등불이 지나가자 손들이 하나씩 등불을 쥐었다. 등불이 끌려 들어갔다.<br>그걸 보고 물러났다. 무리에게 알렸다. 이 방은 끝이다.<br><br>무리를 다른 문으로 돌렸다. 등 뒤에서 이쪽 등불이 구멍 안 아주 깊은 데서 꺼졌다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 자국을 피해 벽을 따라 다른 문으로 길을 잡는다.', k:'evade', dc:22,
        ok:`자국을 안 밟았다. 벽에 붙어 방을 돌았다. 자국은 방 한가운데를 가른다. 그 양옆으로만 갔다.<br><br>반대편에 문이 있다. 자국은 그 문을 지나지 않았다. 끌려간 이는 이 문을 못 봤다. 끌려가느라.<br>문을 열고 무리를 들였다. 마지막에 이쪽이 들어가며 돌아봤다.<br><br>자국 끝 구멍에서 손 하나가 나와 바닥을 더듬는다. 자국을 거꾸로 따라. 문 쪽으로.`,
        ng:`벽을 따라 도는데 벽 밑에도 구멍이 있었다. 하나가 아니었다.<br><br>발목이 잡혔다. 넘어졌다. 바닥에 이쪽 자국이 생긴다. 무리가 팔을 잡아당겼다. 구멍 안 손과 줄다리기를 했다. 무리가 이겼다.<br>발목에 손자국이 시퍼렇다. 바닥에 이쪽 손톱 자국이 다섯 줄 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-20 } },
      { l:'③ 무력을 실어 탁자를 끌어다 구멍을 막는다.', k:'steady', dc:22, cost:{ might:30 },
        ok:`방구석 무거운 탁자를 무력으로 끌었다. 구멍 앞에 엎어 막았다.<br><br>탁자 너머에서 손이 두드린다. 똑똑. 그다음엔 민다. 탁자가 반 뼘 밀린다. 등으로 받쳤다. 무리가 방을 지나갔다.<br>마지막 사람이 나간 다음 탁자에서 등을 뗐다. 뛰었다.<br><br>문을 닫기 전에 봤다. 탁자가 천천히 넘어간다. 구멍에서 손이 줄지어 나와 탁자를 쓰다듬는다. 다음엔 이 탁자다.`,
        ng:`끄는데 탁자 다리가 바닥 틈에 걸렸다.<br><br>힘을 더 줬다. 탁자 다리가 부러지며 이쪽이 넘어졌다. 구멍 앞이다. 손이 머리카락을 잡았다. 부러진 탁자 다리로 손을 쳤다. 놓았다.<br>무리가 탁자를 대신 끌어 막았다. 두피가 쓰라리다. 머리카락 한 줌이 구멍 안으로 끌려갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } }
    ] },

  { at:'A', t:'계단참 — 앞에서 부르는 무리',
    x:`열 걸음 앞에 섰다. 뒤에 무리가 있다. 숨소리로 안다.<br><br>
    그런데 앞에서 무리 목소리가 부른다. 여기야. 이쪽으로 와. 길 찾았어. 무리 중 하나의 목소리다. 그 사람은 지금 이쪽 뒤에서 숨을 쉬고 있다.<br>
    척후병보다 앞에 있는 무리는 없다.<br><br>
    앞 목소리가 이쪽 이름을 부른다. 반가운 목소리로.`,
    o:[
      { l:'① 뒤를 확인하고 앞 목소리를 무시한다.', k:'evade', dc:22,
        ok:`뒤로 손짓했다. 목소리 주인에게 손을 들게 했다. 손이 들렸다. 뒤에 있다. 앞의 것은 아니다.<br><br>앞을 무시하고 옆 갈래로 무리를 돌렸다. 앞 목소리가 따라 움직인다. 여기야, 여기. 이쪽이 안 오자 짜증을 낸다. 그 사람은 짜증을 안 내는 사람이다.<br>옆 갈래 끝까지 갔다.<br><br>앞 목소리가 그 끝에 다시 섰다. 이번엔 이쪽 목소리로 무리를 부른다.`,
        ng:`뒤로 손짓했는데 손이 두 개 들렸다. 같은 사람 둘.<br><br>어느 쪽이 진짜인지 볼 새가 없었다. 앞 목소리가 갑자기 귀에서 났다. 왜 안 와. 차가운 손이 손목을 잡았다. 앞에서. 뿌리쳤다.<br>무리를 옆 갈래로 몰았다. 들린 손 하나는 계단참 어둠에 남았다. 손목에 손가락 자국이 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 앞 목소리 쪽으로 열 걸음 더 가 본다.', k:'sense', dc:23,
        doom:{ title:'앞의 무리', what:'앞에서 부른 것에게 어둠 속으로 끌려갑니다', dc:18, sec:45,
          text:`열 걸음 더 갔다. 척후병의 일이다. 앞에 뭐가 있는지 보는 것.<br><br>목소리가 바로 앞에서 났다. 등불을 들었다. 무리 하나가 서 있다. 그 사람 얼굴이다. 웃는다. 이 사람은 이렇게 안 웃는다. 입이 귀까지다.<br>그것이 이쪽 손을 잡았다. 반갑게. 끌고 간다. 길 찾았어. 이쪽이야. 발이 끌린다. 어둠 쪽으로.<br><br>뒤에서 진짜 무리가 이쪽 이름을 부른다. 앞의 것도 같이 부른다. 같은 목소리로.`,
          dieText:`척후병보다 앞에 있는 무리는 없다. 있으면 그건 무리가 아니다.<br><br>무리는 한참 기다리다 다른 길로 갔다.<br>그 뒤로 가끔 앞에서 척후병 목소리가 부른다. 길 찾았어.` },
        ok:`열 걸음을 가되 허리에 줄을 묶어 무리에게 끝을 쥐여 주고 갔다.<br><br>목소리 앞에 섰다. 등불을 들었다. 무리 하나 얼굴이다. 입이 귀까지 웃는다. 손을 내민다. 줄을 두 번 당겼다. 무리가 이쪽을 끌어당겼다.<br>그것의 손이 빈 데를 쥐었다. 이쪽은 줄에 끌려 열 걸음 뒤로 갔다.<br><br>무리에 닿아 알렸다. 앞은 안 된다. 앞의 것은 그 자리에서 손을 내민 채 서 있다. 웃는 입을 다물지 않는다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A', t:'문 앞 — 맨 마지막',
    x:`문을 지나는 순서는 척후병이 정한다. 먼저 가고, 맨 마지막에 닫는다.<br><br>
    무리가 다 문을 지났다. 이쪽만 남았다. 뒤 복도 어둠에서 뭔가 다가온다. 발소리가 없다. 바람이 먼저 온다. 차다.<br>
    문을 닫으려면 뒤를 등져야 한다. 등지는 순간이 제일 길다.<br><br>
    척후병은 마지막에 나오는 법도 안다. 처음 나가는 법만큼.`,
    o:[
      { l:'① 어둠을 마주 본 채 뒷걸음으로 문을 넘는다.', k:'evade', dc:22, wake:1,
        ok:`어둠을 마주 보고 섰다. 뒷걸음으로 문턱을 넘었다. 발뒤꿈치가 문턱을 찾았다. 눈은 앞에 둔 채.<br><br>어둠이 다가온다. 바람이 얼굴을 친다. 그 안에서 뭔가 손을 뻗는다. 이쪽이 보고 있으니 다가오는 게 느리다. 문턱을 넘었다. 손으로 문을 끌어 닫았다. 마지막까지 어둠을 봤다.<br>쾅. 문이 닫혔다. 문 너머에서 바람이 문을 민다.<br><br>먼저 가는 일만 앞인 줄 알았다. 마지막에 나오는 일도 앞이다. 등 뒤를 앞으로 바꾸는 법을 알았다. 무리의 맨 끝이 이쪽의 맨 앞이 된다.`,
        ng:`뒷걸음질하다 문턱에 걸려 넘어졌다.<br><br>엉덩방아를 찧었다. 문이 열린 채다. 어둠이 문턱까지 왔다. 차가운 손가락이 발목을 쥐었다. 무리가 겨드랑이를 잡아 끌어냈다. 발목에서 손이 미끄러졌다.<br>무리가 문을 닫았다. 발목이 얼었다. 한참 감각이 없다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-22 } },
      { l:'② 무력을 실어 문을 닫고 등으로 버틴다.', k:'steady', dc:22, cost:{ might:30 },
        ok:`몸을 돌려 문을 닫았다. 등을 붙였다. 무력을 다리에 박았다. 문짝이 등에 붙었다.<br><br>쿵. 저쪽에서 민다. 한 번, 두 번. 버텼다. 무리가 빗장을 찾았다. 녹슨 쇠막대. 문고리에 질렀다.<br>등을 뗐다. 문이 버틴다. 빗장이 운다.<br><br>문 너머에서 미는 소리가 멈췄다. 대신 문 밑 틈으로 바람이 새어 든다. 이쪽 발목만 감고 돌아갔다.`,
        ng:`버티는데 문짝이 얇았다. 등 뒤에서 판자가 휘었다.<br><br>판자 틈으로 손가락이 들어와 등을 긁었다. 옷이 찢어졌다. 등이 찢어졌다. 이를 악물고 버텼다. 무리가 빗장을 질렀다.<br>등을 뗐다. 등에 손톱 자국이 다섯 줄. 판자 틈에 이쪽 옷 조각이 끼어 있다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'A1', t:'접수처 — 방청객 명단',
    x:`로비 접수처 책상에 방청객 명단이 펼쳐졌다. 오늘 날짜. 오후 다섯 시 녹화.<br><br>
    이름이 줄줄이 적혔다. 맨 아래에 이쪽 일행 이름이 있다. 이쪽 글씨가 아니다. 둥글둥글한 아이 글씨다.<br>
    이름 옆에 입장 확인 칸이 있다. 비었다. 그 위 이름들에는 다 동그라미가 쳐졌다.<br><br>
    척후병은 명단도 지도처럼 읽는다. 누가 어디로 갔는지.`,
    o:[
      { l:'① 명단 옆 작은 글씨로 앞서 간 이들의 길을 읽는다.', k:'gaze', dc:22,
        ok:`명단을 봤다. 동그라미 옆에 작은 글씨가 있다. 층과 자리. 4층 방청석 3열. 6층 공 바다. 7층 무대. 위층으로 갈수록 동그라미가 진하다.<br><br>안 끝난 이름도 있다. 2층 의상실에서 끝난 이름. 동그라미가 없다. 그 사람은 의상실에서 무대로 안 갔다. 다른 데로 갔다.<br>그 이름 옆에 연필로 화살표가 그려졌다. 세탁실. 세탁실 뒤에 직원 계단이 있다는 뜻이다.<br><br>그 길을 머리에 넣고 명단을 덮었다. 덮는 순간 명단 안에서 연필 소리가 났다. 이쪽 이름 옆에서.`,
        ng:`넘기는데 종이가 손에 붙었다. 끈적하다. 꿀처럼.<br><br>떼려는데 이쪽 이름 옆 입장 칸에 동그라미가 그려지기 시작했다. 저절로. 반쯤 그려졌다. 명단을 찢었다. 손바닥에 붙은 종이가 같이 찢겼다.<br>손바닥이 쓰라리다. 동그라미 반쪽이 손바닥에 찍혀 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-26 } },
      { l:'② 무력을 실어 명단을 뜯어 들고 앞서 달린다.', k:'evade', dc:22, cost:{ might:28 },
        ok:`명단을 뜯어 품에 넣었다. 무력을 다리에 실어 로비를 가로질렀다. 비상구 초록 불을 찾아.<br><br>로비 텔레비전 속 노란 얼굴이 이쪽을 따라 고개를 돌린다. 친구야, 접수는 하고 가야지. 비상구 문에 닿았다. 잠겼다. 매점 뒤로 돌았다. 다른 문이 있다. 직원용이다.<br>무리를 불렀다. 직원용 문으로 들어갔다.<br><br>품 안 명단을 꺼내 보니 이쪽 일행 이름이 지워져 있다. 아니다. 옮겨졌다. 직원 명단 칸으로.`,
        ng:`명단을 뜯는 순간 로비 불이 꺼졌다. 텔레비전만 켜졌다.<br><br>노란 얼굴이 화면 가득 다가왔다. 접수 안 한 친구! 비상구 쪽으로 달리는데 줄 선 의자가 발에 걸렸다. 넘어졌다. 의자 다리가 정강이를 찍었다.<br>일어나 보니 명단이 손에 없다. 접수처 책상 위에 다시 펼쳐져 있다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A1', t:'세트 뒤 — 무대 감독의 카드',
    x:`세트 뒤 어둠에 무대 감독이 서 있다. 헤드셋을 꼈다. 얼굴이 없다. 손에 커다란 카드 묶음.<br><br>
    카드를 한 장씩 넘긴다. 박수. 조용히. 웃음. 앞으로. 카드가 넘어갈 때마다 세트 위 장갑들이 그대로 한다. 앞으로 카드에 다들 무대 쪽으로 한 걸음.<br>
    무리는 세트 뒤를 가로질러야 한다. 카드가 보이는 데에 있으면 카드대로 해야 한다.<br><br>
    척후병은 다음에 올 것을 먼저 본다. 카드도 마찬가지다.`,
    o:[
      { l:'① 다음 카드를 먼저 읽어 무리에게 반 박자 앞서 신호한다.', k:'sense', dc:22, wake:1,
        ok:`무대 감독 손을 봤다. 카드 묶음 옆면으로 다음 카드 글씨가 비친다. 앞으로 다음은 조용히, 조용히 다음은 박수.<br><br>무리에게 손짓했다. 박수 카드가 올라가기 직전에 박수를 쳤다. 앞으로 카드가 올라가기 직전에 한 걸음 물러서 있었다. 카드보다 반 박자 먼저 하면 카드 차례가 아니다.<br>감독이 카드를 넘기다 멈췄다. 이쪽이 먼저 한다. 카드가 늦었다. 그 틈에 세트 뒤를 다 지났다.<br><br>앞서 가는 일이 걸음만이 아니다. 저쪽이 하려는 걸 먼저 읽고 한 박자 앞에 서면 저쪽 차례가 사라진다. 시간에도 열 걸음 앞이 있다.`,
        ng:`읽은 카드가 묶음 맨 뒤 카드였다. 순서가 아니다.<br><br>무리에게 박수 신호를 보냈다. 올라간 카드는 조용히. 박수 소리가 세트 뒤를 울렸다. 얼굴 없는 머리가 이쪽을 향했다. 카드가 넘어갔다. 앞으로.<br>무리가 한 걸음 무대 쪽으로 끌려갔다. 팔을 벌려 막았다. 장갑들이 무리 소매를 잡았다. 뿌리치고 빠져나왔다. 팔에 장갑 손가락 자국이 남았다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 카드가 안 보이는 감독 등 뒤로 돌아 지난다.', k:'evade', dc:23,
        ok:`카드는 앞에만 보인다. 감독 등 뒤에서는 안 보인다. 안 보이는 카드는 안 따라 해도 된다.<br><br>무리를 감독 등 뒤로 돌렸다. 헤드셋 줄이 바닥에 길게 깔렸다. 밟지 않게 넘었다.<br>감독 바로 뒤를 지날 때 헤드셋에서 목소리가 샜다. 노래 언니다. 뒤에 몇 명? 감독이 카드를 넘겼다. 조용히.<br><br>조용히 지났다. 카드가 이쪽을 안 봐도 이쪽은 카드를 따랐다.`,
        ng:`등 뒤로 도는데 헤드셋 줄이 발에 걸렸다.<br><br>감독 머리가 확 당겨졌다. 돌아섰다. 카드가 얼굴 앞에 있다. 앞으로. 발이 저절로 한 걸음 나갔다. 두 걸음. 무리가 허리를 잡았다.<br>버티는 사이 카드가 넘어갔다. 박수. 다들 박수를 쳤다. 그 틈에 빠져나왔다. 무릎이 세트 각목에 찍혔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-18 } },
      { l:'③ 무력을 실어 감독 손의 카드 묶음을 빼앗는다.', k:'break', dc:23, cost:{ might:30 },
        doom:{ title:'무대 감독', what:'무대 감독에게 무대로 끌려 나갑니다', dc:18, sec:50,
          text:`무력을 실어 달려들어 카드 묶음을 잡았다. 감독 손이 놓지 않는다. 차고 질기다.<br><br>당겼다. 카드가 반으로 찢어졌다. 찢긴 반쪽 맨 앞 카드가 이쪽 손에 남았다. 앞으로.<br>감독이 이쪽 손목을 잡았다. 헤드셋에서 언니 목소리가 난다. 친구가 카드를 들었네. 오늘 진행은 친구가 해요. 감독이 이쪽을 끌고 세트 틈으로 걷는다. 노란 빛 쪽으로. 무대로 끌려 나간다.<br><br>손에 든 카드가 얼굴 앞에서 펄럭인다. 앞으로.`,
          dieText:`다음 카드를 먼저 보면 앞서갈 수 있다. 카드를 쥐면 다음 사람이 된다.<br><br>그날 방송에는 진행자가 하나 더 나왔다. 카드를 들고.<br>카드를 넘길 때마다 손이 조금 떨렸다.` },
        ok:`달려들어 묶음 맨 아래 한 장만 뽑았다. 무력을 손끝에 실어 빠르게. 감독이 못 느꼈다.<br><br>뽑은 카드를 봤다. 쉬는 시간. 맨 아래에 있었으니 한 번도 안 넘긴 카드다.<br>세트 위로 카드를 높이 들었다. 장갑들이 멈췄다. 손을 무릎에 얹었다. 감독도 카드 넘기기를 멈췄다. 그 사이 무리가 지났다.<br><br>카드를 세트 각목에 끼워 두고 나왔다. 등 뒤에서 오래 쉬지 못한 것들이 숨을 몰아쉰다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A1', t:'6층 계단 — 신발 벗는 곳',
    x:`6층 계단 앞에 낮은 신발장이 있다. 팻말. 여기서부터 신발을 벗어요.<br><br>
    신발장 칸마다 작은 신발이 들었다. 아이 신발이다. 칸마다 이름표. 빈칸이 여럿이다. 빈칸 이름표 몇 개는 이쪽 일행 이름이다.<br>
    계단 위 놀이 세트에서 아이 웃음이 깔린다. 녹음이다. 웃음 사이에 맨발 소리가 있다. 그건 녹음이 아니다.<br><br>
    척후병은 신발을 안 벗는다. 언제 뛰어야 할지 모르니까.`,
    o:[
      { l:'① 신발장의 신발을 세고 밑창을 본다.', k:'sense', dc:22, wake:1,
        ok:`신발을 셌다. 마흔둘. 칸은 쉰. 빈칸 여덟.<br><br>밑창을 봤다. 마흔하나는 깨끗하다. 신고 걸은 적 없다. 하나만 닳았다. 오래 뛰었다. 그 칸 이름표에 줄이 그어졌다. 그 아이는 신발을 벗었다가 다시 신었다. 그리고 나갔다.<br>그 신발 앞코가 계단이 아니라 옆 직원 통로를 향한다. 그쪽으로 무리를 이끌었다.<br><br>신발 한 짝으로 사람 하나가 간 길을 봤다. 발자국이 아니라 닳은 자리로. 남이 간 길을 남이 신던 것에서 읽는 법을 알았다. 앞의 땅만 읽는 게 아니었다.`,
        ng:`세다가 신발 하나가 칸에서 떨어졌다. 혼자.<br><br>떨어진 신발이 이쪽 발 앞에 섰다. 신으라고. 이쪽 발을 내려다봤다. 신발 끈이 풀려 있다. 언제 풀렸는지 모른다. 손이 끈을 마저 푼다. 이쪽 손이다.<br>무리가 이쪽 손을 잡아 막았다. 신발은 안 벗었다. 끈을 꽉 묶었다. 손가락이 끈에 쓸려 피가 났다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-24 } },
      { l:'② 신발을 신은 채 계단을 앞서 오른다.', k:'evade', dc:23,
        ok:`신발을 신은 채 올랐다. 발소리를 줄였다. 밑창 가장자리로만 디뎠다.<br><br>위에서 웃음이 멎었다. 신발 소리를 들었다. 맨발 소리가 계단 위로 모였다. 기다린다. 계단참에서 멈추고 무리에게 손짓했다. 다른 계단으로.<br>위의 맨발들은 신발 소리를 기다리다 흩어졌다.<br><br>다른 계단 위에 신발장이 또 있다. 팻말이 바뀌었다. 신발 신은 친구는 여기 두고 가요. 칸 하나가 비었다. 어른 신발 크기다.`,
        ng:`계단 중간에서 위의 맨발들이 내려왔다. 작다. 빠르다.<br><br>이쪽 발을 밟고 지나간다. 신발 끈을 잡아당긴다. 넘어졌다. 계단 모서리에 옆구리를 찧었다. 작은 손들이 신발을 벗기려 한다. 걷어찼다.<br>계단 밑까지 굴러 내려왔다. 신발 한 짝이 없다. 위층에서 그 신발을 신발장에 넣는 소리가 났다. 딸깍.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A1', t:'놀이 세트 — 텃밭 동산',
    x:`놀이 세트 한쪽에 텃밭 동산이 있다. 합판 울타리, 그려 넣은 해, 가짜 풀. 허수아비 인형이 섰다. 웃는 얼굴이다.<br><br>
    가짜 풀 사이로 진짜 풀이 자란다. 무대 조명 밑에서. 오래 켜져 있던 조명이다.<br>
    허수아비 얼굴이 조금씩 돈다. 텃밭에 들어온 것을 본다. 허수아비 옆에 작은 허수아비가 셋 더 있다. 텃밭에서 뭔가 뽑은 아이들일 것이다.<br><br>
    척후병은 먹을 것도 찾는다. 무리가 먹어야 걷는다.`,
    o:[
      { l:'① 허수아비 얼굴이 도는 박자를 보며 진짜 나물을 딴다.', k:'sense', dc:22,
        ok:`허수아비 얼굴이 도는 박자를 셌다. 오른쪽 끝까지 가서 멈췄다가 돌아온다. 오른쪽 끝에 멈출 때 왼쪽이 빈다.<br><br>그때마다 왼쪽 고랑에서 한 줌씩 뜯었다. 가짜 풀은 손에 미끄럽고 진짜 풀은 손에 걸린다. 걸리는 것만 뜯었다. 나물이다.<br>세 번 만에 한 아름. 허수아비가 돌아올 때마다 손을 내리고 섰다.<br><br>나오면서 봤다. 작은 허수아비 셋 중 하나가 이쪽으로 고개를 돌렸다. 큰 허수아비는 아직 오른쪽을 본다.`,
        ng:`뜯는데 뿌리가 길었다. 안 뽑힌다. 당겼다. 뿌리가 땅 밑에서 뭔가를 같이 끌어 올렸다. 작은 손이다.<br><br>손이 이쪽 손가락을 쥐었다. 허수아비 얼굴이 이쪽으로 홱 돌았다. 손을 뿌리치고 울타리를 넘었다. 손가락이 꺾일 뻔했다.<br>뒤를 보니 허수아비가 하나 늘어 있다. 이쪽 옷을 닮은 걸 입었다.`,
        win:{ exp:16, dream:1, item:'산나물' }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 텃밭에 안 들어가고 울타리 바깥으로 허수아비 뒤를 돈다.', k:'evade', dc:22,
        ok:`텃밭에 안 들어갔다. 울타리 바깥을 돌았다. 허수아비 등 뒤로.<br><br>허수아비는 텃밭만 본다. 울타리 바깥은 텃밭이 아니다. 등 뒤를 지날 때 허수아비 등에 지퍼가 보였다. 열려 있다. 안이 비었다. 아니다. 안에서 숨소리가 난다.<br>울타리를 다 돌아 다음 문으로 갔다.<br><br>울타리 기둥에 물뿌리개가 걸렸다. 아직 젖었다. 누가 오늘 텃밭에 물을 줬다.`,
        ng:`울타리 바깥이 좁았다. 어깨가 울타리에 닿았다. 합판이 덜컥.<br><br>허수아비 얼굴이 돌았다. 한 바퀴 다. 등 뒤의 이쪽을 본다. 작은 허수아비 셋이 울타리를 넘어온다. 걸음이 서툴다. 서툴러서 무섭다.<br>뛰었다. 하나가 바짓단을 잡았다. 찢고 달렸다. 정강이가 울타리 모서리에 갈렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'A1', t:'스튜디오 — 카메라 세 대',
    x:`생방송 스튜디오 바닥에 카메라 세 대가 섰다. 사람 없이 혼자 돈다. 렌즈마다 빨간 불.<br><br>
    세 렌즈가 스튜디오를 나눠 찍는다. 찍힌 것은 화면에 나간다. 화면에 나간 것은 출연자다.<br>
    세트 반대편 직원 문까지 가야 한다. 셋이 다 비켜 가는 길이 있을 것이다. 렌즈는 앞만 본다.<br><br>
    척후병은 남의 눈이 어디를 보는지부터 본다.`,
    o:[
      { l:'① 세 렌즈가 안 닿는 자리를 이어 길을 낸다.', k:'evade', dc:22, wake:1,
        ok:`셋이 도는 박자를 셌다. 첫째는 왼쪽에서 오른쪽, 둘째는 반대, 셋째는 위아래. 바닥에 빛이 닿는 데와 안 닿는 데가 번갈아 생긴다.<br><br>안 닿는 데를 이었다. 첫 기둥 뒤, 소품 상자 옆, 조명 받침 밑. 무리에게 하나씩 짚어 줬다. 세 박자에 한 칸.<br>직원 문에 닿았다. 무리를 다 넣었다.<br><br>스튜디오를 그림으로 봤다. 바닥 그림이 아니라 눈길 그림이다. 셋이 어디를 보는지가 길이다. 땅에 길이 없으면 남의 눈길 사이에 길이 있다. 그 길이 이제 보인다.`,
        ng:`둘째 카메라가 박자를 바꿨다. 한 번 더 돌았다.<br><br>렌즈가 이쪽을 잡았다. 빨간 불이 깜박였다. 스피커에서 언니 목소리가 났다. 어머, 오늘 친구가 벌써 나왔네! 박수가 쏟아졌다. 발밑 바닥 문이 덜컥 들렸다.<br>옆으로 굴렀다. 바닥 문이 이쪽이 있던 데서 열렸다 닫혔다. 어깨가 조명 받침에 찍혔다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 무력을 실어 카메라 한 대를 벽 쪽으로 비틀어 놓는다.', k:'break', dc:22, cost:{ might:30 },
        ok:`가장 가까운 카메라 받침을 두 손으로 잡았다. 무력을 실어 비틀었다. 렌즈가 벽을 보게.<br><br>렌즈가 벽을 찍는다. 화면에 벽이 나간다. 셋 중 하나가 눈을 감은 셈이다. 남은 둘 사이 빈틈이 넓어졌다.<br>무리를 넓어진 틈으로 보냈다.<br><br>마지막에 지나며 돌아봤다. 비틀어 놓은 카메라가 천천히 돌아온다. 무리가 지나간 자리를 찍었다. 바닥에 찍힌 무리 발자국이 화면에 나간다.`,
        ng:`비트는데 카메라가 이쪽을 향해 돌았다. 받침이 이쪽 힘을 따라왔다.<br><br>렌즈가 코앞이다. 빨간 불. 손을 놓고 몸을 낮췄다. 렌즈가 머리 위를 지나 무리 쪽을 잡았다. 무리 하나가 바닥 문 위에 서 있다.<br>뛰어가 그 사람을 밀쳤다. 바닥 문이 열렸다. 이쪽 발이 문 가장자리에 걸렸다. 발목이 꺾였다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } },
      { l:'③ 기둥 뒤에서 박자를 세어 무리를 하나씩 보낸다.', k:'fix', dc:22,
        ok:`무리를 기둥 뒤에 모았다. 셋 다 비킨 박자에만 한 명씩 보냈다. 하나 가고, 세 박자 쉬고, 또 하나.<br><br>느리다. 그 사이 기둥 뒤에서 박자를 셌다. 틀리면 한 사람이 찍힌다. 안 틀렸다.<br>마지막에 이쪽이 갔다.<br><br>직원 문 안에서 무리를 셌다. 맞다. 스튜디오 스피커에서 박수가 났다. 아무도 안 찍혔는데. 테이프에 박수가 미리 들어가 있었다.`,
        ng:`셋째 사람을 보낼 때 박자를 반 박자 일찍 셌다.<br><br>그 사람이 셋째 렌즈에 걸렸다. 위아래로 도는 렌즈. 스피커가 반겼다. 친구 하나 등장! 바닥 문이 들렸다. 뛰어나가 그 사람을 잡아 끌었다. 이쪽도 찍혔다.<br>둘이 같이 직원 문으로 굴러 들어갔다. 둘 다 무릎이 깨졌다. 화면에 나갔는지는 모른다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } }
    ] },

  { at:'A2', t:'종탑 — 물속 창문을 센다',
    x:`종탑 꼭대기에서 내려다본다. 물속으로 학교 창문이 층층이 보인다. 물이 맑다.<br><br>
    척후병은 들어가기 전에 땅을 본다. 이번 땅은 물속이다. 몇 층인지, 어느 쪽이 무너졌는지.<br>
    창문마다 아주 희미한 불빛이 있다. 창문 몇 개에는 얼굴이 붙어 있다. 위를 본다.<br><br>
    배가 문턱에 닿아 있다. 노가 하나다.`,
    o:[
      { l:'① 물속 창문을 세어 층과 길을 잡는다.', k:'sense', dc:22, wake:1,
        ok:`창문을 셌다. 한 줄에 열둘. 줄이 일곱. 맨 아래 줄은 창문이 아니라 큰 유리다. 강당이다.<br><br>얼굴이 붙은 창문을 따로 셌다. 셋째 줄에 많다. 다섯째 줄에 많다. 둘째와 넷째 줄 한쪽 끝은 비었다. 얼굴이 없는 쪽. 계단이 거기 있을 것이다. 사람이 오래 서 있지 않는 데가 계단이다.<br>무리에게 그렸다. 종탑 바닥에 손가락으로. 일곱 줄, 비어 있는 끝.<br><br>물속 학교 하나를 위에서 다 그렸다. 들어가기 전에. 걷기 전에 땅을 아는 법을 알았다. 얼굴이 없는 데가 길이다.`,
        ng:`세다가 창문 하나에 붙은 얼굴과 눈이 마주쳤다.<br><br>그 얼굴이 창문에서 떨어져 위로 떠오른다. 천천히. 다른 창문 얼굴들도. 수면 바로 밑까지 와서 멈췄다. 다들 이쪽을 본다. 수면이 숨을 쉬듯 한 번 부풀었다.<br>뒤로 물러났다. 종탑 바닥에 엎드려 한참 내려다보지 못했다. 센 숫자를 다 잊었다.`,
        win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-22 } },
      { l:'② 무력을 실어 배를 저어 종탑을 먼저 한 바퀴 돈다.', k:'evade', dc:22, cost:{ might:28 },
        ok:`배에 혼자 올랐다. 무력을 팔에 실어 노를 저었다. 종탑을 한 바퀴.<br><br>물 밑으로 창문들이 지나간다. 창문 하나에서 손이 나와 뱃전을 짚었다. 노로 쳤다. 손이 들어갔다. 더 빨리 저었다.<br>종탑 뒤쪽 물 위로 지붕 하나가 비죽 나와 있다. 기숙사 지붕이다. 종탑 창에서 건너갈 수 있다.<br><br>배를 문턱에 다시 댔다. 노 끝에 머리카락이 감겼다. 길고 젖었다. 떼어 물에 버렸다. 가라앉지 않고 배 옆을 따라 떠 왔다.`,
        ng:`반 바퀴쯤에서 노가 무거워졌다. 물 밑에서 누가 노를 잡았다.<br><br>당긴다. 배가 기울었다. 노를 놓을까 했다. 노는 하나뿐이다. 버텼다. 팔이 빠질 듯하다. 노가 풀렸다. 노 끝에 손자국이 찍혀 있다.<br>문턱까지 저어 돌아왔다. 팔이 한참 안 올라간다. 본 것은 반 바퀴뿐이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A2', t:'교실동 — 자리 배치표',
    x:`교실 앞문에 자리 배치표가 붙었다. 칸마다 이름. 서른다섯 칸. 물에 젖어 글씨가 번졌다.<br><br>
    교실 물은 허리까지다. 의자가 다 빼져 있다. 앉은 만큼. 앞문에서 뒷문으로 지나가야 복도로 이어진다.<br>
    척후병은 지도를 본다. 자리 배치표도 지도다. 누가 어디 앉았는지.<br><br>
    배치표 빈칸 하나에 이쪽 일행 이름이 새로 적혀 있다. 연필이다. 아직 번지지 않았다.`,
    o:[
      { l:'① 배치표로 빈자리를 피해 길을 잡는다.', k:'gaze', dc:22,
        ok:`배치표를 봤다. 이름 칸 서른넷. 빈칸 하나. 이쪽 일행 이름이 적힌 칸이다. 셋째 줄 가운데.<br><br>그 자리 옆을 안 지나는 길을 그렸다. 창가 줄을 따라 맨 뒤로. 의자 빠진 자리마다 물이 조금 무겁다. 앉은 것이 있다. 그 사이로 무리를 한 줄로 이끌었다.<br>셋째 줄 가운데만 물이 가볍다. 의자가 빠진 채 기다린다. 멀리 돌았다.<br><br>뒷문을 나서며 배치표를 다시 봤다. 이쪽 일행 이름이 지워지고 다른 칸에 옮겨 적혔다. 창가 줄 맨 뒤. 이쪽이 지나간 자리다.`,
        ng:`보는데 글씨가 계속 번졌다. 물이 배치표를 타고 올라온다.<br><br>이름들이 섞였다. 어느 칸이 빈칸인지 모르겠다. 짐작으로 걸었다. 가운데 줄에서 물이 가벼웠다. 의자가 무릎 뒤를 쳤다. 주저앉을 뻔했다. 무리가 겨드랑이를 들었다.<br>뒷문까지 갔다. 무릎 뒤에 의자 모서리 자국이 깊게 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-22 } },
      { l:'② 열 걸음 앞서 교실을 가로질러 본다.', k:'evade', dc:23,
        doom:{ title:'자리 배치', what:'빈자리로 끌려가 앉혀집니다', dc:18, sec:45,
          text:`무리보다 열 걸음 앞서 교실을 가로질렀다. 척후병의 일이다.<br><br>셋째 줄 가운데에서 물이 가벼웠다. 의자가 빠져 있다. 지나치려는데 양옆 자리에서 손이 올라와 소매를 잡았다. 앉아. 네 자리야. 친절하다.<br>어깨를 누르는 손이 여럿이다. 의자가 무릎 뒤를 받친다. 자리로 끌려가 앉혀진다. 물이 가슴까지, 턱까지 온다. 앉은 키만큼.<br><br>칠판에서 분필 소리가 난다. 이쪽 이름이 출석부 마지막 칸에 쓰인다.`,
          dieText:`척후병의 자리는 무리 열 걸음 앞이다. 교실에는 그 자리가 없었다.<br><br>자리 배치표 서른다섯 칸이 다 찼다.<br>셋째 줄 가운데 이름만 아직 번지지 않았다.` },
        ok:`열 걸음 앞서 가되 의자 등받이를 하나씩 짚으며 갔다. 빈자리를 손으로 미리 알게.<br><br>셋째 줄 가운데에서 손이 빈 데를 짚었다. 의자가 없다. 빈자리다. 거기서 멈췄다. 양옆에서 손이 올라왔다. 소매를 잡기 전에 물러섰다.<br>무리에게 신호했다. 셋째 줄은 비켜라. 무리가 창가로 돌았다.<br><br>뒷문에서 돌아보니 셋째 줄 가운데에 의자가 하나 밀려 들어와 있다. 누가 앉혀 보려고 넣어 둔 것이다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 무력을 실어 책상을 밀어 한 줄 길을 낸다.', k:'break', dc:22, cost:{ might:30 },
        ok:`허리 물속에서 책상을 밀었다. 무력을 다 실었다. 책상들이 한쪽으로 몰린다. 끼익. 물 밑 바닥에 책상 다리 긁히는 소리.<br><br>창가 쪽에 한 줄 길이 났다. 책상이 없으니 자리도 없다. 자리가 없으니 앉을 데도 없다. 무리가 그 길로 지났다.<br>마지막에 이쪽이 지났다. 몰린 책상들 사이에서 의자 빼는 소리가 났다. 자리를 잃은 것들이 일어선다.<br><br>복도로 나와 숨을 몰아쉬었다. 팔이 떨린다. 교실 안에서 책상을 제자리로 끌어다 놓는 소리가 한참 났다.`,
        ng:`미는데 책상 하나가 안 밀렸다. 누가 앉아 있다.<br><br>밀수록 버틴다. 책상 밑에서 작은 발이 정강이를 찼다. 수업 중이라고. 힘이 빠졌다. 다른 책상들이 제자리로 밀려와 이쪽을 끼웠다.<br>책상 사이에서 몸을 빼냈다. 갈비가 모서리에 눌려 숨 쉴 때마다 결린다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] },

  { at:'A2', t:'식당동 — 보이지 않는 줄',
    x:`식당 물이 가슴까지다. 배식대 앞에 줄이 있다. 보이지 않는 줄이다. 물이 거기만 조금씩 앞으로 밀린다.<br><br>
    줄은 식당을 가로질러 뒷문 앞까지 이어진다. 뒷문으로 나가야 조리실이다. 줄을 끊고 지나가면 새치기다. 새치기는 줄 맨 끝으로 보내진다. 줄에 서게 된다.<br>
    척후병은 줄 끝을 찾는다. 끝을 알아야 끊지 않고 돈다.<br><br>
    물 밀리는 박자가 느리다. 한 사람씩.`,
    o:[
      { l:'① 물이 밀리는 결을 읽어 줄 끝을 돌아간다.', k:'evade', dc:22,
        ok:`물결을 봤다. 줄이 선 데는 물이 앞으로 밀리고 아닌 데는 가만있다. 밀리는 결을 따라 줄 끝을 찾았다. 창가 쪽이다.<br><br>무리를 줄 끝 뒤로 돌렸다. 끊지 않고 끝을 돌아 뒷문 쪽으로. 멀다. 물이 차다.<br>뒷문에 닿았다. 문 앞이 줄 맨 앞이다. 배식대 국자가 이쪽으로 기운다. 문을 열고 빠졌다.<br><br>문을 닫으며 들었다. 국자가 국을 뜨는 소리. 다음.`,
        ng:`결을 읽었는데 줄이 둘이었다. 하나는 배식대, 하나는 퇴식구.<br><br>퇴식구 줄을 끊었다. 물이 이쪽을 확 밀었다. 줄 맨 끝으로. 앞사람 등이 차다. 뒷사람 손이 어깨를 짚는다. 줄이 앞으로 간다. 이쪽도 간다.<br>무리가 끌어냈다. 빠지는데 어깨 짚은 손이 오래 안 떨어졌다. 어깨가 얼었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 밀리는 박자를 세어 줄 길이를 잰다.', k:'sense', dc:23,
        ok:`물이 밀리는 박자를 셌다. 국자 소리 한 번에 물 한 번. 줄 끝에서 맨 앞까지 물이 전해지는 시간을 쟀다. 서른한 명이다.<br><br>서른한 명이면 끝이 배식대에서 얼마나 떨어졌는지 나온다. 줄 끝에서 반 걸음 떨어져 돌았다. 줄은 딱 그만큼만 길다.<br>뒷문으로 나갔다.<br><br>조리실 저장고 앞에 소금 자루가 있다. 물에 녹다 굳어 덩이가 됐다. 한 덩이 깼다. 서른한 명이 다 먹고 남긴 것이다.`,
        ng:`세다가 박자가 늘었다. 줄이 길어진다. 새로 서는 것이 있다.<br><br>줄 끝이 이쪽 쪽으로 자란다. 피하려고 물러났다. 물러난 자리가 줄 끝이 됐다. 앞사람 등이 코앞이다. 차가운 머리카락이 얼굴에 닿았다.<br>옆으로 비켜 뛰었다. 물이 무겁다. 뒷문까지 오래 걸렸다. 얼굴에 닿았던 머리카락 냄새가 안 빠진다.`,
        win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ mind:-20, spirit:-22 } }
    ] },

  { at:'A2', t:'본관 — 마지막 공기',
    x:`본관 중앙 계단이 물속으로 내려간다. 이 층은 턱까지 찼다. 그 밑은 완전히 잠겼다.<br><br>
    다음 층까지 숨을 참고 가야 한다. 물 밑 계단 어딘가에 공기 자리가 있을 것이다. 천장이 높은 데, 꺾인 데.<br>
    척후병은 먼저 가서 공기 자리를 찾고 돌아와야 한다. 숨 한 번으로 가서 숨 한 번으로 돌아와야 한다.<br><br>
    물 밑 계단 칸마다 작은 신발이 한 짝씩 놓였다.`,
    o:[
      { l:'① 무력을 실어 숨을 참고 앞서 헤엄쳐 공기 자리를 찾고 온다.', k:'evade', dc:23, cost:{ might:30 },
        doom:{ title:'마지막 공기', what:'물 밑 계단으로 끌려 가라앉습니다', dc:18, sec:45,
          text:`숨을 크게 들이쉬고 물속으로 들어갔다. 무력을 팔다리에 실어 계단을 따라 헤엄쳤다. 빠르다.<br><br>계단참에서 천장을 더듬었다. 공기가 없다. 다음 계단참. 없다. 숨이 반 남았다. 돌아서려는데 발목이 잡혔다. 계단 칸 신발 옆에서 작은 손이.<br>손이 하나 더. 칸마다 하나씩. 이쪽을 아래 칸으로 데려간다. 줄 서라고. 숨이 줄어든다. 위쪽 수면이 멀다.<br><br>입에서 공기 방울이 빠져나간다. 하나, 둘. 위로 올라간다. 이쪽은 아래로 끌려간다.`,
          dieText:`숨 한 번으로 가서 숨 한 번으로 돌아온다. 돌아오는 숨이 모자랐다.<br><br>무리는 계단 위에서 기다렸다. 수면에 공기 방울이 올라왔다. 하나, 둘.<br>물 밑 계단 칸에 큰 신발이 한 짝 늘었다.` },
        ok:`숨을 들이쉬고 들어갔다. 무력을 실어 계단을 헤엄쳤다. 칸마다 놓인 신발은 안 건드렸다. 손이 그 옆에 있을 것이다.<br><br>둘째 계단참 천장이 꺾인 데에 공기가 있었다. 머리 하나 들어갈 만큼. 숨을 갈았다. 거기서 다음 층 문이 보였다.<br>돌아왔다. 숨 한 번으로. 무리에게 손가락으로 그렸다. 둘째 계단참, 왼쪽 위.<br><br>무리가 하나씩 따라갔다. 이쪽은 맨 뒤에서. 공기 자리에서 숨을 갈 때 공기에서 다른 숨 냄새가 났다. 누가 먼저 이 공기를 썼다. 오래전에.`,
        win:{ exp:24, dream:3 } },
      { l:'② 허리에 줄을 매고 무리가 끝을 쥐게 한 다음 간다.', k:'bond', dc:22,
        ok:`허리에 줄을 맸다. 무리가 끝을 쥐었다. 신호를 정했다. 두 번이면 끌어 올린다.<br><br>물속으로 들어갔다. 계단을 따라 내려갔다. 첫 계단참에 공기가 없다. 둘째에 있다. 머리를 넣고 숨을 갈았다. 줄을 한 번 당겼다. 찾았다는 신호.<br>무리가 줄을 따라 하나씩 내려왔다. 줄이 길을 대신했다.<br><br>마지막 사람이 공기 자리에 머리를 넣었을 때 줄이 한 번 더 당겨졌다. 위에서. 무리는 다 여기 있다.`,
        ng:`내려가는데 줄이 두 번 당겨졌다. 이쪽은 안 당겼다.<br><br>무리가 이쪽을 끌어 올렸다. 공기 자리 바로 앞에서 수면으로 끌려 나왔다. 숨이 터졌다.<br>무리는 신호를 받았다고 한다. 두 번. 줄을 다시 매고 들어갔다. 이번엔 찾았다. 그 사이 숨을 너무 썼다. 머리가 깨질 듯하다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } },
      { l:'③ 신발이 빈 칸을 세어 공기 자리를 짐작한다.', k:'sense', dc:22,
        ok:`물 밖에서 내려다봤다. 신발이 칸마다 놓였다. 그런데 몇 칸은 비었다. 둘째 계단참 위 세 칸.<br><br>신발 주인들이 거기서는 서 있지 않았다. 서 있을 필요가 없었다. 숨을 쉴 수 있는 데라서. 공기 자리다.<br>그 칸까지 단숨에 헤엄쳤다. 천장 꺾인 데에 공기가 있었다. 무리를 불렀다.<br><br>공기 자리 벽에 손톱으로 쓴 글씨가 있다. 숨 쉬고 가. 오래전 글씨다.`,
        ng:`빈칸을 셌는데 물 밑에서 신발 하나가 옮겨졌다. 빈칸 위로.<br><br>짐작이 틀렸다. 첫 계단참으로 헤엄쳤다. 공기가 없다. 숨이 끊길 듯했다. 되돌아 올라왔다. 수면에서 숨을 몰아쉬는데 물 밑 신발들이 다 이쪽을 향해 돌아앉았다.<br>결국 무리 하나가 공기 자리를 찾았다. 그 사이 이쪽은 물을 너무 먹었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-20 } }
    ] },

  { at:'A2', t:'배수로 — 당기는 물',
    x:`체육관 밑 배수로다. 물이 한쪽으로 빠르게 흐른다. 큰 배수구로 빨려 들어간다. 쇠창살이 달렸다. 창살 사이에 교복 천 조각, 실내화, 머리끈이 걸렸다.<br><br>
    건너편으로 건너야 강당 쪽 문이 나온다. 물살 너비가 다섯 걸음.<br>
    척후병은 앞서 건너 줄을 매고 무리를 넘긴다. 앞서 건너는 사람이 제일 위험하다.<br><br>
    물 밑에서 배수구로 향한 손들이 보인다. 다 같은 쪽을 가리킨다.`,
    o:[
      { l:'① 물살이 약한 결을 읽어 먼저 건넌다.', k:'evade', dc:23,
        doom:{ title:'배수로', what:'배수구 창살 쪽으로 빨려 들어갑니다', dc:18, sec:45,
          text:`물살 결을 봤다. 약한 데를 골라 들어갔다. 허리까지. 한 걸음, 두 걸음.<br><br>셋째 걸음에 바닥이 없었다. 몸이 물살에 실렸다. 배수구 쪽으로 빨려 간다. 빠르다. 창살에 몸이 부딪쳤다. 등에 창살이 박힌다. 창살 사이로 물이 빨려 나간다. 옷자락도 같이.<br>창살 너머 어둠에서 손들이 옷자락을 잡았다. 안으로 당긴다. 창살 틈은 좁다. 사람은 못 지나간다. 그래도 당긴다.<br><br>무리가 줄을 던진다. 손이 줄에 닿을락 말락 한다.`,
          dieText:`앞서 건너는 사람이 제일 위험하다. 그걸 알고 앞서 건넌다.<br><br>배수구 창살에 걸린 것이 하나 늘었다. 척후병의 숯 주머니다.<br>무리는 그 주머니를 보고 반대편으로 길을 찾았다.` },
        ok:`결을 읽고 들어가되 창살 반대쪽으로 비스듬히 걸었다. 물살을 거스르지 않고 반쯤 실려 건넜다. 닿을 자리를 처음부터 하류 쪽에 잡았다.<br><br>셋째 걸음에 바닥이 꺼졌다. 몸이 실렸다. 셈한 만큼만 실렸다. 건너편 벽에 손이 닿았다. 창살 다섯 걸음 앞이다. 기어올랐다.<br>줄을 매고 무리를 넘겼다. 다들 하류 쪽으로 비스듬히.<br><br>창살 너머 손들이 이쪽을 향해 손가락을 접었다 폈다 한다. 다음에는, 하고.`,
        win:{ exp:24, dream:3 } },
      { l:'② 무력을 실어 창살을 붙잡고 둑이 되어 무리를 넘긴다.', k:'steady', dc:22, cost:{ might:30 },
        ok:`창살 옆 벽을 따라 내려가 창살을 두 손으로 잡았다. 무력을 팔에 박았다. 이쪽 몸이 창살 앞에서 물살을 막는 둑이 됐다.<br><br>무리가 이쪽 등 뒤로 건넜다. 이쪽 등이 물살을 갈랐다. 하나, 둘. 다 건넜다.<br>마지막에 창살을 놓고 물살에 실려 건너편 벽을 잡았다.<br><br>창살을 잡았던 손바닥에 교복 천 조각이 붙어 있다. 이름표가 달렸다. 17. 창살 너머에서 누가 이쪽 손에 쥐여 준 것 같다.`,
        ng:`창살을 잡았는데 창살 너머에서 손이 이쪽 손가락을 하나씩 폈다.<br><br>한 손이 풀렸다. 몸이 창살에 눌렸다. 물살이 갈비를 민다. 숨이 안 쉬어진다. 남은 손으로 버텼다. 무리가 줄로 끌어냈다.<br>건너편에 쓰러졌다. 갈비에 창살 자국이 일곱 줄. 숨 쉴 때마다 결린다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] }
]);

// ── 투우사 (matador) · 무력 ──────────────────
kJob('matador', 'A', [
  { at:'A', t:'복도 — 등을 보이면 다가오는 것',
    x:`복도 끝에 뭔가 서 있다. 이쪽이 보는 동안은 안 움직인다.<br><br>
    일행 하나가 등을 돌렸다가 돌아봤다. 그것이 다섯 걸음 가까워져 있었다. 소리도 없이.<br>
    투우사는 등을 보이지 않는다. 늘 정면이다. 오늘은 그게 목숨이다.<br><br>
    나가는 문은 그것 쪽이 아니다. 등 뒤 쪽이다. 문까지 서른 걸음.`,
    o:[
      { l:'① 그것을 마주 본 채 뒷걸음으로 문까지 간다.', k:'steady', dc:22, wake:1,
        ok:`그것을 봤다. 눈을 떼지 않았다. 뒷걸음으로 한 걸음. 그것은 안 움직인다. 또 한 걸음.<br><br>일행을 이쪽 등 뒤로 줄 세웠다. 이쪽 정면 하나로 다 가렸다. 이쪽이 보는 동안은 일행 등도 보이는 등이 아니다. 서른 걸음. 문고리가 등에 닿았다.<br>일행을 먼저 내보냈다. 마지막에 이쪽이 문턱을 넘었다. 눈은 끝까지 그것에.<br><br>문을 닫는 순간 그것이 문 앞에 와 있었다. 문짝이 그것 코앞에서 닫혔다. 정면을 지키는 건 버릇이었다. 오늘은 그 버릇이 일행 전부를 덮는 벽이 됐다. 눈 하나로 몇 사람의 등을 지킬 수 있는지 알았다.`,
        ng:`스무째 걸음에서 발뒤꿈치가 뭔가에 걸렸다. 넘어지며 눈이 천장을 봤다.<br><br>한 박자. 그것이 왔다. 얼굴 앞이다. 숨이 없다. 손이 발목을 잡았다. 눈을 다시 그것에 박았다. 멈췄다. 손은 안 놓는다.<br>발목을 비틀어 빼냈다. 문까지 기었다. 눈은 그것에 둔 채. 발목에 손자국이 시퍼렇다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 천을 벽에 걸어 두고 등을 돌려 달린다.', k:'evade', dc:23,
        doom:{ title:'돌아선 등', what:'등 뒤의 것에게 붙잡혀 끌려갑니다', dc:18, sec:50,
          text:`천을 벽 못에 걸었다. 그것과 이쪽 사이에. 천이 대신 보고 있게. 등을 돌려 달렸다.<br><br>천은 눈이 없다. 다섯 걸음째에 등에 바람이 닿았다. 열 걸음째에 뒷덜미에 손이 닿았다. 차갑다. 옷깃을 쥐었다.<br>몸이 뒤로 끌려간다. 발이 바닥을 긁는다. 돌아보려 해도 목이 안 돌아간다. 옷깃이 목을 조인다. 복도 끝 쪽으로 끌려간다. 천 옆을 지나간다.<br><br>일행이 외친다. 그것을 보라고. 누구든 보라고.`,
          dieText:`투우사는 등을 보이지 않는다. 그 한 번이었다.<br><br>복도 벽 못에 회색 천이 걸려 있다.<br>복도 끝에 서 있는 것이 둘이 됐다. 둘 다 이쪽을 보고 있다.` },
        ok:`천을 벽 못에 걸고, 등을 돌리기 전에 일행 하나에게 말했다. 그것을 봐. 눈 떼지 마.<br><br>일행이 그것을 봤다. 이쪽은 등을 돌려 문까지 달렸다. 문을 열었다. 돌아서서 그것을 봤다. 이번엔 이쪽이 볼 차례다. 일행이 등을 돌려 달려왔다.<br>번갈아 보며 다 나왔다. 천을 걷으러 갈 수는 없었다.<br><br>문을 닫기 전에 봤다. 천이 못에서 떨어져 그것 발밑에 있다. 그것이 천을 내려다본다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 무력을 실어 천을 던져 그것 머리에 덮는다.', k:'evade', dc:22, cost:{ might:28 },
        ok:`천을 펼쳐 무력을 실어 던졌다. 천이 펼쳐지며 날았다. 그것 머리에 덮였다.<br><br>눈이 가려졌다. 이쪽도 그것을 못 본다. 그것도 이쪽을 못 본다. 서로 못 보는 동안은 아무도 등을 보인 게 아니다.<br>일행 모두 뛰었다. 문을 나왔다. 닫았다.<br><br>문틈으로 봤다. 천 덮인 것이 그 자리에 그대로 서 있다. 천 밑에서 머리가 이쪽을 향해 천천히 돈다. 천을 벗지 않는다.`,
        ng:`던졌는데 천이 펼쳐지지 않고 뭉쳐 그것 발 앞에 떨어졌다.<br><br>천을 보느라 일행이 그것에게서 눈을 뗐다. 그것이 단숨에 다가왔다. 이쪽 바로 앞이다. 다시 봤다. 멈췄다. 숨이 닿을 거리다.<br>그 거리에서 뒷걸음질로 문까지 갔다. 그것이 이쪽 이마에 손가락을 댔다 뗐다. 이마가 얼어 한참 감각이 없다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-18 } }
    ] },

  { at:'A', t:'방 — 기어 오는 것',
    x:`방바닥을 뭔가 긴다. 느리다. 아주 느리다. 이쪽으로.<br><br>
    달려들지 않는다. 투우사는 달려드는 것을 안다. 달려드는 것은 마지막 한 뼘에 못 꺾는다. 기는 것은 언제든 꺾는다.<br>
    그것이 다가올수록 방이 좁아진다. 문은 그것 뒤에 있다.<br><br>
    천을 쥔 손에 땀이 찬다. 천은 달려드는 것에게 쓰는 물건이다.`,
    o:[
      { l:'① 천을 흔들어 기는 것을 달려들게 만든다.', k:'evade', dc:23, wake:1,
        ok:`천을 펼쳐 흔들었다. 크게. 바닥을 쓸듯이. 천 끝이 그것 코앞을 스쳤다. 또 스쳤다.<br><br>그것이 멈췄다. 몸을 웅크렸다. 기던 것이 뛸 준비를 한다. 뛰었다. 빠르다. 그러나 똑바로 온다. 마지막 한 뼘에 천을 옆으로 뺐다. 그것이 천을 따라 지나갔다. 벽에 부딪혔다.<br>그 틈에 문을 나섰다.<br><br>달려드는 것만 상대할 줄 알았다. 이제 아니다. 기는 것을 달리게 만들었다. 상대가 어떻게 올지를 이쪽이 정했다. 천이 비키는 물건에서 부르는 물건이 됐다.`,
        ng:`천을 흔들었는데 그것이 천을 피해 기었다. 천 밑으로.<br><br>천 밑으로 기어 와서 발목을 감았다. 차고 미끈하다. 천을 놓고 발을 뺐다. 천이 그것 등에 덮였다. 그것이 천을 업은 채 계속 긴다.<br>문까지 뛰었다. 발목에 감긴 자국이 미끈하게 남았다. 천은 방 안에 두고 왔다. 손이 허전하다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-22 } },
      { l:'② 구석으로 물러나 꺾을 데를 지운다.', k:'steady', dc:22,
        ok:`방 구석으로 물러났다. 등을 벽에 댔다. 그것이 다가온다. 느리게.<br><br>구석에서는 그것이 정면으로만 온다. 옆으로 꺾을 데가 없다. 이쪽이 꺾을 데를 다 지웠다. 그것이 발끝 앞까지 왔다. 멈췄다. 고개를 든다.<br>그 순간 옆으로 한 걸음, 그것을 넘어 문으로 갔다. 구석에 남은 것은 그것이다.<br><br>문을 닫으며 봤다. 그것이 구석 벽을 오래 본다. 이쪽이 있던 자리를.`,
        ng:`구석에서 기다렸다. 그것이 발끝에서 멈추지 않았다. 발등을 타고 올라왔다.<br><br>정강이, 무릎. 무겁다. 차다. 옆으로 뛰었다. 그것이 다리에서 떨어지며 종아리를 길게 긁었다.<br>문을 나와 종아리를 봤다. 긁힌 데가 하얗게 부풀었다. 오래 따끔거린다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A', t:'복도 — 손만 나오는 문들',
    x:`복도 양옆에 문이 줄지어 있다. 다 조금씩 열렸다.<br><br>
    지나갈 때마다 문틈에서 손이 나온다. 빠르다. 지나가는 것을 잡는다. 잡힌 것은 문 안으로 들어간다. 앞서 누가 떨어뜨린 짐이 하나씩 문 안으로 들어갔다.<br>
    투우사는 잡으려는 손도 달려드는 것으로 본다. 손도 마지막 한 뼘에 못 꺾는다.<br><br>
    문이 열둘이다.`,
    o:[
      { l:'① 천을 문 쪽에 늘어뜨려 손이 천을 잡게 하며 지난다.', k:'evade', dc:22,
        ok:`천을 펼쳐 몸 옆에 늘어뜨렸다. 문 쪽으로. 첫 문에서 손이 나왔다. 천을 잡았다. 천을 뺐다. 손이 빈손으로 들어갔다.<br><br>둘째 문, 셋째 문. 손이 나올 때마다 뺐다. 손은 처음 본 것을 잡는다. 천이 먼저 보인다.<br>열두 문을 다 지났다. 천이 구멍투성이다. 손톱 자국이다.<br><br>천을 털었다. 구멍마다 손톱이 하나씩 박혀 있다. 하나씩 빼냈다. 열한 개. 하나가 모자란다.`,
        ng:`일곱째 문에서 손이 둘 나왔다. 하나는 천, 하나는 손목.<br><br>천을 뺐다. 손목은 못 뺐다. 문 안으로 당긴다. 어깨가 문틀에 부딪쳤다. 문짝을 발로 찼다. 문이 손을 짓찧었다. 손이 놓았다.<br>나머지는 뛰어서 지났다. 손목이 부었다. 문 안에서 문짝을 원망하는 소리가 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-18 } },
      { l:'② 천을 넣고 맨몸으로 반 걸음씩 비켜 지난다.', k:'evade', dc:23,
        doom:{ title:'열린 문', what:'문틈의 손에 문 안으로 끌려 들어갑니다', dc:18, sec:50,
          text:`천을 접어 넣었다. 맨몸으로 지났다. 손이 나오는 순간 반 걸음 비켰다. 첫 문, 둘째 문. 된다.<br><br>여섯째 문에서 손이 안 나왔다. 반 걸음 비킨 쪽, 맞은편 문에서 나왔다. 이쪽이 비킬 쪽을 알았다. 옆구리 옷을 잡았다.<br>문 안으로 끌려간다. 어깨가 문틈에 낀다. 문이 좁다. 그래도 들어간다. 안이 깜깜하다. 안에 손이 많다. 다 이쪽을 잡는다.<br><br>일행이 다리를 잡았다. 문틈이 조금씩 닫힌다.`,
          dieText:`손도 마지막 한 뼘에 못 꺾는다. 맞은편에서 오는 손은 꺾을 필요가 없었다.<br><br>복도 양옆에 문이 열둘이다. 하나가 닫혔다.<br>닫힌 문 안에서 회색 천을 개는 소리가 난다.` },
        ok:`천을 넣고 반 걸음씩 비켰다. 비킬 때 맞은편 문을 같이 봤다.<br><br>여섯째 문에서 손이 안 나왔다. 맞은편이다. 이쪽이 비킬 쪽에서 손이 나왔다. 비키지 않고 그 자리에 섰다. 맞은편 손이 빈 데를 쥐었다. 반 걸음 앞에서.<br>남은 문을 다 지났다. 한 번 더 그랬다. 비킬 데를 비켜 서는 것.<br><br>복도 끝에서 돌아보니 문들이 다 닫혔다. 그다음 다시 조금씩 열렸다. 다음 사람을 기다린다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A', t:'계단 — 굴러 내려오는 것',
    x:`계단 위에서 뭔가 굴러 내려온다. 한 칸씩. 쿵, 쿵.<br><br>
    처음엔 주먹만 했다. 칸마다 커진다. 지금은 사람 머리만 하다. 털이 붙었다. 머리카락이다.<br>
    계단은 좁다. 옆으로 비킬 데가 반 걸음이다. 투우사는 굴러오는 것도 소처럼 본다. 똑바로 오고, 마지막에 못 꺾는다.<br><br>
    다만 이것은 칸마다 커진다. 마지막 칸에서는 얼마나 클지 모른다.`,
    o:[
      { l:'① 마지막 한 칸에서 천을 빼고 반 걸음 비킨다.', k:'evade', dc:22,
        ok:`반 걸음 자리에 섰다. 천을 펼쳤다. 그것이 내려온다. 쿵, 쿵. 이쪽 키만 하다.<br><br>마지막 칸에서 천을 반대로 뺐다. 그것이 천을 스치며 지나갔다. 바람이 얼굴을 쳤다. 머리카락이 천에 걸려 한 움큼 뜯겼다. 그것이 계단 밑으로 굴러갔다.<br>밑에서 멈췄다. 굴러가지 않는다. 천천히 돌아선다. 얼굴이 있는 쪽이 이쪽을 향한다.<br><br>천에 걸린 머리카락을 털었다. 안 털린다. 천에 엉켰다.`,
        ng:`반 걸음이 모자랐다. 그것이 이쪽보다 컸다.<br><br>어깨를 스쳤다. 스친 게 아니라 쳤다. 계단에 넘어졌다. 그것이 지나가며 머리카락이 이쪽을 감았다. 끌려갈 뻔했다. 천으로 머리카락을 쳐 냈다.<br>계단에 엎드려 숨을 몰아쉬었다. 어깨가 빠졌다 들어갔다. 목에 머리카락 자국이 감겼다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-18 } },
      { l:'② 무력을 실어 받아서 난간 너머로 흘린다.', k:'steady', dc:22, cost:{ might:30 },
        ok:`몸을 낮추고 두 팔로 받았다. 무력을 다 실었다. 팔에 닿는 순간 옆으로 밀었다. 난간 쪽으로.<br><br>그것이 난간을 넘어 계단통 아래로 떨어졌다. 한참 뒤에 쿵. 그리고 조용하다.<br>팔이 저리다. 팔에 머리카락이 붙어 있다. 길다. 떼어 냈다.<br><br>계단통 아래에서 쿵, 쿵. 한 칸씩. 다시 올라오는 소리다. 작아지면서.`,
        ng:`받았는데 무거웠다. 칸마다 커진 만큼 무거웠다.<br><br>밀려서 뒤로 넘어졌다. 그것이 위를 굴러 지나갔다. 머리카락이 얼굴을 덮었다. 숨이 막혔다. 지나갔다.<br>일어났다. 갈비가 아프다. 입 안에 머리카락이 있다. 뱉어도 나온다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] },

  { at:'A', t:'복도 — 천을 달라는 목소리',
    x:`어둠 속에서 목소리가 난다. 그 천, 줘.<br><br>
    낮고 다정하다. 천을 주면 지나가게 해 준다고 한다. 이쪽 앞 바닥에 천들이 쌓여 있다. 색이 다 다르다. 다 낡았다. 다 투우사 천이다.<br>
    투우사는 천을 남에게 안 준다. 천이 투우사다.<br><br>
    목소리가 조금 가까워졌다. 줘.`,
    o:[
      { l:'① 천을 손에 감아 쥐고 주지 않는다.', k:'steady', dc:22,
        ok:`천을 손에 감았다. 더 꽉. 대답하지 않았다.<br><br>목소리가 서운해한다. 다른 사람들은 다 줬어. 쌓인 천이 조금 흔들린다. 천 밑에서 뭔가 움직인다. 천 감은 손을 가슴에 댔다.<br>오래 섰다. 목소리가 지쳤다. 그럼 그거 들고 가. 다음에 줘.<br><br>지나갔다. 천 더미 옆을 지날 때 천 하나가 발목을 스쳤다. 손 같았다. 천을 내준 이의 손.`,
        ng:`쥐었는데 손이 저절로 펴졌다. 천이 미끄러진다.<br><br>목소리가 웃었다. 천 끝이 더미에 닿았다. 더미가 천을 당긴다. 손목까지. 다시 쥐고 당겼다. 천이 찢어졌다. 끝 한 뼘이 더미에 남았다.<br>찢어진 천을 들고 지났다. 손바닥이 천에 쓸려 피가 났다. 천이 짧아졌다. 이쪽도 짧아진 것 같다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-24 } },
      { l:'② 천을 쥔 채 쌓인 천 더미를 들춰 본다.', k:'gaze', dc:23,
        ok:`천을 쥔 채 쪼그려 앉아 더미를 들췄다. 맨 위 천 밑에 신발이 있다. 그 밑에 또 천. 또 신발.<br><br>천을 준 사람마다 신발 한 켤레씩. 천을 주고 지나간 게 아니다. 신발까지 주었다. 맨 밑에는 신발이 없다. 천만 깔렸다. 그 위에 발자국이 있다. 지나간 발자국. 맨 처음 사람은 천을 안 줬다.<br>안 준 사람은 지나갔다. 그걸 알고 일어섰다. 목소리를 지나쳤다.<br><br>목소리가 등 뒤에서 울었다. 다 보여 주면 어떡해.`,
        ng:`들추는데 더미 밑에서 손이 이쪽 천을 잡았다.<br><br>더미가 천을 끌어당긴다. 이쪽도 끌려간다. 천을 놓으면 끝이다. 안 놓았다. 무릎이 더미에 박혔다. 천 사이에서 다른 손들이 팔을 쓰다듬는다. 반갑게.<br>일행이 허리를 잡아당겼다. 천째 빠져나왔다. 팔에 손자국이 여럿이다. 다 따뜻했다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-26 } }
    ] },

  { at:'A', t:'어둠 — 숨이 닿는 거리',
    x:`불이 꺼졌다. 깜깜하다. 일행 숨소리만 들린다.<br><br>
    하나가 더 있다. 숨소리. 가깝다. 이쪽으로 온다. 걷지 않는다. 다가온다.<br>
    투우사는 눈으로만 비키지 않는다. 발소리가 없으면 숨소리를 듣는다. 숨이 얼굴에 닿는 순간이 한 뼘이다.<br><br>
    숨이 차다. 이쪽 숨이 아니다.`,
    o:[
      { l:'① 천을 얼굴 앞에 들고 숨이 천에 닿는 순간 비킨다.', k:'evade', dc:23, wake:1,
        ok:`천을 펼쳐 얼굴 앞에 들었다. 기다렸다. 숨이 천에 닿았다. 천이 아주 조금 부풀었다.<br><br>그 순간 천을 옆으로 빼고 반대로 비켰다. 천을 따라 숨이 지나갔다. 바람이 볼을 스쳤다. 숨소리가 멀어졌다.<br>불을 켰다. 아무것도 없다. 천에 젖은 자국이 있다. 입 모양이다.<br><br>눈 없이 비켰다. 귀로도 아니다. 천에 닿는 숨으로 거리를 쟀다. 천이 살갗보다 먼저 느낀다. 천 끝까지가 이쪽 몸이다.`,
        ng:`숨이 천을 돌아서 왔다. 천에 안 닿고 바로 목에 닿았다.<br><br>차다. 목덜미에 입술이 닿았다. 비켰다. 늦었다. 목덜미가 얼어붙었다. 불을 켰다. 아무것도 없다.<br>목덜미에 하얀 자국이 남았다. 고개를 돌릴 때마다 시리다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
      { l:'② 천을 반대쪽으로 던져 끌어 소리를 옮긴다.', k:'sense', dc:22,
        ok:`천 끝을 쥐고 반대쪽 바닥으로 던져 끌었다. 사락사락. 천 끄는 소리가 이쪽 반대편에서 난다.<br><br>숨소리가 그쪽으로 갔다. 천 소리 쪽으로. 이쪽은 숨을 멈추고 반대로 갔다. 벽을 더듬어 문을 찾았다.<br>불을 켰다. 천이 바닥에 떨어져 있다. 그 위에 무엇이 엎드려 숨을 쉬다가 사라졌다.<br><br>천을 주웠다. 따뜻하다.`,
        ng:`던졌는데 소리가 이쪽 발밑에서 났다. 천이 발에 걸렸다.<br><br>숨소리가 발밑으로 왔다. 다리를 타고 올라온다. 무릎, 허리, 가슴. 천을 걷어차며 뛰었다. 벽에 머리를 부딪쳤다.<br>불을 켰다. 이마가 찢어졌다. 천은 그 자리에 남았다. 주우러 가는 데 한참 걸렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'A', t:'방 — 둘러싼 것들',
    x:`방 한가운데에 섰다. 사방에서 뭔가 다가온다. 여럿이다. 천천히 원을 좁힌다.<br><br>
    투우사는 하나를 상대한다. 하나가 달려들 때 천을 빼면 된다. 여럿은 다르다. 천을 한쪽으로 빼면 다른 쪽이 온다.<br>
    원이 세 걸음까지 좁혀졌다. 문은 원 바깥이다.<br><br>
    천은 하나다.`,
    o:[
      { l:'① 무력을 실어 천을 크게 돌려 한꺼번에 흘린다.', k:'evade', dc:23, cost:{ might:30 },
        ok:`천을 머리 위로 올려 크게 돌렸다. 무력을 팔에 실었다. 천이 원을 그리며 넓게 펼쳐진다. 휘익.<br><br>사방에서 것들이 한꺼번에 달려들었다. 천 원을 따라. 천이 도는 쪽으로 다들 흘렀다. 원 바깥으로 밀려 나갔다. 서로 부딪쳤다.<br>그 틈에 빈 데로 빠져 문으로 갔다.<br><br>팔이 떨린다. 천이 무겁다. 천 끝에 손톱 자국이 원을 그리며 박혀 있다.`,
        ng:`돌리는데 하나가 천 끝을 잡았다.<br><br>천이 멈췄다. 원이 멈추자 사방에서 왔다. 천을 놓고 몸을 낮췄다. 머리 위로 손들이 지나갔다. 손들 밑으로 빠졌다.<br>문까지 기었다. 등을 손톱이 그었다. 천은 방 한가운데 떨어졌다. 다시 주웠다. 등이 피투성이다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-32, spirit:-18 } },
      { l:'② 벽까지 물러나 등을 대고 하나씩 상대한다.', k:'steady', dc:22,
        ok:`원을 뚫고 벽까지 물러났다. 등을 벽에 댔다. 이제 사방이 아니라 앞뿐이다.<br><br>것들이 앞으로 몰렸다. 한 번에 다 못 온다. 벽 앞이 좁다. 하나씩 온다. 하나 오면 천을 빼고, 하나 오면 빼고. 하나가 벽에 부딪히고, 다음 것이 그 위로 넘어졌다.<br>여섯을 흘렸다. 벽을 따라 옆걸음으로 문까지 갔다.<br><br>정면을 만드는 건 벽이다. 벽이 없으면 정면도 없다. 문을 나서며 벽에 한 번 손을 댔다.`,
        ng:`벽에 등을 댔는데 벽이 차가웠다. 벽에서도 손이 나왔다.<br><br>등 뒤에서 어깨를 잡았다. 앞의 것들이 동시에 왔다. 천을 휘둘렀다. 둘을 흘렸다. 셋째가 허리를 받았다. 숨이 빠졌다.<br>벽 손을 뿌리치고 문으로 굴렀다. 허리를 펼 수가 없다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } },
      { l:'③ 원을 이끄는 하나만 본다.', k:'gaze', dc:22,
        ok:`여럿을 다 보지 않았다. 하나만 봤다. 원을 이끄는 것. 다른 것들이 그것을 따라 걷는다. 그것이 멈추면 다 멈춘다.<br><br>그것 하나에게 천을 흔들었다. 그것이 왔다. 천을 뺐다. 그것이 원 바깥으로 지나가 벽에 부딪혔다. 다른 것들이 그것을 따라 몸을 돌렸다. 원이 풀렸다.<br>풀린 데로 빠져 문으로 갔다.<br><br>문 앞에서 돌아보니 것들이 벽에 부딪힌 것 둘레에 모였다. 일으켜 세운다. 다시 이쪽을 본다.`,
        ng:`하나를 골랐는데 골라 놓고 보니 다 똑같다. 누가 이끄는지 모르겠다.<br><br>고르는 사이 원이 한 걸음까지 좁혀졌다. 손이 사방에서 닿는다. 옷을 잡는다. 천을 휘두르며 몸을 비틀어 빠져나왔다. 옷이 찢겼다.<br>문까지 뛰었다. 몸 여기저기 손자국이다. 다 같은 크기다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } }
    ] },

  { at:'A', t:'통로 — 천을 쥐는 손',
    x:`좁은 통로다. 바닥 틈에서 손이 올라온다. 지나가는 것을 잡는다.<br><br>
    투우사는 천을 먼저 내민다. 손은 천을 잡는다. 천을 빼면 손이 빈손이 된다. 그게 버릇이다.<br>
    이 손은 천을 잡고 놓지 않는다. 잡은 것을 바닥 틈으로 끌고 들어간다. 앞서 누가 놓친 지팡이가 반쯤 틈에 박혀 있다.<br><br>
    천 끝이 이미 손에 잡혔다.`,
    o:[
      { l:'① 천을 놓는다.', k:'steady', dc:22,
        ok:`천을 놓았다. 손가락을 하나씩 폈다. 투우사가 천을 놓는다.<br><br>손이 천을 끌고 틈으로 들어간다. 사락사락. 천이 다 들어갔다. 손이 다시 올라오지 않는다. 배가 불렀다.<br>천 없이 통로를 지났다. 다른 손들도 안 올라왔다. 천 하나로 다들 배가 불렀다.<br><br>통로 끝 바닥 틈에서 천 끝이 한 뼘 삐져나와 있다. 거기까지만 먹었다. 당겼다. 나왔다. 반쯤 찢긴 채.`,
        ng:`놓으려는데 손가락이 안 펴졌다. 저쪽이 안 놓는 게 아니다. 이쪽이 못 놓는다.<br><br>천이 당겨진다. 손목이 바닥 쪽으로. 무릎이 꺾였다. 일행이 이쪽 손가락을 하나씩 폈다. 천이 틈으로 들어갔다.<br>천 없이 통로를 지났다. 손가락 마디가 다 뻣뻣하다. 손이 천을 쥔 모양으로 굳었다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-22 } },
      { l:'② 천을 쥔 채 비틀어 손을 꺾는다.', k:'evade', dc:23,
        doom:{ title:'쥔 천', what:'천째 바닥 틈으로 끌려 들어갑니다', dc:18, sec:45,
          text:`천을 쥔 채 비틀었다. 소가 천을 물었을 때 하는 대로. 비틀면 놓는다.<br><br>손이 안 놓았다. 같이 비틀었다. 반대로. 천이 손목에 감겼다. 감긴 채 당긴다. 바닥 쪽으로. 무릎이 바닥에 닿았다. 팔꿈치가 틈에 들어갔다.<br>틈은 좁다. 팔이 들어간다. 어깨가 걸렸다. 손이 당긴다. 천과 함께 끌려 들어간다.<br><br>일행이 허리를 잡았다. 천이 팽팽하다. 천이 찢어지든지 이쪽이 들어가든지.`,
          dieText:`투우사는 천을 놓지 않는다. 그게 투우사다. 그래서였다.<br><br>통로 바닥 틈에 회색 천 끝이 한 뼘 삐져나와 있다.<br>당기면 아직 따뜻하다.` },
        ok:`천을 쥔 채 비틀되 이쪽으로가 아니라 손 쪽으로 밀어 넣었다. 손이 잡은 천을 손 안으로 더 깊이.<br><br>손이 당황했다. 당기는데 천이 밀려 들어온다. 쥘 데가 없다. 천을 뭉쳐 쥔 채 멈칫했다. 그 틈에 천을 단번에 뺐다. 손이 뭉친 천 모양 그대로 빈 데를 쥐었다.<br>천을 걷고 통로를 지났다.<br><br>천에 손가락 주름이 다섯. 털어도 안 펴진다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'A', t:'계단참 — 인사하는 것',
    x:`계단참에 뭔가 서 있다. 키가 크다. 이쪽을 보더니 허리를 깊이 숙였다. 인사다.<br><br>
    숙인 등이 길다. 등뼈 마디가 옷 밖으로 드러난다. 숙인 채 이쪽을 본다. 고개를 숙이고 올려다보는 눈.<br>
    투우사는 안다. 들이받는 것들은 들이받기 전에 머리를 숙인다.<br><br>
    그것이 조금 더 숙였다.`,
    o:[
      { l:'① 인사를 받지 않고 정면에 서서 천을 든다.', k:'steady', dc:22, wake:1,
        ok:`계단참 정면에 섰다. 천을 펼쳤다. 인사를 받지 않았다. 숙인 머리를 봤다.<br><br>그것이 왔다. 숙인 채로. 머리부터. 마지막 한 뼘에 천을 뺐다. 그것이 천을 따라 계단 밑으로 지나갔다. 굴렀다. 계단 아래에서 일어섰다. 허리를 펴더니 위를 보고 다시 숙였다. 이번에는 작게.<br>계단을 올라 지났다.<br><br>그 인사가 무엇인지 알았다. 들이받기 전 인사다. 투우사도 끝나면 인사를 한다. 서로 같은 걸 안다. 상대의 예를 읽으면 다음 수가 보인다. 숙이는 깊이만큼 온다.`,
        ng:`정면에 섰는데 그것이 안 왔다. 숙인 채 기다린다. 이쪽도 숙이기를.<br><br>오래 기다렸다. 다리가 굳었다. 고개가 저절로 내려갔다. 숙이는 순간 그것이 왔다. 천을 빼기에 늦었다. 어깨에 머리가 박혔다. 계단 밑으로 굴렀다.<br>일어나 보니 그것이 계단참에서 허리를 펴고 있다. 만족한 듯. 어깨가 빠졌다 들어갔다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, spirit:-18 } },
      { l:'② 같이 허리를 숙여 인사를 받아 준다.', k:'bond', dc:23,
        ok:`이쪽도 허리를 숙였다. 깊이. 그것보다 조금 덜.<br><br>그것이 멈칫했다. 숙인 채 기다린다. 이쪽도 숙인 채 기다렸다. 먼저 펴는 쪽이 지는 것 같다. 숨을 고르게 쉬었다. 그것이 먼저 폈다. 길게. 천장까지.<br>그것이 옆으로 비켜 섰다. 계단을 내준다.<br><br>지나가며 한 번 더 숙였다. 그것도 숙였다. 등 뒤에서 그것이 계속 숙이고 있다. 다음 사람에게.`,
        ng:`숙였는데 너무 깊이 숙였다. 그것보다 더.<br><br>그것이 웃는 소리를 냈다. 숙인 뒷덜미에 손이 얹혔다. 누른다. 더 숙이라고. 무릎이 꺾였다. 이마가 계단에 닿았다. 일행이 이쪽을 끌어당겼다.<br>뒷덜미에 손 모양 멍이 들었다. 고개를 들 때마다 누르는 느낌이 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-20, spirit:-24 } }
    ] },

  { at:'A', t:'복도 끝 — 마지막 한 뼘',
    x:`복도 끝에서 큰 것이 이쪽을 본다. 복도가 그것으로 꽉 찬다.<br><br>
    그것이 땅을 긁는다. 바닥이 운다. 이쪽 뒤에는 일행이 있다. 일행 뒤에는 벽이다.<br>
    투우사는 마지막 한 뼘까지 기다린다. 그 한 뼘이 투우사의 전부다. 오늘은 그 한 뼘 뒤에 일행이 있다.<br><br>
    천을 펼쳤다. 회색 천이 복도 폭만큼 넓지는 않다.`,
    o:[
      { l:'① 일행을 벽에 붙이고 천을 복도 가운데에 둔다.', k:'evade', dc:23, wake:1,
        ok:`일행을 한쪽 벽에 붙였다. 이쪽은 반대쪽 벽에 붙어 천만 복도 가운데로 내밀었다.<br><br>그것이 달렸다. 바닥이 흔들린다. 천을 본다. 천을 향해. 마지막 한 뼘. 천을 뺐다. 그것이 천이 있던 가운데를 지나쳤다. 일행 옆을, 이쪽 옆을. 벽에 박혔다.<br>복도가 조용해졌다. 일행이 숨을 쉰다.<br><br>천을 빼는 쪽으로 상대가 오는 줄 알았다. 아니다. 천이 있던 자리로 온다. 그 자리는 이쪽이 정한다. 천 하나로 복도를 둘로 갈랐다. 이쪽이 아닌 데로 상대를 보내는 법이다.`,
        ng:`마지막 한 뼘이 생각보다 짧았다. 그것이 컸다.<br><br>천을 뺐는데 그것 어깨가 천을 따라오며 이쪽을 쳤다. 벽에 부딪혔다. 그것은 지나갔다. 일행은 무사하다.<br>이쪽만 벽에 붙어 미끄러져 내렸다. 갈비가 몇 개 나갔는지 모른다. 천이 그것 어깨에 걸려 같이 갔다.`,
        win:{ exp:25, dream:3 }, lose:{ hp:-34, mind:-16 } },
      { l:'② 무력을 실어 머리를 받아 옆으로 흘린다.', k:'steady', dc:22, cost:{ might:32 },
        ok:`천을 버리고 두 팔로 받았다. 무력을 다 실었다. 머리가 팔에 닿는 순간 옆으로 밀었다. 뿔을 잡고 돌리듯.<br><br>그것이 옆으로 흘렀다. 벽에 머리를 박았다. 벽이 무너졌다. 그 너머가 다른 방이다. 그것이 그 방으로 굴러 들어갔다.<br>팔이 저리다. 손바닥이 다 갈렸다. 일행이 뛰어나와 이쪽을 부축했다.<br><br>무너진 벽 너머에서 그것이 일어선다. 이쪽을 안 본다. 다른 데를 보고 땅을 긁는다.`,
        ng:`받았는데 너무 무거웠다.<br><br>밀려서 일행 쪽으로 미끄러졌다. 일행을 등으로 막았다. 그것이 가슴을 밀었다. 숨이 다 빠졌다. 그것이 멈췄다. 일행 앞 한 뼘에서.<br>그것이 물러났다. 다른 데로 갔다. 이쪽은 쓰러져 한참 숨을 못 쉬었다. 가슴에 그것의 이마 자국이 남았다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-36, mind:-18 } }
    ] },

  { at:'A1', t:'로비 — 안아 주러 오는 방글이',
    x:`로비 한가운데에 방글이 인형탈이 서 있다. 노란 해 얼굴. 그려 넣은 입이 얼굴보다 길다.<br><br>
    하얀 장갑을 활짝 폈다. 팔을 벌렸다. 안아 주려는 자세다. 그리고 달려온다. 뒤뚱뒤뚱. 빠르다.<br>
    안긴 사람은 탈 안으로 들어간다고 했다. 로비 텔레비전 속에서 안긴 아이가 웃는다. 그려 넣은 입으로.<br><br>
    투우사는 달려드는 것을 안다. 품을 벌리고 오는 것도 달려드는 것이다.`,
    o:[
      { l:'① 천을 펼쳐 벌린 품이 천을 안게 한다.', k:'evade', dc:22, wake:1,
        ok:`천을 넓게 펼쳐 몸 앞에 들었다. 방글이가 달려온다. 팔을 벌리고.<br><br>마지막 한 뼘. 천을 옆으로 빼며 놓았다. 방글이가 천을 안았다. 꽉. 천을 안은 채 지나갔다. 진열장에 부딪혔다. 유리가 깨졌다. 방글이는 천을 놓지 않는다. 안은 채 다정하게 흔든다.<br>그 틈에 계단으로 갔다.<br><br>천을 빼는 게 아니라 천을 안겼다. 상대가 원하는 것을 천에 실어 주면 상대는 그걸 갖고 멈춘다. 천을 내주는 것도 비키는 일이다. 계단에서 돌아보니 방글이가 천을 쓰다듬고 있다. 나중에 찾으러 가야 한다.`,
        ng:`천을 펼쳤는데 방글이가 천을 안 봤다. 이쪽을 봤다.<br><br>장갑 팔이 천을 넘어 어깨를 안았다. 탈 안 냄새. 좀약과 분. 지퍼 소리가 등 뒤에서 난다. 지익. 팔을 비틀어 빠져나왔다. 장갑 손가락 넷이 등을 쓸었다.<br>계단으로 뛰었다. 등이 따뜻하다. 털이 붙었다. 한참 떼어 냈다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
      { l:'② 무력을 실어 달려오는 탈 옆구리를 밀어 흘린다.', k:'steady', dc:22, cost:{ might:28 },
        ok:`달려오는 방글이 옆으로 반 걸음 비키며 옆구리를 두 손으로 밀었다. 무력을 실어. 달리는 쪽 그대로 더 밀었다.<br><br>방글이가 제 힘에 이쪽 힘까지 실려 로비를 가로질러 미끄러졌다. 접수처 책상을 넘어 넘어졌다. 머리가 벗겨질 듯 흔들린다.<br>일어나지 못하고 버둥거린다. 그 틈에 계단으로 갔다.<br><br>계단에서 보니 방글이 머리가 반쯤 돌아갔다. 목 틈으로 안이 보인다. 안에 누가 있다. 작다. 이쪽을 본다.`,
        ng:`옆구리를 밀었는데 탈이 물렁했다. 손이 파묻혔다.<br><br>탈 속에서 무엇이 이쪽 손을 잡았다. 작은 손이다. 뽑아냈다. 방글이가 돌아섰다. 팔을 다시 벌린다.<br>계단으로 뛰었다. 손바닥에 탈 안감 실밥이 붙었다. 작은 손 온도가 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-18 } },
      { l:'③ 기념품 진열장 뒤로 몸을 던진다.', k:'hide', dc:22,
        ok:`진열장 뒤로 몸을 던졌다. 방글이가 진열장 앞을 지나갔다. 팔을 벌린 채. 안을 것이 없다.<br><br>멈췄다. 돌아본다. 진열장 유리 너머로 이쪽이 보인다. 유리 안에 작은 방글이 인형들이 줄지어 있다. 다 팔을 벌렸다. 큰 방글이가 진열장 앞에 섰다.<br>진열장을 사이에 두고 돌았다. 방글이가 따라 돈다. 한 바퀴. 계단 쪽에서 멈춰 빠져나갔다.<br><br>진열장 속 작은 인형 하나가 팔을 내렸다. 이쪽이 뛰어간 쪽을 가리킨다.`,
        ng:`숨었는데 진열장이 흔들렸다. 유리가 쏟아졌다.<br><br>작은 방글이 인형들이 이쪽 위로 쏟아졌다. 다 팔을 벌리고. 작은 팔들이 옷을 잡는다. 털어 냈다. 유리 조각에 손등을 베었다.<br>큰 방글이가 진열장을 넘어왔다. 계단까지 뛰었다. 작은 인형 하나가 옷깃에 매달려 따라왔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
    ] },

  { at:'A1', t:'방청석 — 맨 앞줄',
    x:`방청석 맨 앞줄이다. 무대 바로 앞이다. 의자 밑에서 하얀 장갑들이 올라온다. 손바닥을 위로.<br><br>
    맨 앞줄에 걸린 것은 무대로 올려진다. 손에서 손으로. 맨 앞줄을 따라 걸어야 무대 옆 문으로 간다.<br>
    스피커에서 박수가 터진다. 박수가 커질 때마다 장갑들이 한꺼번에 손을 뻗는다. 달려드는 것과 같다. 박자가 있다.<br><br>
    투우사는 박자를 안다.`,
    o:[
      { l:'① 박수 박자에 천을 흔들어 장갑들을 천으로 모은다.', k:'evade', dc:22,
        ok:`천을 맨 앞줄 위로 펼쳐 흔들었다. 박수가 커졌다. 장갑들이 한꺼번에 뻗었다. 천 쪽으로. 천을 뺐다. 장갑들이 빈 데를 쥐었다.<br><br>박수가 잦아들면 걸었다. 커지면 천을 흔들었다. 장갑들이 천만 쫓는다. 맨 앞줄 끝까지 갔다.<br>무대 옆 문을 열었다.<br><br>천을 거두니 장갑 털이 하얗게 붙었다. 천이 조금 하얘졌다. 회색보다 밝다.`,
        ng:`박수가 박자를 바꿨다. 크게, 작게, 다시 크게.<br><br>천을 늦게 흔들었다. 장갑들이 천 대신 소매를 잡았다. 들어 올린다. 무대 쪽으로. 의자 등받이를 붙잡았다. 장갑들이 손가락을 하나씩 편다.<br>천으로 장갑들을 쳐 냈다. 빠져나왔다. 손가락 셋이 젖혀졌다. 무대 옆 문까지 기었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-20 } },
      { l:'② 무대를 정면에 두고 옆걸음으로 지난다.', k:'steady', dc:23,
        doom:{ title:'맨 앞줄', what:'손에서 손으로 실려 무대로 갑니다', dc:18, sec:50,
          text:`무대를 등지지 않으려고 무대를 보며 옆걸음했다. 맨 앞줄 의자들이 이쪽 등 뒤가 됐다.<br><br>박수가 터졌다. 등 뒤에서 장갑들이 뻗었다. 등을, 허리를, 다리를 받친다. 발이 바닥에서 뜬다. 손에서 손으로 실려 간다. 무대 쪽으로. 정면에 있던 무대가 가까워진다.<br>무대를 보고 있었다. 무대가 이쪽을 받는다.<br><br>스피커가 반긴다. 맨 앞줄 친구가 나왔어요!`,
          dieText:`정면을 지켰다. 정면이 무대였다.<br><br>그날 오늘의 친구는 무대 위에서 한 번도 등을 보이지 않았다.<br>카메라를 보고 끝까지 웃었다. 그려 넣은 입으로.` },
        ok:`정면을 하나 정했다. 무대가 아니라 맨 앞줄. 장갑들을 보며 옆걸음했다. 무대를 등졌다.<br><br>무대는 달려들지 않는다. 장갑이 달려든다. 달려드는 쪽을 정면에 뒀다. 박수가 터질 때마다 장갑들이 뻗었다. 이쪽은 손끝 한 뼘 앞에서 물러섰다.<br>무대 옆 문에 닿았다.<br><br>문을 닫기 전에 무대를 봤다. 무대 위에서 인형탈 셋이 내내 이쪽 등을 보고 있었다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 천을 머리에 덮어쓰고 낮게 지난다.', k:'hide', dc:22,
        ok:`천을 머리에 덮어썼다. 쪼그려 앉은 높이로 맨 앞줄 의자 앞을 지났다.<br><br>장갑들이 머리 덮은 천을 본다. 천은 방청객이 아니다. 무대 소품이다. 소품은 올리지 않는다. 장갑들이 천을 쓰다듬고 지나간다.<br>무대 옆 문까지 갔다. 천을 벗었다.<br><br>천 안쪽에 손바닥 자국이 여럿 찍혀 있다. 바깥에서 쓰다듬은 손이 안쪽까지 배어 들었다.`,
        ng:`천을 덮었는데 천 밑으로 신발이 보였다.<br><br>장갑 하나가 신발을 잡았다. 방청객이다. 당긴다. 천이 벗겨졌다. 맨 앞줄에 얼굴이 드러났다. 박수가 터졌다. 장갑들이 한꺼번에.<br>천을 휘둘러 장갑들을 쳐 내고 문으로 굴렀다. 발목이 꺾였다. 신발 한 짝이 장갑에 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
    ] },

  { at:'A1', t:'무대 옆 — 출연 줄',
    x:`무대 옆 대기 공간에 인형탈들이 줄을 섰다. 방글이 둘, 뭉치, 삐뚤이. 무대를 향해 섰다. 등 지퍼가 닫혔다. 안에 뭔가 있다.<br><br>
    스피커가 센다. 십. 구. 영에 커튼이 열리면 줄이 무대로 달려 나간다. 줄 앞에 선 것은 같이 휩쓸려 나간다.<br>
    직원 문은 줄 맞은편이다. 줄과 커튼 사이를 지나야 한다.<br><br>
    투우사는 달려 나오는 줄 앞에 서 본 적은 없다.`,
    o:[
      { l:'① 줄 앞에 서서 천으로 하나씩 흘린다.', k:'evade', dc:23,
        doom:{ title:'출연 줄', what:'인형탈 줄에 휩쓸려 무대로 끌려 나갑니다', dc:18, sec:45,
          text:`줄 앞에 서서 천을 펼쳤다. 삼. 이. 일. 영. 커튼이 열렸다. 노란 빛.<br><br>줄이 달려 나왔다. 첫 방글이가 천을 쳤다. 뺐다. 지나갔다. 뭉치가 천을 쳤다. 뺐다. 지나갔다. 삐뚤이가 왔다. 목이 길다. 천 위로 목이 넘어왔다. 부리가 옷깃을 물었다.<br>끌려간다. 줄 사이에 끼었다. 앞뒤로 탈이다. 털, 깃털. 발이 탈 걸음에 맞춰진다. 무대로 끌려 나간다. 박수가 쏟아진다.<br><br>마지막 방글이의 지퍼가 이쪽 등에 닿는다. 열려 있다.`,
          dieText:`달려드는 것은 천을 본다. 목이 긴 것은 천 너머를 본다.<br><br>그날 출연한 인형탈은 다섯이었다.<br>다섯째는 춤이 서툴렀다. 그 대신 한 번도 등을 보이지 않았다.` },
        ok:`줄 앞에서 천을 펼치되 높이 들었다. 삐뚤이 목 높이까지.<br><br>영. 커튼이 열렸다. 줄이 달려 나왔다. 방글이가 천을 쳤다. 뺐다. 뭉치. 뺐다. 삐뚤이 목이 천을 넘어오려다 높은 천에 부리가 걸렸다. 부리가 천을 물었다. 천을 놓았다. 삐뚤이가 천을 문 채 무대로 나갔다.<br>줄이 다 지나갔다. 직원 문으로 갔다.<br><br>문틈으로 무대를 봤다. 삐뚤이가 회색 천을 흔들며 춤춘다. 박수가 쏟아진다. 천을 되찾으려면 무대에 올라가야 한다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 검은 커튼 주름 속으로 몸을 밀어 넣는다.', k:'hide', dc:22,
        ok:`검은 커튼 주름 속으로 몸을 밀어 넣었다. 커튼이 이쪽을 감쌌다. 먼지 냄새.<br><br>영. 커튼이 열렸다. 이쪽이 감긴 자락은 안 열렸다. 줄이 앞으로 지나갔다. 털이 커튼을 쓸었다. 탈 하나가 멈췄다. 커튼을 한 번 만졌다. 그리고 무대로 나갔다.<br>박수가 쏟아지는 사이 직원 문으로 갔다.<br><br>문 앞에서 돌아보니 이쪽이 감겼던 자락에 사람 모양 주름이 남았다. 아직 따뜻하다.`,
        ng:`주름에 숨었는데 영에 커튼이 통째로 걷혔다.<br><br>노란 빛 속에 이쪽이 드러났다. 줄 맨 앞이다. 탈들이 이쪽을 밀고 나간다. 무대 쪽으로. 각목 기둥을 끌어안았다. 탈들이 기둥 양옆으로 지나갔다. 어깨를 치고.<br>줄이 다 지나간 뒤 기둥에서 떨어졌다. 양 어깨가 퍼렇게 멍들었다. 무대에서 박수가 났다. 이쪽 몫이 빠진 박수.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
    ] },

  { at:'A1', t:'분장실 — 가발 머리',
    x:`분장실 선반에 가발 머리가 줄지어 놓였다. 얼굴 없는 하얀 머리통에 가발을 씌웠다. 스무 개.<br><br>
    이쪽이 지나가면 머리들이 돈다. 얼굴 없는 앞쪽이 이쪽을 따라온다. 등을 보이면 선반에서 떨어져 굴러온다. 굴러온 머리는 발목에 붙는다. 바닥에 그런 머리가 둘 있다. 신발 한 짝씩 물고 있다.<br>
    투우사는 등을 안 보인다. 스무 개를 다 정면에 두기는 어렵다.<br><br>
    선반은 양쪽 벽에 있다.`,
    o:[
      { l:'① 몸을 옆으로 돌려 양쪽 선반을 다 정면에 두고 지난다.', k:'steady', dc:22, wake:1,
        ok:`몸을 옆으로 돌렸다. 한쪽 어깨는 왼쪽 선반, 다른 쪽 어깨는 오른쪽 선반. 눈은 양쪽 끝을 번갈아 봤다. 등은 문 쪽이다.<br><br>옆걸음으로 지났다. 머리들이 돈다. 따라온다. 다 이쪽 앞이나 옆이다. 등 뒤에는 문뿐이다. 하나도 안 떨어졌다.<br>문에 닿았다. 등으로 문을 밀었다.<br><br>정면은 하나라고 생각했다. 몸을 비틀면 정면이 둘이 된다. 눈이 닿는 데가 다 정면이다. 등을 좁히는 법을 알았다. 뒤가 줄면 앞이 넓어진다.`,
        ng:`옆걸음 중간에 왼쪽 끝 머리 하나를 놓쳤다. 눈을 안 준 사이.<br><br>그 머리가 선반에서 떨어졌다. 굴러와 발목에 붙었다. 이빨이 없는데 문다. 차다. 떼어 냈다. 손에 가발 머리카락이 감겼다.<br>문을 나와 발목을 보니 동그란 자국이 났다. 이가 없는 입 자국이다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-22 } },
      { l:'② 무력을 실어 천으로 한쪽 선반을 통째로 덮어 누른다.', k:'fix', dc:22, cost:{ might:28 },
        ok:`천을 넓게 펼쳐 오른쪽 선반에 덮었다. 무력을 실어 천 끝을 선반 밑에 쑤셔 넣어 고정했다. 머리 열 개가 천 밑에 갇혔다.<br><br>천 밑에서 머리들이 돈다. 천이 들썩인다. 못 나온다. 남은 왼쪽 열 개만 정면에 두고 지났다.<br>문 앞에서 천을 걷으러 돌아갔다. 천 밑에서 머리 하나가 천을 물고 있다.<br><br>당겼다. 머리가 딸려 왔다. 떼어 냈다. 천에 가발 머리카락이 엉겼다. 천이 회색보다 조금 검다.`,
        ng:`천을 덮는데 왼쪽 선반에 등을 보였다.<br><br>왼쪽 머리 셋이 떨어졌다. 굴러와 종아리에 붙었다. 천을 놓고 떼어 냈다. 하나는 안 떨어진다. 일행이 같이 잡아 뜯었다.<br>천은 오른쪽 선반에 덮인 채 남았다. 걷으러 갈 엄두가 안 났다. 종아리가 얼얼하다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'A1', t:'동산 세트 — 삐뚤이의 목',
    x:`동산 세트 가장자리에 삐뚤이가 서 있다. 파란 깃털. 목이 길다. 끝에 노란 부리.<br><br>
    목이 위로 펴졌다가 내리찍는다. 바닥 문 위에 선 것을 쫀다. 쪼인 것은 부리에 물려 위로 들린다. 세트 위 천장 쪽으로.<br>
    세트를 건너야 한다. 내리찍는 목은 투우사가 아는 것이다. 위에서 오는 들이받기.<br><br>
    목이 펴진다. 높이. 이쪽을 본다.`,
    o:[
      { l:'① 천을 머리 위에 들고 부리가 찍는 순간 뺀다.', k:'evade', dc:23, wake:1,
        ok:`천을 머리 위로 들었다. 위에서 오는 것에는 위에 천을 둔다. 목이 펴졌다. 멈췄다. 내리찍었다.<br><br>마지막 한 뼘. 천을 옆으로 뺐다. 부리가 천을 따라 옆으로 꺾이며 바닥을 찍었다. 판자가 깨졌다. 부리가 판자에 박혔다. 목이 버둥거린다.<br>그 옆을 건넜다.<br><br>앞에서 오는 것만 비켰다. 위에서 오는 것도 같다. 오는 쪽에 천을 들면 된다. 천 드는 높이를 바꾸자 정면이 위로 올라갔다. 정면은 방향이 아니라 상대가 오는 쪽이다.`,
        ng:`천을 머리 위로 들었는데 부리가 천을 뚫고 왔다.<br><br>천에 구멍이 났다. 부리가 어깨를 쪼았다. 옷과 살이 같이 집혔다. 들린다. 발이 바닥에서 떴다. 몸을 비틀었다. 살이 찢기며 떨어졌다.<br>세트를 굴러 건넜다. 어깨에서 피가 계속 난다. 천에 부리 구멍이 났다. 손가락 셋이 들어간다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, spirit:-18 } },
      { l:'② 무력을 실어 천으로 목을 감아 끌어내린다.', k:'break', dc:23, cost:{ might:30 },
        doom:{ title:'삐뚤이의 목', what:'삐뚤이 목에 감겨 천장 쪽으로 끌려 올라갑니다', dc:18, sec:50,
          text:`목이 내리찍을 때 천으로 목을 감았다. 무력을 실어 끌어내렸다. 부리가 바닥에 닿았다.<br><br>목이 다시 펴졌다. 천을 감은 채. 천 끝을 쥔 이쪽도 같이 들렸다. 발이 바닥에서 떴다. 놓으려 했다. 목이 천을 감아 이쪽 손목까지 감았다.<br>위로 끌려 올라간다. 세트 위 천장 쪽으로. 조명 다리가 가까워진다. 아래 세트가 작아진다. 목이 접히며 부리가 이쪽을 향한다.<br><br>밑에서 일행이 천 끝을 잡으려 뛴다. 손이 닿을락 말락 한다.`,
          dieText:`위에서 오는 것을 끌어내리면 위로 끌려간다. 무게가 같으면.<br><br>그날 동산 세트 하늘에 해가 둘 떴다. 하나는 그려 넣은 해.<br>하나는 회색이었다.` },
        ok:`목을 감되 천 끝을 쥐지 않고 바닥 문 손잡이에 걸었다. 무력을 실어 매듭을 지었다.<br><br>목이 펴졌다. 천에 걸려 반쯤 펴지다 멈췄다. 바닥 문 손잡이가 버틴다. 삐뚤이가 목을 흔든다. 천이 팽팽하다. 목이 묶였다.<br>그 옆을 건넜다. 부리가 닿지 않는 거리다.<br><br>건너편에서 돌아봤다. 바닥 문이 열렸다. 문 밑에서 장갑들이 매듭을 풀고 있다. 친절하게. 다 풀면 목이 펴질 것이다.`,
        win:{ exp:24, dream:3 } },
      { l:'③ 부리가 찍는 박자에 맞춰 일행을 한 명씩 보낸다.', k:'fix', dc:22,
        ok:`목이 펴지고, 멈추고, 찍는 박자를 셌다. 찍은 다음 다시 펴기까지 셋. 그 셋 동안 한 명.<br><br>일행을 하나씩 보냈다. 이쪽은 천을 흔들어 목을 이쪽으로 끌었다. 목이 이쪽을 찍는다. 이쪽이 비킨다. 그 셋에 한 사람이 건넌다.<br>다 건너갔다. 마지막에 이쪽이 건넜다. 천을 뒤로 던져 두고.<br><br>삐뚤이가 천을 찍었다. 물고 위로 들었다. 천장 쪽으로. 천이 높이 걸렸다. 깃발처럼.`,
        ng:`셋째 사람을 보낼 때 박자가 둘이었다. 목이 빨라졌다.<br><br>부리가 그 사람을 향해 찍었다. 이쪽이 몸으로 밀쳤다. 부리가 이쪽 등을 쪼았다. 옷이 들렸다. 옷을 찢고 떨어졌다.<br>둘이 같이 굴러 건넜다. 등에 부리 자국이 깊다. 옷 조각이 천장 쪽에서 흔들린다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } }
    ] },

  { at:'A2', t:'세탁실 — 젖은 교복',
    x:`세탁실 빨랫줄에 교복이 줄줄이 걸렸다. 젖었다. 마르지 않는다. 물이 가슴까지 찬 방에서.<br><br>
    교복이 흔들린다. 바람이 없다. 소매가 이쪽으로 뻗는다. 지나가는 것의 팔을 잡는다. 잡힌 것은 빨랫줄에 같이 걸린다. 빨랫줄 끝에 사복 한 벌이 걸려 있다. 어른 옷이다.<br>
    투우사는 뻗는 것을 천으로 받는다. 소매도 뻗는 것이다.<br><br>
    빨랫줄 사이로 지나가야 한다.`,
    o:[
      { l:'① 천을 앞세워 소매가 천을 잡게 하며 지난다.', k:'evade', dc:22,
        ok:`천을 펼쳐 몸 옆에 들었다. 첫 교복 소매가 뻗었다. 천을 잡았다. 천을 뺐다. 소매가 빈 데를 쥐었다.<br><br>둘째, 셋째. 소매가 천을 잡을 때마다 뺐다. 천이 젖는다. 무거워진다. 무거운 천은 늦게 돈다. 크게 돌렸다. 크게 돌리면 늦어도 넓다.<br>빨랫줄을 다 지났다.<br><br>천이 물을 잔뜩 먹었다. 짰다. 물이 나온다. 회색 물이 아니다. 교복 남색 물이다.`,
        ng:`젖은 천이 너무 무거웠다. 반 박자 늦게 돌았다.<br><br>소매 둘이 팔을 잡았다. 팔이 빨랫줄 쪽으로 들렸다. 집게가 소매를 문다. 이쪽 소매다. 팔을 비틀었다. 옷소매가 찢겼다.<br>나머지는 뛰어서 지났다. 팔에 소매 자국이 감겼다. 빨랫줄에 이쪽 옷 조각이 걸려 마르지 않는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-24 } },
      { l:'② 물속으로 턱까지 몸을 낮춰 지난다.', k:'hide', dc:23,
        ok:`물속으로 몸을 낮췄다. 턱까지. 교복은 물 위에 걸렸다. 소매는 물 위를 뻗는다.<br><br>물속으로 지났다. 머리 위로 소매들이 지나간다. 머리카락을 스친다. 머리카락은 안 잡는다. 팔을 찾는다.<br>빨랫줄 끝 사복 밑을 지날 때 바짓단에서 물이 떨어졌다. 이쪽 이마에. 따뜻하다.<br><br>세탁실을 나왔다. 사복 주머니에서 열쇠 하나가 물에 떨어지는 소리가 났다. 줍지 않았다.`,
        ng:`물속에서 교복 치맛단이 내려왔다. 물에 잠긴 치맛단.<br><br>치맛단이 얼굴을 덮었다. 젖은 천이 코와 입에 붙는다. 숨이 막힌다. 천 너머에서 무릎이 이마를 짚었다. 누른다. 물속으로.<br>천을 걷어 내고 일어섰다. 기침이 멎지 않는다. 물을 많이 먹었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
    ] },

  { at:'A2', t:'중앙 계단 — 쏟아지는 물',
    x:`본관 중앙 계단 위에서 소리가 난다. 물이다. 위층 어딘가가 터졌다. 물이 계단을 타고 쏟아져 내려온다.<br><br>
    물머리가 하얗다. 그 안에 뭔가 섞였다. 책상, 의자, 손.<br>
    투우사는 달려드는 것을 안다. 물도 달려든다. 똑바로 오고, 마지막에 못 꺾는다.<br><br>
    천을 펼쳤다. 물은 천을 보지 않는다.`,
    o:[
      { l:'① 물머리에 천을 비스듬히 대어 가르며 비킨다.', k:'evade', dc:23, wake:1,
        ok:`계단 난간 옆에 섰다. 천을 비스듬히 들었다. 물을 막지 않고 물이 미끄러질 각으로.<br><br>물머리가 왔다. 천에 닿았다. 천이 물을 반대편 난간 쪽으로 흘렸다. 그 틈에 몸을 난간에 붙였다. 물이 옆으로 지나간다. 물속의 손들이 이쪽으로 뻗다가 천 각을 따라 흘러간다.<br>물이 다 지나갔다. 무릎까지만 젖었다.<br><br>천은 보는 것만 흘린다고 알았다. 눈 없는 것도 흘린다. 천이 길을 만들면 오는 것은 그 길로 간다. 보든 말든. 천 각 하나가 물길이 됐다.`,
        ng:`천을 댔는데 물이 천째 이쪽을 덮었다.<br><br>계단을 같이 굴러 내려갔다. 물속 손들이 팔다리를 잡는다. 같이 가자고. 난간을 붙잡았다. 손들이 놓고 물을 따라 내려갔다.<br>계단에 걸려 숨을 몰아쉬었다. 온몸이 멍이다. 천은 손에 감겨 있다. 놓지 않은 게 다행이다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, spirit:-18 } },
      { l:'② 천으로 몸을 난간에 묶고 버틴다.', k:'steady', dc:22,
        ok:`천으로 몸을 난간에 묶었다. 천 끝을 기둥에 두 번 감아 매듭을 지었다.<br><br>물머리가 덮쳤다. 숨을 참았다. 물이 이쪽을 끌어간다. 천이 버틴다. 난간이 버틴다. 물속 손이 발목을 당긴다. 같이 가자고. 천이 안 놓았다.<br>물이 지나갔다. 숨을 터뜨렸다.<br><br>매듭을 풀었다. 천이 늘어났다. 물살이 그만큼 세게 당겼다. 회색 천에 손 자국이 하나 남았다. 발목을 잡던 그 손이 천도 잡았다.`,
        ng:`매듭이 덜 감겼다. 물이 덮치자 천이 풀렸다.<br><br>몸이 물살에 실려 계단 밑으로 쓸려 갔다. 계단참 벽에 부딪혀 멈췄다. 물속 손들이 이쪽을 계단참 구석에 밀어 넣는다. 거기 앉으라고.<br>물이 빠진 뒤 기어 나왔다. 머리가 깨졌다. 천은 계단참 구석에 걸려 있다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-18 } },
      { l:'③ 무력을 실어 교실 문짝을 뜯어 계단에 세운다.', k:'steady', dc:22, cost:{ might:30 },
        ok:`계단 옆 교실 문짝을 잡았다. 무력을 다 실어 경첩째 뜯었다. 문짝을 계단에 비스듬히 세우고 등으로 받쳤다.<br><br>물이 문짝에 부딪쳤다. 양옆으로 갈라진다. 문짝 뒤는 조용하다. 물속 의자가 문짝을 쳤다. 손이 문짝 가장자리를 잡았다. 등을 더 붙였다.<br>물이 다 지나갔다. 문짝을 내려놨다.<br><br>문짝에 교실 번호가 붙어 있다. 3학년 2반. 안쪽에 낙서. 17번 바보. 그 밑에 누가 지운 자국. 그 밑에 새 글씨. 고마워.`,
        ng:`뜯는데 경첩 하나가 안 빠졌다. 문짝이 반만 섰다.<br><br>물이 반쪽으로 들이쳤다. 문짝째 밀렸다. 문짝과 벽 사이에 끼었다. 가슴이 눌렸다. 물이 빠질 때까지 숨을 못 쉬었다.<br>문짝을 밀어내고 나왔다. 갈비가 결린다. 문짝 안쪽에 손바닥 자국이 여럿 찍혔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-16 } }
    ] },

  { at:'A2', t:'수영장 — 돌아오는 물살',
    x:`수영장 레인을 따라 물살이 오간다. 끝에 닿으면 돌아온다.<br><br>
    레인 하나 끝, 출발대 위에 이쪽이 서 있다. 이쪽 레인 물살이 돌아온다. 똑바로. 빠르다. 물 위로 하얗게 머리를 들었다.<br>
    투우사가 아는 것이다. 똑바로 오는 것. 다만 이것은 물이라 천을 안 본다. 출발대 위에 선 것을 본다.<br><br>
    물살이 반쯤 왔다.`,
    o:[
      { l:'① 마지막 한 뼘까지 기다렸다가 출발대에서 비켜 내린다.', k:'evade', dc:23,
        doom:{ title:'돌아온 물살', what:'물살에 감겨 레인 끝으로 끌려갑니다', dc:18, sec:45,
          text:`기다렸다. 마지막 한 뼘까지. 투우사처럼.<br><br>물살이 출발대에 닿기 직전 옆으로 뛰어 내렸다. 옆 레인 물로. 비켰다. 그런데 옆 레인 물살도 돌아오고 있었다. 이쪽이 내린 데로.<br>물살이 이쪽을 감았다. 같이 돌자고. 몸이 실려 레인 끝으로 끌려간다. 끝에 닿으면 돌아오고, 끝에 닿으면 돌아온다. 숨 쉴 틈이 없다.<br><br>출발대 위에서 일행이 손을 뻗는다. 이쪽이 지나갈 때마다.`,
          dieText:`마지막 한 뼘까지 기다렸다. 옆에서 오는 것은 세지 않았다.<br><br>수영장 레인이 다 찼다.<br>한 레인이 유난히 마지막 한 뼘에서 옆으로 꺾는다.` },
        ok:`마지막 한 뼘까지 기다렸다. 그 사이 옆 레인 물살도 봤다. 옆 레인은 지금 반대편 끝이다.<br><br>물살이 출발대에 닿기 직전 옆 레인으로 뛰어 내렸다. 옆 레인은 비었다. 이쪽 레인 물살이 출발대를 들이받았다. 물보라가 출발대를 덮었다. 거기 서 있었으면 같이 덮였다.<br>옆 레인 물에서 타일 턱으로 올라섰다. 옆 물살이 돌아오기 전에.<br><br>출발대를 보니 물이 출발대 위에 고였다. 이쪽이 서 있던 데. 웅덩이가 사람 발 모양이다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 출발대 위에서 다리를 묶고 버틴다.', k:'steady', dc:22,
        ok:`출발대 위에서 다리를 넓게 벌리고 섰다. 무게를 낮췄다. 천을 다리와 출발대 손잡이에 감았다.<br><br>물살이 출발대를 들이받았다. 물보라가 가슴까지 왔다. 천이 버텼다. 물살이 끌어내리려다 출발대에 막혀 돌아갔다.<br>다음 물살이 오기 전에 타일 턱을 따라 빠졌다.<br><br>천을 풀었다. 물이 잔뜩 배었다. 짜니 소독약 냄새가 난다.`,
        ng:`물살이 출발대를 넘어왔다. 생각보다 높았다.<br><br>물보라가 얼굴을 덮었다. 숨이 막혔다. 다리가 출발대에서 미끄러졌다. 천이 손잡이에 걸려 매달렸다. 물살이 다리를 당긴다. 한참 매달려 있었다.<br>물살이 지나간 뒤 기어 올라왔다. 팔이 빠질 듯하다. 소독약 물을 먹었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } }
    ] },

  { at:'A2', t:'사감실 앞 — 걸어오는 손',
    x:`사감실 문이 열렸다. 사감이 나온다. 안경. 장부. 열쇠 꾸러미. 물을 헤치며 걷는다. 달리지 않는다.<br><br>
    투우사는 달려드는 것을 상대한다. 사감은 안 달려든다. 걷는다. 걷는 것은 마지막 한 뼘에서 꺾을 수 있다. 손이 길다.<br>
    복도 끝이 막혔다. 사감 옆을 지나야 한다.<br><br>
    안경 너머 눈이 이쪽을 센다. 하나.`,
    o:[
      { l:'① 정면에서 기다렸다가 손이 뻗는 순간 비킨다.', k:'evade', dc:23,
        doom:{ title:'사감', what:'사감 손에 사감실 안으로 끌려 들어갑니다', dc:18, sec:50,
          text:`정면에 섰다. 사감이 걸어온다. 손이 뻗었다. 마지막 한 뼘에서 비켰다.<br><br>사감 손이 꺾였다. 걷는 것은 꺾는다. 손이 손목을 잡았다. 길쭉한 손가락이 손목을 두 번 감는다. 차다.<br>사감이 돌아선다. 사감실 쪽으로. 이쪽을 끈다. 걸음은 느린데 끌리는 힘이 세다. 물이 이쪽을 같이 민다. 사감실 문이 열려 있다. 책상, 장부, 의자 하나. 의자는 이쪽을 향해 빼져 있다.<br><br>사감이 장부를 편다. 연필 끝을 고른다.`,
          dieText:`달려드는 것은 마지막에 못 꺾는다. 걷는 것은 꺾는다. 알고 있었다.<br><br>사감실 의자에 누가 앉아 장부를 정리한다.<br>사감이 둘이 됐다. 하나는 등을 보이지 않는다.` },
        ok:`정면에 섰다. 사감이 걸어온다. 손이 뻗었다. 비키지 않았다. 천을 내밀었다.<br><br>손이 천을 잡았다. 천을 놓았다. 사감이 천을 들여다본다. 회색 천. 장부에 없는 물건이다. 안경을 고쳐 쓰며 천을 본다. 무엇인지 적어야 한다.<br>그 사이 옆을 지났다. 사감은 천을 장부에 적고 있다.<br><br>복도 끝에서 돌아봤다. 사감이 천을 개어 팔에 걸었다. 분실물이다. 찾으려면 사감실로 가야 한다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 천을 사람 모양으로 걸어 두고 빠진다.', k:'luck', dc:22,
        ok:`복도 옷걸이 못에 천을 걸었다. 사람 모양으로 펼쳐서. 천 위에 이쪽 모자를 얹었다.<br><br>사감이 천 앞에서 멈췄다. 하나. 천을 사람으로 셌다. 장부에 적는다. 이상 없음. 그 사이 물속으로 몸을 낮춰 사감 등 뒤로 지났다.<br>사감이 다음 방으로 갔다. 천을 두고.<br><br>천을 걷으러 갔다. 천 밑에 사감 쪽지가 끼워져 있다. 외출 금지.`,
        ng:`천을 걸었는데 사감이 천을 안 셌다. 천 너머를 셌다. 이쪽을.<br><br>하나가 많네. 손이 길게 뻗어 왔다. 물속으로 피했다. 손이 물속까지 따라왔다. 머리채를 잡혔다. 천을 걷어 손에 감아 쳐 냈다.<br>사감 등 뒤로 겨우 빠졌다. 두피가 쓰라리다. 장부에 무엇이 적혔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-24 } },
      { l:'③ 무력을 실어 사감실 문을 밀어 사감을 안에 가둔다.', k:'steady', dc:23, cost:{ might:30 },
        ok:`사감이 사감실 문 앞을 지나는 순간 문을 밀었다. 무력을 실어. 문이 사감 등을 밀며 닫혔다. 사감이 안으로 밀려 들어갔다.<br><br>문을 등으로 막았다. 안에서 문고리가 돈다. 천천히. 열쇠 꾸러미 소리. 이 문 열쇠를 찾는다. 하나씩. 그 사이 일행이 복도를 지나갔다.<br>열쇠 맞는 소리가 났다. 문에서 등을 뗐다. 뛰었다.<br><br>복도 끝에서 들었다. 문이 열리는 소리. 걷는 소리. 달리지 않는다. 달릴 필요가 없다는 듯.`,
        ng:`문을 밀었는데 문 사이에 사감 손이 끼었다.<br><br>길쭉한 손가락이 문틈에서 손목을 잡았다. 문을 닫을수록 세게 쥔다. 손을 뺐다. 손목 살갗이 벗겨졌다. 문이 열렸다. 사감이 나온다.<br>복도를 뛰었다. 손목이 쓰라리다. 등 뒤에서 열쇠 소리가 천천히 따라온다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-16 } }
    ] },

  { at:'A2', t:'강당 — 내려오는 줄',
    x:`강당 관람석에서 학생들이 일어선다. 보이지 않는다. 의자 접히는 소리만 난다. 탁, 탁.<br><br>
    일어선 것들이 줄을 지어 계단을 내려온다. 무대로. 물이 줄 모양으로 밀려 내려온다. 빠르지 않다. 멈추지 않는다.<br>
    이쪽은 계단 통로 한가운데에 서 있다. 줄이 이쪽을 지나가야 한다. 줄에 닿은 것은 줄에 낀다.<br><br>
    투우사는 떼가 지나가는 길에 서 본 적이 있다. 그때보다 조용하다.`,
    o:[
      { l:'① 줄 맨 앞에 천을 비스듬히 펼쳐 줄 전체를 비키게 한다.', k:'evade', dc:23, wake:1,
        ok:`천을 줄 앞에 비스듬히 펼쳤다. 맨 앞이 천에 닿았다. 천을 따라 옆으로 비켰다. 첫 사람이 비키니 다음도 비킨다. 줄은 앞사람을 따른다.<br><br>줄이 이쪽을 비켜 갔다. 한 사람씩. 천 끝을 스치며. 물이 옆으로 흐른다. 마지막 사람까지.<br>줄이 무대로 올라갔다. 이쪽은 통로에 남았다. 아무도 이쪽을 데려가지 않았다.<br><br>여럿을 상대할 때는 맨 앞 하나만 상대하면 된다. 앞을 돌리면 뒤가 따른다. 천 한 번으로 줄 전부를 비켰다. 하나를 비키는 법이 여럿을 비키는 법이 됐다.`,
        ng:`천을 펼쳤는데 맨 앞이 천을 지나쳤다. 천 너머로 그대로.<br><br>줄이 이쪽에 닿았다. 어깨, 팔. 차다. 줄에 낀다. 발이 줄 걸음에 맞춰진다. 무대 쪽으로. 관람석 등받이를 잡았다. 줄이 손가락을 하나씩 떼어 낸다.<br>일행이 허리를 잡아 끌어냈다. 손가락이 다 젖혀졌다. 줄은 무대로 갔다. 이쪽 자리를 비워 둔 채.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-24 } },
      { l:'② 관람석 빈 의자를 펴고 앉아 줄이 지나가길 기다린다.', k:'hide', dc:22,
        ok:`통로 옆 빈 의자에 앉았다. 접힌 의자를 펴고. 관람석에 앉은 것은 관람객이다. 줄은 일어선 것들이다.<br><br>줄이 이쪽 앞을 지나간다. 물이 무릎을 스친다. 누가 이쪽 무릎을 짚고 지나갔다. 실례합니다, 하듯이.<br>다 지나갔다. 일어났다.<br><br>앉았던 의자 등받이에 이름표가 붙어 있다. 물에 번졌다. 17. 의자가 이쪽 체온만큼 따뜻하다. 원래 따뜻했는지도 모른다.`,
        ng:`앉았는데 의자가 이쪽을 안 놓았다. 등받이가 등에 붙었다.<br><br>줄이 지나가다 이쪽 앞에서 멈췄다. 일어나. 같이 가야지. 손이 손목을 잡아당긴다. 의자는 등을 잡고. 양쪽에서 당긴다.<br>천을 휘둘러 손을 쳐 냈다. 의자에서 몸을 뜯어냈다. 등에 의자 자국이 깊다. 줄이 아쉬워하며 내려갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
    ] }
]);
